68	// agentHelpRepoLine resolves the current repo as forge/owner/repo from the
69	// origin remote, returning "" when it can't be determined (no origin / detached
70	// HEAD) so the renderer degrades gracefully rather than erroring.
71	func agentHelpRepoLine(ctx context.Context) string {
72		forge, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
73		if err != nil || forge == "" || owner == "" || repo == "" {
74			return ""
75		}
76		return strings.Join([]string{forge, owner, repo}, "/")
77	}
