79	// runAgentHelp resolves args to a command node and renders it. It is pure (no
80	// git / IO): the caller passes the already-resolved repoLine and trailsEnabled.
81	func runAgentHelp(rootCmd *cobra.Command, args []string, repoLine string, asJSON, trailsEnabled bool) (string, error) {
82		target := rootCmd
83		for _, name := range args {
84			child := agentHelpFindChild(target, name)
85			if child == nil {
86				return "", fmt.Errorf("unknown command %q; run `entire agent-help` for the list of commands", name)
