88			if !trailsEnabled && child.Annotations[agentHelpRequiresTrailsAnnotation] == agentHelpAnnotationEnabled {
89				return "", fmt.Errorf("`%s` is unavailable: trails are not enabled for this repo", child.Name())
90			}
91			target = child
92		}
93		if asJSON {
94			return renderAgentHelpJSON(rootCmd, target, repoLine, trailsEnabled)
95		}
96		if target == rootCmd {
97			return renderAgentHelpTop(rootCmd, repoLine, trailsEnabled), nil
98		}
99		return renderAgentHelpCommand(target, repoLine, trailsEnabled), nil
100	}
