102	// agentHelpFindChild finds a direct child of parent by name or alias, including
103	// hidden commands (so drill-down into e.g. trail works).
104	func agentHelpFindChild(parent *cobra.Command, name string) *cobra.Command {
105		for _, sub := range parent.Commands() {
106			if sub.Name() == name {
107				return sub
108			}
109			for _, alias := range sub.Aliases {
110				if alias == name {
111					return sub
112				}
113			}
114		}
115		return nil
116	}
