127		Name  string `json:"name"`
128		Short string `json:"short"`
129	}
130	
131	type agentHelpJSON struct {
132		Command     string                    `json:"command"`
133		Short       string                    `json:"short,omitempty"`
134		Long        string                    `json:"long,omitempty"`
135		Repo        string                    `json:"repo,omitempty"`
136		Flags       []agentHelpFlagJSON       `json:"flags,omitempty"`
137		Subcommands []agentHelpSubcommandJSON `json:"subcommands,omitempty"`
138	}
139	
140	// renderAgentHelpJSON renders the structured form of a command node.
141	func renderAgentHelpJSON(rootCmd, target *cobra.Command, repoLine string, trailsEnabled bool) (string, error) {
142		doc := agentHelpJSON{
143			Command: target.CommandPath(),
144			Short:   target.Short,
145			Long:    strings.TrimSpace(target.Long),
146			Repo:    repoLine,
147		}
148		if target != rootCmd {
149			collect := func(fs *flag.FlagSet) {
150				fs.VisitAll(func(f *flag.Flag) {
151					if f.Hidden {
152						return
153					}
154					doc.Flags = append(doc.Flags, agentHelpFlagJSON{
155						Name:      f.Name,
156						Shorthand: f.Shorthand,
157						Type:      f.Value.Type(),
158						Default:   f.DefValue,
159						Usage:     f.Usage,
160					})
161				})
162			}
163			collect(target.LocalFlags())
164			collect(target.InheritedFlags())
165		}
166		for _, sub := range agentHelpCommands(target, trailsEnabled) {
167			doc.Subcommands = append(doc.Subcommands, agentHelpSubcommandJSON{Name: sub.Name(), Short: sub.Short})
168		}
169		b, err := json.MarshalIndent(doc, "", "  ")
170		if err != nil {
171			return "", fmt.Errorf("marshal agent-help json: %w", err)
172		}
173		return string(b) + "\n", nil
174	}
175	
176	// agentHelpCommands returns the child commands to advertise to agents: every
177	// visible command plus any hidden command that opts in via agentHelpAnnotation.
178	// The help command itself is never advertised.
179	func agentHelpCommands(parent *cobra.Command, trailsEnabled bool) []*cobra.Command {
180		var out []*cobra.Command
181		for _, sub := range parent.Commands() {
182			if sub.Name() == "help" || sub.Deprecated != "" {
183				continue
184			}
185			if sub.Hidden && sub.Annotations[agentHelpAnnotation] != agentHelpAnnotationEnabled {
186				continue
187			}
188			if !trailsEnabled && sub.Annotations[agentHelpRequiresTrailsAnnotation] == agentHelpAnnotationEnabled {
189				continue
190			}
191			out = append(out, sub)
192		}
193		return out
194	}
195	
196	// agentHelpRepoBlock formats the auto-detected repo line, degrading gracefully
197	// when the repo can't be resolved (no origin / detached HEAD) rather than
198	// implying a repo that isn't there.
199	func agentHelpRepoBlock(repoLine string) string {
200		if strings.TrimSpace(repoLine) == "" {
201			return "Current repo: not auto-detectable here (no origin remote / detached HEAD); pass --repo explicitly.\n"
202		}
203		return "Current repo: " + repoLine + "  (auto-detected from origin; pass --repo only for a DIFFERENT repo)\n"
204	}
205	
206	// renderAgentHelpCommand renders one resolved command node for an agent: its
207	// path + Short, its Long description, the auto-detected repo line, its live flag
208	// usages (hidden flags are skipped by cobra), and its advertised subcommands.
209	func renderAgentHelpCommand(cmd *cobra.Command, repoLine string, trailsEnabled bool) string {
210		var b strings.Builder
211		fmt.Fprintf(&b, "%s — %s\n", cmd.CommandPath(), cmd.Short)
212		if long := strings.TrimSpace(cmd.Long); long != "" && long != strings.TrimSpace(cmd.Short) {
213			b.WriteString(long)
214			b.WriteString("\n")
215		}
216		b.WriteString("\n")
217		b.WriteString(agentHelpRepoBlock(repoLine))
218	
219		// LocalFlags()/InheritedFlags() trigger cobra's persistent-flag merge (plain
220		// Flags() does not without Execute) and skip hidden flags in FlagUsages.
221		if usages := strings.TrimRight(cmd.LocalFlags().FlagUsages(), "\n"); usages != "" {
222			b.WriteString("\nFlags:\n")
223			b.WriteString(usages)
224			b.WriteString("\n")
225		}
226		if usages := strings.TrimRight(cmd.InheritedFlags().FlagUsages(), "\n"); usages != "" {
227			b.WriteString("\nInherited flags:\n")
228			b.WriteString(usages)
229			b.WriteString("\n")
230		}
231	
232		if subs := agentHelpCommands(cmd, trailsEnabled); len(subs) > 0 {
233			names := make([]string, 0, len(subs))
234			for _, sub := range subs {
235				names = append(names, sub.Name())
236			}
237			fmt.Fprintf(&b, "\nSubcommands: %s\n", strings.Join(names, " · "))
238			fmt.Fprintf(&b, "Next:  entire agent-help %s <subcommand>\n", strings.TrimPrefix(cmd.CommandPath(), cmd.Root().Name()+" "))
239		}
240		return b.String()
241	}
242	
243	// renderAgentHelpTop renders the top-level agent-facing overview: the curated
244	// intro + rule, the auto-detected repo line, and a live map of the advertised
245	// commands (their Short help), ending with the drill-down pointer.
246	func renderAgentHelpTop(rootCmd *cobra.Command, repoLine string, trailsEnabled bool) string {
247		var b strings.Builder
248		b.WriteString(agentHelpOverview)
249		b.WriteString("\n\n")
250		b.WriteString(agentHelpRepoBlock(repoLine))
251		b.WriteString("\nWhen to use entire:\n")
252		for _, sub := range agentHelpCommands(rootCmd, trailsEnabled) {
253			fmt.Fprintf(&b, "  %-12s %s\n", sub.Name(), sub.Short)
254		}
255		// Use an example command that is actually advertised here (trail is gated on
256		// trails being enabled), so we never point at a command the agent can't use.
257		example := "checkpoint"
258		if trailsEnabled {
259			example = "trail"
260		}
261		fmt.Fprintf(&b, "\nDrill in for exact, currently-installed flags:  entire agent-help <command>  (e.g. entire agent-help %s)\n", example)
262		b.WriteString("Add --json for structured output.\n")
263		return b.String()
264	}
