9	)
10	
11	// managedScaffoldStatus is the outcome of writing an Entire-managed scaffold file
12	// (a search skill, an agent-help skill, ...). Statuses are shared so each
13	// feature's reporter can switch on them.
14	type managedScaffoldStatus string
15	
16	const (
17		managedScaffoldUnsupported     managedScaffoldStatus = "unsupported"
18		managedScaffoldCreated         managedScaffoldStatus = "created"
19		managedScaffoldUpdated         managedScaffoldStatus = "updated"
20		managedScaffoldUnchanged       managedScaffoldStatus = "unchanged"
21		managedScaffoldSkippedConflict managedScaffoldStatus = "skipped_conflict"
22	)
23	
24	type managedScaffoldResult struct {
25		Status  managedScaffoldStatus
26		RelPath string
27	}
28	
29	// writeManagedScaffold writes content to targetPath idempotently: it creates the
30	// file when absent, leaves it untouched (Unchanged) when identical, rewrites it
31	// (Updated) only when Entire already manages it, and refuses to clobber an
32	// unmanaged file (SkippedConflict). isManaged reports whether existing bytes
33	// carry this feature's management marker.
34	func writeManagedScaffold(targetPath, relPath string, content []byte, isManaged func([]byte) bool) (managedScaffoldResult, error) {
35		existingData, err := os.ReadFile(targetPath) //nolint:gosec // target path is derived from repo root + fixed relative path
36		if err == nil {
37			if !isManaged(existingData) {
38				return managedScaffoldResult{Status: managedScaffoldSkippedConflict, RelPath: relPath}, nil
39			}
40			if bytes.Equal(existingData, content) {
41				return managedScaffoldResult{Status: managedScaffoldUnchanged, RelPath: relPath}, nil
42			}
43			if err := os.WriteFile(targetPath, content, 0o600); err != nil {
44				return managedScaffoldResult{}, fmt.Errorf("update managed scaffold: %w", err)
45			}
46			return managedScaffoldResult{Status: managedScaffoldUpdated, RelPath: relPath}, nil
47		}
48		if !errors.Is(err, os.ErrNotExist) {
49			return managedScaffoldResult{}, fmt.Errorf("read managed scaffold: %w", err)
50		}
51	
52		if err := os.MkdirAll(filepath.Dir(targetPath), 0o750); err != nil {
53			return managedScaffoldResult{}, fmt.Errorf("create managed scaffold directory: %w", err)
54		}
55		if err := os.WriteFile(targetPath, content, 0o600); err != nil {
56			return managedScaffoldResult{}, fmt.Errorf("write managed scaffold: %w", err)
57		}
58		return managedScaffoldResult{Status: managedScaffoldCreated, RelPath: relPath}, nil
59	}
