108	// ParseURL parses a git remote URL (SSH SCP-style or HTTPS) into its components.
109	func ParseURL(rawURL string) (*Info, error) {
110		rawURL = strings.TrimSpace(rawURL)
111	
112		if strings.Contains(rawURL, ":") && !strings.Contains(rawURL, "://") {
113			parts := strings.SplitN(rawURL, ":", 2)
114			if len(parts) != 2 {
115				return nil, fmt.Errorf("invalid SSH URL: %s", RedactURL(rawURL))
116			}
117	
118			hostPart := parts[0]
119			_, host, found := strings.Cut(hostPart, "@")
120			if !found {
121				host = hostPart
122			}
123	
124			pathPart := strings.TrimSuffix(parts[1], ".git")
125			owner, repo, err := splitOwnerRepo(pathPart)
126			if err != nil {
127				return nil, err
128			}
129	
130			return &Info{Protocol: ProtocolSSH, Host: host, Forge: hostToForge[host], Owner: owner, Repo: repo}, nil
131		}
132	
133		u, err := url.Parse(rawURL)
134		if err != nil {
135			return nil, fmt.Errorf("invalid URL: %s", RedactURL(rawURL))
136		}
137		if u.Scheme == "" {
138			return nil, fmt.Errorf("no protocol in URL: %s", RedactURL(rawURL))
139		}
140	
141		pathPart := strings.TrimPrefix(u.Path, "/")
142		forge := hostToForge[u.Hostname()]
143		if u.Scheme == ProtocolEntire {
144			// entire:// URLs encode the forge as the first path segment.
145			forge, pathPart = splitForgePrefix(pathPart)
146		}
147		owner, repo, err := splitOwnerRepo(pathPart)
148		if err != nil {
149			return nil, err
150		}
151	
152		return &Info{Protocol: u.Scheme, Host: u.Hostname(), Port: u.Port(), Forge: forge, Owner: owner, Repo: repo}, nil
153	}
154	
155	// splitForgePrefix returns the leading forge/namespace segment of an entire://
156	// URL path and the remainder (e.g. "gh/owner/repo" -> "gh", "owner/repo").
157	// Paths without a separator are returned with an empty forge.
158	func splitForgePrefix(path string) (forge, rest string) {
159		if forge, rest, found := strings.Cut(path, "/"); found {
160			return forge, rest
161		}
162		return "", path
163	}
164	
165	// RedactURL removes credentials and query parameters from a URL for safe logging.
166	// SCP-style SSH URLs (e.g., git@github.com:org/repo.git) are returned as-is
167	// since they contain no embedded credentials.
168	func RedactURL(rawURL string) string {
169		// SCP-style SSH: user@host:path — no credentials to redact.
170		if strings.Contains(rawURL, ":") && !strings.Contains(rawURL, "://") {
171			return rawURL
172		}
173	
174		u, err := url.Parse(rawURL)
175		if err != nil {
176			return "<unparseable>"
177		}
178		u.User = nil
179		u.RawQuery = ""
180		return u.Scheme + "://" + u.Host + u.Path
181	}
182	
183	// ExtractOwnerFromRemoteURL extracts the owner component from a git remote URL.
184	// Returns an empty string if the URL cannot be parsed.
185	func ExtractOwnerFromRemoteURL(rawURL string) string {
186		info, err := ParseURL(rawURL)
187		if err != nil {
188			return ""
189		}
190		return info.Owner
191	}
192	
193	// ResolveRemoteRepo returns the forge identifier, owner, and repo name for the
194	// given git remote. The forge is the short id used by the trails API ("gh",
195	// "et", ...); it is derived from the hostname for direct git URLs or from the
196	// path prefix on entire:// URLs. It is empty for unrecognized hosts.
197	// For example, git@github.com:org/my-repo.git returns ("gh", "org", "my-repo").
198	func ResolveRemoteRepo(ctx context.Context, remoteName string) (forge, owner, repo string, err error) {
199		rawURL, err := GetRemoteURL(ctx, remoteName)
200		if err != nil {
201			return "", "", "", fmt.Errorf("get remote URL for %q: %w", remoteName, err)
202		}
203		info, err := ParseURL(rawURL)
204		if err != nil {
205			return "", "", "", fmt.Errorf("parse remote URL: %w", err)
206		}
207		return info.Forge, info.Owner, info.Repo, nil
208	}
209	
210	func splitOwnerRepo(path string) (string, string, error) {
211		path = strings.TrimSuffix(path, ".git")
212		parts := strings.SplitN(path, "/", 2)
213		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
214			return "", "", fmt.Errorf("cannot parse owner/repo from path: %s", path)
215		}
216		return parts[0], parts[1], nil
217	}
