211	func splitOwnerRepo(path string) (string, string, error) {
212		path = strings.TrimSuffix(path, ".git")
213		parts := strings.SplitN(path, "/", 2)
214		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
215			return "", "", fmt.Errorf("cannot parse owner/repo from path: %s", path)
216		}
217		// Reject control characters (newlines, ANSI escapes, ...). The SCP-style
218		// branch in ParseURL bypasses net/url.Parse's built-in control-char
219		// rejection, so a crafted origin URL could otherwise smuggle a newline or
220		// escape into owner/repo and, via plain-text consumers like `entire
221		// agent-help`, into an agent's context or a user's terminal. This shared
222		// chokepoint protects every caller; the tainted bytes are not echoed back.
223		if strings.IndexFunc(parts[0]+"/"+parts[1], func(r rune) bool { return unicode.IsControl(r) }) >= 0 {
224			return "", "", errors.New("invalid control character in remote owner/repo")
225		}
226		return parts[0], parts[1], nil
