import json, glob, collections, os

files = sorted(glob.glob(os.path.expanduser("~/.codex/sessions/2026/06/**/rollout-*.jsonl"), recursive=True))
hits = collections.Counter()
examples = {}

for f in files:
    try:
        fh = open(f)
    except OSError:
        continue
    with fh:
        for line in fh:
            low = line.lower()
            if 'agent' not in low and 'spawn' not in low:
                continue
            try:
                o = json.loads(line)
            except Exception:
                continue
            p = o.get('payload', {})
            if not isinstance(p, dict):
                continue
            ptype = p.get('type', '')
            name = p.get('name') or (p.get('tool') if isinstance(p.get('tool'), str) else '')
            key = None
            if ptype in ('function_call', 'custom_tool_call', 'local_shell_call', 'tool_call', 'function_call_output') and name:
                if 'agent' in name.lower() or 'spawn' in name.lower():
                    key = f"{ptype}:{name}"
            if o.get('type') == 'event_msg':
                et = p.get('type', '')
                if any(w in et.lower() for w in ('agent', 'spawn', 'task')):
                    key = f"event_msg:{et}"
            if key:
                hits[key] += 1
                if key not in examples:
                    ex = {k: (v if not isinstance(v, str) else v[:160]) for k, v in p.items()
                          if k in ('type', 'name', 'arguments', 'call_id', 'status', 'agent', 'agent_name',
                                   'thread_id', 'session_id', 'result', 'input', 'output')}
                    examples[key] = (os.path.basename(f), ex)

print("=== agent/spawn-related payloads (count : key) ===")
for k, v in hits.most_common():
    print(v, k)
print("\n=== one example per key ===")
for k, (fn, ex) in examples.items():
    print(f"\n## {k}  [{fn}]")
    print(json.dumps(ex, indent=1)[:1100])

