413	func sanitizeRolloutLine(lineData []byte) ([]byte, bool) {
414		var line rolloutLine
415		if err := json.Unmarshal(lineData, &line); err != nil {
416			return lineData, true
417		}
418		if line.Type == "compacted" {
419			return sanitizeCompactedLine(line)
420		}
421		if line.Type != rolloutLineTypeResponseItem {
422			return lineData, true
423		}
424	
425		var payload map[string]any
426		if err := json.Unmarshal(line.Payload, &payload); err != nil {
427			return lineData, true
428		}
429	
430		itemType, ok := payload["type"].(string)
431		if !ok {
432			return lineData, true
433		}
434		switch itemType {
435		case "reasoning":
436			delete(payload, "encrypted_content")
437		case "compaction", "compaction_summary":
438			return nil, false
439		default:
440			return lineData, true
441		}
442	
443		encodedPayload, err := json.Marshal(payload)
444		if err != nil {
445			return lineData, true
446		}
447		line.Payload = encodedPayload
448	
449		encodedLine, err := json.Marshal(line)
450		if err != nil {
451			return lineData, true
452		}
453		return encodedLine, true
