456	func sanitizeCompactedLine(line rolloutLine) ([]byte, bool) {
457		var payload map[string]any
458		if err := json.Unmarshal(line.Payload, &payload); err != nil {
459			return mustMarshalRolloutLine(line), true
460		}
461	
462		replacementHistory, ok := payload["replacement_history"].([]any)
463		if !ok {
464			return mustMarshalRolloutLine(line), true
465		}
466	
467		sanitizedHistory := sanitizeHistoryItems(replacementHistory)
468		payload["replacement_history"] = sanitizedHistory
469	
470		encodedPayload, err := json.Marshal(payload)
471		if err != nil {
472			return mustMarshalRolloutLine(line), true
473		}
474		line.Payload = encodedPayload
475	
476		return mustMarshalRolloutLine(line), true
477	}
