479	func sanitizeHistoryItems(items []any) []any {
480		sanitized := make([]any, 0, len(items))
481		for _, item := range items {
482			itemMap, ok := item.(map[string]any)
483			if !ok {
484				sanitized = append(sanitized, item)
485				continue
486			}
487	
488			itemType, ok := itemMap["type"].(string)
489			if !ok {
490				sanitized = append(sanitized, itemMap)
491				continue
492			}
493			switch itemType {
494			case "reasoning":
495				delete(itemMap, "encrypted_content")
496			case "compaction", "compaction_summary":
497				continue
498			}
499	
500			sanitized = append(sanitized, itemMap)
501		}
502		return sanitized
503	}
