513	// splitJSONL splits JSONL bytes into individual lines, skipping empty lines.
514	func splitJSONL(data []byte) [][]byte {
515		var lines [][]byte
516		for _, line := range bytes.Split(data, []byte("\n")) {
517			line = bytes.TrimSpace(line)
518			if len(line) > 0 {
519				lines = append(lines, line)
520			}
521		}
522		return lines
523	}
