525	func parseSessionStartTime(data []byte) (time.Time, error) {
526		lines := splitJSONL(data)
527		if len(lines) == 0 {
528			return time.Time{}, errors.New("transcript is empty")
529		}
530	
531		var line rolloutLine
532		if err := json.Unmarshal(lines[0], &line); err != nil {
533			return time.Time{}, fmt.Errorf("parse first transcript line: %w", err)
534		}
535		if line.Type != "session_meta" {
536			return time.Time{}, fmt.Errorf("first transcript line is %q, want session_meta", line.Type)
537		}
538	
539		var meta sessionMetaPayload
540		if err := json.Unmarshal(line.Payload, &meta); err != nil {
541			return time.Time{}, fmt.Errorf("parse session_meta payload: %w", err)
542		}
543		if meta.Timestamp == "" {
544			return time.Time{}, errors.New("session_meta timestamp is empty")
545		}
546	
547		startTime, err := time.Parse(time.RFC3339Nano, meta.Timestamp)
548		if err != nil {
549			return time.Time{}, fmt.Errorf("parse session_meta timestamp %q: %w", meta.Timestamp, err)
550		}
551		return startTime, nil
552	}
