299	func addHook(groups []MatcherGroup, command string) []MatcherGroup {
300		entry := HookEntry{
301			Type:    "command",
302			Command: command,
303			Timeout: 30,
304		}
305	
306		// Add to an existing group with null matcher, or create a new one
307		for i, group := range groups {
308			if group.Matcher == nil {
309				groups[i].Hooks = append(groups[i].Hooks, entry)
310				return groups
311			}
312		}
313		return append(groups, MatcherGroup{
314			Matcher: nil,
315			Hooks:   []HookEntry{entry},
316		})
317	}
