334	func removeEntireHooks(groups []MatcherGroup) []MatcherGroup {
335		result := make([]MatcherGroup, 0, len(groups))
336		for _, group := range groups {
337			filtered := make([]HookEntry, 0, len(group.Hooks))
338			for _, hook := range group.Hooks {
339				if !isEntireHook(hook.Command) {
340					filtered = append(filtered, hook)
341				}
342			}
343			if len(filtered) > 0 {
344				group.Hooks = filtered
345				result = append(result, group)
346			}
347		}
348		return result
