351	// configFileName is the Codex config file name.
352	const configFileName = "config.toml"
353	
354	// featureLine is the TOML line that enables the hooks feature. The flag was
355	// renamed from `codex_hooks` to `hooks` in Codex 0.129.0; the old name is
356	// still accepted as a legacy alias but emits a deprecation warning at
357	// every startup. ensureProjectFeatureEnabled rewrites the legacy form when
358	// it sees it.
359	const (
360		featureLine       = "hooks = true"
361		legacyFeatureLine = "codex_hooks = true"
362	)
363	
364	// ensureProjectFeatureEnabled writes features.hooks = true to the
365	// project-level .codex/config.toml. This keeps the feature flag per-repo.
366	// Replaces the deprecated codex_hooks = true line if it's present.
367	func ensureProjectFeatureEnabled(repoRoot string) error {
368		configPath := filepath.Join(repoRoot, ".codex", configFileName)
369	
370		data, err := os.ReadFile(configPath) //nolint:gosec // path constructed from repo root
371		if err != nil && !os.IsNotExist(err) {
372			return fmt.Errorf("failed to read config.toml: %w", err)
373		}
374	
375		content := string(data)
376		hasNew := containsFeatureLine(content, featureLine)
377		hasLegacy := containsFeatureLine(content, legacyFeatureLine)
378		switch {
379		case hasNew && hasLegacy:
380			content = stripLegacyFeatureLine(content)
381		case hasNew:
382			return nil
383		case hasLegacy:
384			content = strings.Replace(content, legacyFeatureLine, featureLine, 1)
385		case strings.Contains(content, "[features]"):
386			content = strings.Replace(content, "[features]", "[features]\n"+featureLine, 1)
387		default:
388			if len(content) > 0 && !strings.HasSuffix(content, "\n") {
389				content += "\n"
390			}
391			content += "\n[features]\n" + featureLine + "\n"
392		}
393	
394		if err := os.MkdirAll(filepath.Dir(configPath), 0o750); err != nil {
395			return fmt.Errorf("failed to create .codex directory: %w", err)
396		}
397		if err := os.WriteFile(configPath, []byte(content), 0o600); err != nil { //nolint:gosec // path constructed from repo root
398			return fmt.Errorf("failed to write config.toml: %w", err)
399		}
400		return nil
401	}
402	
403	// containsFeatureLine checks for an exact line match. A plain
404	// strings.Contains is wrong because "hooks = true" is a substring of
405	// "codex_hooks = true" — without the line-boundary anchor we'd treat the
406	// legacy form as if the new form was already present.
407	func containsFeatureLine(content, line string) bool {
408		for _, raw := range strings.Split(content, "\n") {
409			if strings.TrimSpace(raw) == line {
410				return true
411			}
412		}
413		return false
414	}
415	
416	// stripLegacyFeatureLine removes the deprecated `codex_hooks = true` line
417	// from a TOML config string, dropping a trailing blank line so the file
418	// stays tidy. The new `hooks = true` is added separately by the caller.
419	func stripLegacyFeatureLine(content string) string {
420		idx := strings.Index(content, legacyFeatureLine)
421		if idx < 0 {
422			return content
423		}
424		end := idx + len(legacyFeatureLine)
425		if end < len(content) && content[end] == '\n' {
426			end++
427		}
428		return content[:idx] + content[end:]
429	}
