export const meta = {
  name: 'bugbot-codex-subagents',
  description: 'Adversarial bug audit of the Codex subagent change (codex-subagent-tracking branch)',
  phases: [
    { title: 'Find' },
    { title: 'Verify' },
    { title: 'Synthesize' },
  ],
}

const CONTEXT = `You are a meticulous bug-bot reviewing a Go change on the entire CLI repo at /Users/suhaan/devenv/cli.

The change (branch \`codex-subagent-tracking\`, 1 commit on top of \`origin/main\`) adds Codex subagent tracking: parse Codex SubagentStart/SubagentStop hooks into SubagentStart/SubagentEnd events, install those hooks, implement SubagentAwareExtractor (read child rollouts → merge files + sum SubagentTokens), a SubagentTranscriptResolver framework interface, and trust/drift detection for the new hooks.

INSPECT:
- Diff: \`cd /Users/suhaan/devenv/cli && git --no-pager diff origin/main...codex-subagent-tracking\`
- ALWAYS read the FULL changed files (and neighbors they call into) — review the real code, not just diff hunks. Use Read/Grep.

CHANGED FILES (non-test):
  cmd/entire/cli/agent/agent.go              (new SubagentTranscriptResolver interface)
  cmd/entire/cli/agent/capabilities.go       (As-helper)
  cmd/entire/cli/lifecycle.go                (subagent-end handler: resolver wiring)
  cmd/entire/cli/agent/codex/types.go        (subagent hook payload structs)
  cmd/entire/cli/agent/codex/lifecycle.go    (ParseHookEvent subagent cases, ResolveSubagentTranscript)
  cmd/entire/cli/agent/codex/hooks.go        (install/uninstall subagent hooks)
  cmd/entire/cli/agent/codex/transcript.go   (SubagentAwareExtractor: ExtractAllModifiedFiles, CalculateTotalTokenUsage, extractSpawnedAgentIDs, readSubagentRollouts, extractFilesFromBytes)
  cmd/entire/cli/agent/codex/trust.go        (subagent hooks in gap/drift detection)
  cmd/entire/cli/agent/codex/AGENT.md, docs/architecture/agent-guide.md (docs)
TESTS: codex/{subagent_test.go, hooks_test.go, trust_test.go}, doctor_test.go

BAR: report only GENUINE bugs a serious code-review bot would flag — correctness, nil/panic, error-handling, behavior/semantics changes vs the code being modified, resource leaks, concurrency, security, API/contract misuse, and test correctness (assertions that don't test what they claim, wrong fixtures, flake). Do NOT report style/naming/subjective preferences. Ground EVERY finding in a real file:line and give a concrete fix.`

const FINDINGS_SCHEMA = {
  type: 'object', additionalProperties: false, required: ['findings'],
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        required: ['id', 'title', 'file', 'line', 'severity', 'description', 'fix', 'confidence'],
        properties: {
          id: { type: 'string' }, title: { type: 'string' },
          file: { type: 'string' }, line: { type: 'string' },
          severity: { type: 'string', enum: ['blocker', 'major', 'minor'] },
          description: { type: 'string' }, fix: { type: 'string' },
          confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
        },
      },
    },
  },
}

const VERDICT_SCHEMA = {
  type: 'object', additionalProperties: false,
  required: ['isReal', 'reasoning', 'fixCorrect', 'severityAdjusted'],
  properties: {
    isReal: { type: 'boolean', description: 'true only if confirmed a real bug by reading the actual code' },
    reasoning: { type: 'string' },
    fixCorrect: { type: 'boolean' },
    fixNotes: { type: 'string' },
    severityAdjusted: { type: 'string', enum: ['blocker', 'major', 'minor', 'invalid'] },
  },
}

const LENSES = [
  { key: 'correctness', focus: 'LOGIC/CORRECTNESS. Wrong field mapping in ParseHookEvent (agent_id/agent_type/transcript paths), inverted conditions, off-by-one in extractFilesFromBytes line offset handling, extractSpawnedAgentIDs matching the wrong tool calls or missing/spurious ids, the resolver picking the wrong path, the hooks.go install count/marshal logic. Does each method do what its name/contract says?' },
  { key: 'semantics', focus: 'BEHAVIOR/SEMANTICS CHANGES vs the code being modified. Compare CalculateTotalTokenUsage to the existing CalculateTokenUsage it wraps: does it preserve the (nil, nil) "no data" return, or does it now return a non-nil empty &TokenUsage{} where the original returned nil (and does that matter downstream in agent/token_usage.go / lifecycle.go)? Does ExtractAllModifiedFiles preserve ordering/dedup semantics? Did the lifecycle.go handler change alter behavior for non-Codex agents (Claude/Droid) in any case?' },
  { key: 'nil-edge', focus: 'NIL/PANIC/EDGE. nil Event, nil Metadata map access, empty transcriptData, missing child rollout files, GetSessionDir error, a child id that resolves to the parent or to a non-rollout file, malformed JSON lines, very large rollouts. Trace each new code path for a nil deref or wrong empty-state result.' },
  { key: 'resource', focus: 'RESOURCE/EFFICIENCY/CONCURRENCY. Unclosed files, reading the same child rollouts twice (ExtractAllModifiedFiles and CalculateTotalTokenUsage both call readSubagentRollouts, and the framework calls both at turn-end → duplicate parse+read+IO), unbounded memory from reading all child rollouts, any shared-state races. Is the duplicate I/O a real concern worth fixing?' },
  { key: 'security', focus: 'SECURITY. extractSpawnedAgentIDs feeds ids into findRolloutBySessionID globbing — is the ValidateAgentSessionID gate sufficient to prevent path traversal / glob injection? Can a crafted parent rollout cause reads outside the sessions dir? agent_transcript_path from the SubagentStop hook flows into reads — is it validated/bounded? Any unvalidated path from hook payload to os.ReadFile.' },
  { key: 'contract', focus: 'API/CONTRACT/CONVENTION. SubagentTranscriptResolver interface + As-helper correctness (does the handler call it correctly, is the type assertion right?). hooks.go: are SubagentStart/SubagentStop added to AreHooksInstalled consistently, and is that intentional or a gap? Cobra/JSON struct-tag correctness in types.go. Does trust.go now correctly include subagent events everywhere it must (declaredCodexEvents AND MissingEntireHooks)? Any place the new hooks are half-wired.' },
  { key: 'tests', focus: 'TEST CORRECTNESS. Do the new/updated tests actually assert the right thing? Token-math assertions in subagent_test.go (recompute by hand: child1 input100/cached20/out50, child2 input200/cached0/out40 → fresh-input = input-cached). Do doctor_test/trust_test fixtures match the new 6-hook canonical set? Any test that would pass even if the feature were broken (weak assertions), or t.Parallel misuse with t.Setenv, or fixtures that do not exercise the claimed path.' },
]

phase('Find')
log('Bug-bot round: 7 lenses, each finding adversarially verified...')

const reviewed = await pipeline(
  LENSES,
  (d) => agent(`${CONTEXT}\n\n=== LENS: ${d.key} ===\n${d.focus}\n\nReport all genuine bugs for this lens.`,
    { label: `find:${d.key}`, phase: 'Find', schema: FINDINGS_SCHEMA }),
