    agent(`${CONTEXT}\n\n=== ADVERSARIAL VERIFICATION ===\nA "${d.key}" reviewer reported this. REFUTE it: read the ACTUAL code at the cited location + surrounding context. Default isReal=false unless the bug is confirmed by the real code. Check the proposed fix is correct and wouldn't break behavior/tests.\n\nFINDING\n title: ${f.title}\n at: ${f.file}:${f.line}\n severity: ${f.severity}\n description: ${f.description}\n proposed fix: ${f.fix}`,
      { label: `verify:${d.key}:${f.id}`, phase: 'Verify', schema: VERDICT_SCHEMA })
      .then((v) => ({ ...f, lens: d.key, verdict: v }))
  ))
)

