12	// TestSubagentAccumulation_Issue591 reproduces the issue #591 shape: multiple
13	// subagent sessions accumulate as ENDED. The fix is eager-condense-on-stop:
14	// subagents with no uncommitted files at stop time are marked FullyCondensed
15	// immediately, so PostCommit skips them entirely on all subsequent commits.
16	//
17	// Scenario:
18	// 1. Parent session spawns 4 subagents; each creates + commits its own file
19	// 2. Each subagent ends (stop hook runs → CondenseAndMarkFullyCondensed marks them FullyCondensed)
20	// 3. Parent commits parent_work.go — PostCommit skips all FullyCondensed subagents
21	// 4. Follow-up commit — subagents remain FullyCondensed and skipped
22	func TestSubagentAccumulation_Issue591(t *testing.T) {
23		t.Parallel()
24	
25		env := NewFeatureBranchEnv(t)
26	
27		type subagentInfo struct {
28			SessionID string
29			File      string
30		}
31	
32		t.Log("Phase 1: start parent session and create subagent sessions with committed files")
33	
34		parent := env.NewSession()
35		if err := env.SimulateUserPromptSubmit(parent.ID); err != nil {
36			t.Fatalf("SimulateUserPromptSubmit for parent failed: %v", err)
37		}
38		parent.TranscriptBuilder.AddUserMessage("Use subagents to create files, then create the parent file.")
39	
40		const numSubagents = 4
41		subagents := make([]subagentInfo, 0, numSubagents)
42	
43		for i := 0; i < numSubagents; i++ {
44			sub := env.NewSession()
45			file := fmt.Sprintf("subagent_work_%d.go", i)
46			content := fmt.Sprintf("package main\n\nfunc SubagentWork%d() {}\n", i)
47	
48			if err := env.SimulateUserPromptSubmit(sub.ID); err != nil {
49				t.Fatalf("SimulateUserPromptSubmit for subagent %d failed: %v", i, err)
50			}
51	
52			env.WriteFile(file, content)
53			sub.CreateTranscript("Create "+file, []FileChange{
54				{Path: file, Content: content},
55			})
56	
57			// Commit the subagent's file BEFORE stopping, so FilesTouched is empty at stop time.
58			// This allows CondenseAndMarkFullyCondensed to eagerly condense at stop.
59			env.GitAdd(file)
60			env.GitCommitWithShadowHooks("Add "+file+" from subagent", file)
61	
62			if err := env.SimulateStop(sub.ID, sub.TranscriptPath); err != nil {
63				t.Fatalf("SimulateStop for subagent %d failed: %v", i, err)
64			}
65			if err := env.SimulateSessionEnd(sub.ID); err != nil {
66				t.Fatalf("SimulateSessionEnd for subagent %d failed: %v", i, err)
67			}
68	
69			// Verify eager-condense-on-stop marked the subagent FullyCondensed
70			state, err := env.GetSessionState(sub.ID)
71			if err != nil {
72				t.Fatalf("GetSessionState for subagent %d failed: %v", i, err)
73			}
74			if state == nil {
75				t.Fatalf("subagent %d session state missing after stop", i)
76			}
77			if state.Phase != session.PhaseEnded {
78				t.Fatalf("subagent %d phase = %s, want ended", i, state.Phase)
79			}
80			if !state.FullyCondensed {
81				t.Fatalf("subagent %d should be FullyCondensed after eager-condense-on-stop (FilesTouched was empty)", i)
82			}
83	
84			taskToolUseID := fmt.Sprintf("toolu_parent_subagent_%d", i)
85			parent.TranscriptBuilder.AddTaskToolUse(taskToolUseID, "Create "+file)
86			parent.TranscriptBuilder.AddTaskToolResult(taskToolUseID, sub.ID)
87	
88			subagents = append(subagents, subagentInfo{
89				SessionID: sub.ID,
90				File:      file,
91			})
92		}
93	
94		t.Log("Phase 2: parent commits its own work — PostCommit should skip all FullyCondensed subagents")
95	
96		parentFile := "parent_work.go"
97		parentContent := "package main\n\nfunc ParentWork() {}\n"
98		env.WriteFile(parentFile, parentContent)
99		parentToolUseID := parent.TranscriptBuilder.AddToolUse("mcp__acp__Write", parentFile, parentContent)
100		parent.TranscriptBuilder.AddToolResult(parentToolUseID)
101		parent.TranscriptBuilder.AddAssistantMessage("Done.")
102		if err := parent.TranscriptBuilder.WriteToFile(parent.TranscriptPath); err != nil {
103			t.Fatalf("failed to write parent transcript: %v", err)
104		}
105	
106		if err := env.SimulateStop(parent.ID, parent.TranscriptPath); err != nil {
107			t.Fatalf("SimulateStop for parent failed: %v", err)
108		}
109	
110		env.GitCommitWithShadowHooks("Parent commit", parentFile)
111	
112		t.Log("Phase 3: verify FullyCondensed subagents were skipped or cleaned up by PostCommit")
113	
114		for i, sub := range subagents {
115			state, err := env.GetSessionState(sub.SessionID)
116			if err != nil {
117				t.Fatalf("GetSessionState after parent commit for subagent %d failed: %v", i, err)
118			}
119			// State may be nil: listAllSessionStates cleans up ENDED sessions whose
120			// shadow branch was deleted and LastCheckpointID is empty. This is expected
121			// for sessions that were eagerly condensed at stop time (shadow branch cleaned
122			// up before PostCommit could set LastCheckpointID).
123			if state == nil {
124				t.Logf("subagent %d state cleaned up after parent commit — OK (eagerly condensed)", i)
125				continue
126			}
127			if state.Phase != session.PhaseEnded {
128				t.Fatalf("subagent %d phase after parent commit = %s, want ended", i, state.Phase)
129			}
130			if !state.FullyCondensed {
131				t.Fatalf("subagent %d should remain FullyCondensed after parent commit", i)
132			}
133		}
134	
135		t.Log("Phase 4: make another unrelated commit and verify fully-condensed subagents stay skipped")
136	
137		followUp := env.NewSession()
138		if err := env.SimulateUserPromptSubmit(followUp.ID); err != nil {
139			t.Fatalf("SimulateUserPromptSubmit for follow-up session failed: %v", err)
140		}
141	
142		followUpFile := "follow_up.go"
143		followUpContent := "package main\n\nfunc FollowUp() {}\n"
144		env.WriteFile(followUpFile, followUpContent)
145		followUp.CreateTranscript("Create "+followUpFile, []FileChange{
146			{Path: followUpFile, Content: followUpContent},
147		})
148		if err := env.SimulateStop(followUp.ID, followUp.TranscriptPath); err != nil {
149			t.Fatalf("SimulateStop for follow-up session failed: %v", err)
150		}
151	
152		env.GitCommitWithShadowHooks("Follow-up commit", followUpFile)
153	
154		for i, sub := range subagents {
155			state, err := env.GetSessionState(sub.SessionID)
156			if err != nil {
157				t.Fatalf("GetSessionState after follow-up commit for subagent %d failed: %v", i, err)
158			}
159			if state == nil {
160				// Already cleaned up in Phase 3 — still gone, which is correct
161				continue
162			}
163			if !state.FullyCondensed {
164				t.Fatalf("subagent %d should remain FullyCondensed after follow-up commit", i)
165			}
166			if state.StepCount != 0 {
167				t.Fatalf("subagent %d StepCount = %d after follow-up commit, want 0", i, state.StepCount)
168			}
169		}
170	}
