// teamOp builds a repo-activity operation. Prefer repoOp / projectOp
// (registerRepos / registerProjects), which bundle the access gate so a scoped
// route cannot be registered ungated.
func teamOp(id, method, path, summary string, mw []opMiddleware) huma.Operation {
	return huma.Operation{OperationID: id, Method: method, Path: apiPrefix + path, Summary: summary,
		Tags: []string{"repo-activity"}, Security: secSchemes, Errors: stdErrors, Middlewares: mw}
}

