/**
 * Loader for repo-scoped routes that require repo access.
 * Throws to the repo route's notFoundComponent so inaccessible repos short-circuit
 * before the app shell mounts.
 *
 * checkpoint-status is only a soft repo-shell signal, not the page's content.
 * The legacy BFF path only ever returned 404 here for "no access", so a 404 is
 * still treated as the definitive access verdict (→ login / notFound). But the
 * entire-api gateway proxy can return 403 (and transient 5xx) for repos that
 * are in fact readable — including public repos. Escalating those to the route
 * error boundary 500s the entire repo shell (trails / commits / sessions). So
 * any non-404 failure is non-fatal: the shell renders and the checkpoint UI
 * degrades to its empty state rather than taking down the whole page.
 */
export async function repoAccessLoader({
  context,
  params,
  location,
}: {
  context: { queryClient: QueryClient; auth?: { isAuthenticated: boolean } }
  params: { org: string; repo: string }
  location: { href?: string; pathname: string }
}) {
  const { org, repo } = params

  try {
    await context.queryClient.ensureQueryData(checkpointStatusQueryOptions(org, repo))
  } catch (error) {
    if (error instanceof ApiError && error.status === 404) {
      if (shouldRedirectToLogin({ auth: context.auth, error })) {
        throw redirectToLogin({ location })
      }

      throw notFound()
    }
    // Non-404 (e.g. a gateway 403 or 5xx): non-fatal. Let the shell mount.
  }
}

