// Regression: the entire-api gateway can 403 checkpoint-status for repos that
// are in fact readable (incl. public repos). checkpoint-status is only a soft
// repo-shell signal, so a non-404 failure must NOT take down the whole repo
// shell (which 500'd every trail / commits / sessions page). Only a definitive
// 404 remains the access verdict.
describe("repoAccessLoader — gateway 403/5xx resilience", () => {
  it("does not throw (shell renders) when checkpoint-status returns a gateway 403", async () => {
    const context = createContext(true, new ApiError("no read access to repo", 403))

    await expect(
      repoAccessLoader({
        context,
        params: { org: "entireio", repo: "cli" },
        location: { pathname: "/gh/entireio/cli/trails/702" },
      }),
    ).resolves.toBeUndefined()
  })

  it("tolerates a transient 5xx from checkpoint-status", async () => {
    const context = createContext(true, new ApiError("upstream unavailable", 503))

    await expect(
      repoAccessLoader({
        context,
        params: { org: "entireio", repo: "cli" },
        location: { pathname: "/gh/entireio/cli/trails/702" },
      }),
    ).resolves.toBeUndefined()
  })

  it("still short-circuits to notFound on a definitive 404 (access verdict preserved)", async () => {
    const context = createContext(true, new ApiError("Repository not found", 404))

    await expect(
      repoAccessLoader({
        context,
        params: { org: "entireio", repo: "cli" },
        location: { pathname: "/gh/entireio/cli/trails/702" },
      }),
    ).rejects.toSatisfy((error: unknown) => isNotFound(error))
  })
})

