	if !ok {
		t.Fatalf("subagents[0] = %v", subs[0])
	}
	for key, want := range map[string]string{
		"tool_use_id":   "t1",
		"agent_id":      "a1",
		"subagent_type": "dev",
		"description":   "build",
	} {
		if got, ok := first[key].(string); !ok || got != want {
			t.Errorf("subagents[0].%s = %v, want %q", key, first[key], want)
		}
	}
