// Zero-dependency heuristic symbol parser — the substrate of Regente's
// symbol-level coordination. It maps a source file to a flat list of symbols
// (functions / classes / methods) with 1-based inclusive line ranges, so an agent
// can claim a single function (not the whole file) and so an edit's line range can
// be mapped to the symbol it lands in.
//
// This is heuristic, not an AST. Known limits (degrade safely — an unrecognized
// symbol simply isn't claimable at the symbol level):
//   - multi-line function signatures, TS overloads/generics, JSX
//   - object-literal methods ({ foo() {} }) are out of scope
//   - only top-level functions/classes/arrows + one level of class methods are
//     captured; functions nested inside functions map to their enclosing symbol
//   - Python: mixed tabs/spaces is approximated (tab = next multiple of 8)
// The brace scanner masks strings/templates/comments first, so braces inside them
// never mis-close a body.

const fs = require("fs");
const path = require("path");

const SYMBOL_MAX_BYTES = 512 * 1024;
const JS_EXT = new Set([".js", ".jsx", ".mjs", ".cjs", ".ts", ".tsx"]);
const PY_EXT = new Set([".py", ".pyi"]);
// Words that look like a method header (`name(...) {`) but are control flow.
const JS_KEYWORDS = new Set([
  "if", "for", "while", "switch", "catch", "return", "function", "do", "else",
  "try", "finally", "with", "case", "typeof", "await", "yield", "throw", "new",
  "constructor",
]);

function languageForPath(relPath) {
  const lower = String(relPath || "").toLowerCase();
  const dot = lower.lastIndexOf(".");
  if (dot < 0) return null;
  const ext = lower.slice(dot);
  if (JS_EXT.has(ext)) return ext === ".ts" || ext === ".tsx" ? "ts" : "js";
  if (PY_EXT.has(ext)) return "py";
  return null;
}

