43	// cellExchangeTransportForTest, when non-nil, is the HTTP transport used for
44	// jurisdiction token exchange and cluster listing. Production leaves it nil.
45	var cellExchangeTransportForTest http.RoundTripper
46	
47	// NewEntireAPICellClient returns an authenticated client aimed at the caller's
48	// home-jurisdiction entire-api cell with a jurisdictional identity token
49	// (scope=openid, aud=jurisdiction host). This is the COR-666 CLI-side routing
50	// path: repo-scoped entire-api reads do not accept the narrowed api-access
51	// bearer minted for https://entire.io — they require a cell identity token.
52	//
53	// When ENTIRE_API_BASE_URL already targets a cell (not the entire.io BFF), the
54	// configured origin is kept and only the token exchange is performed.
55	func NewEntireAPICellClient(ctx context.Context, insecureHTTP bool) (*api.Client, error) {
56		dataURL := api.BaseURL()
57		if insecureHTTP {
58			EnableInsecureHTTP()
59		} else if err := api.RequireSecureURL(dataURL); err != nil {
60			return nil, fmt.Errorf("base URL check: %w", err)
61		}
62	
63		dataOrigin := api.OriginOnly(dataURL)
64		host, ok := hostOf(dataOrigin)
65		if !ok {
66			return nil, fmt.Errorf("data API URL %q has no host to discover against", dataURL)
67		}
68	
69		dctx, cancel := context.WithTimeout(ctx, dataAPIDiscoveryTimeout)
70		defer cancel()
71		var httpClient *http.Client
72		if cellExchangeTransportForTest != nil {
73			httpClient = &http.Client{Timeout: cellDataAPITimeout, Transport: cellExchangeTransportForTest}
74		} else if shouldUsePlainHTTPDiscovery(dataOrigin) {
75			httpClient = dataAPIDiscoveryClient(dataOrigin)
76			httpClient.Timeout = cellDataAPITimeout
77		} else {
78			httpClient = &http.Client{Timeout: cellDataAPITimeout}
79		}
80	
81		selected, err := resolveContextForCellAPI(dctx, userdirs.Config(), userdirs.Cache(), host, httpClient, nil)
82		if errors.Is(err, clusterdiscovery.ErrDiscoveryUnavailable) {
83			return nil, fmt.Errorf("%s does not advertise its trusted login servers (/.well-known/entire-api.json missing or unreachable); cannot authenticate: %w", host, err)
84		}
85		if err != nil {
86			return nil, err
87		}
88	
89		allowInsecure := insecureHTTPEnabled() || isLoopbackHTTP(selected.CoreURL) || isLoopbackHTTP(dataOrigin)
90		loginProvider, err := NewRefreshingLoginProvider(selected, cellExchangeTransportForTest, allowInsecure)
91		if err != nil {
92			return nil, err
93		}
94	
95		loginJWT, err := loginProvider(ctx)
96		if err != nil {
97			if errors.Is(err, ErrNotLoggedIn) {
98				return nil, fmt.Errorf("not logged in (run 'entire login' first): %w", err)
99			}
100			return nil, fmt.Errorf("refresh login token: %w", err)
101		}
102	
103		jurisdiction, err := homeJurisdictionFromLoginJWT(loginJWT)
104		if err != nil {
105			return nil, err
106		}
107		if jurisdiction == "" {
108			return nil, errors.New("login token has no home_jurisdiction claim; cannot route to entire-api cell")
109		}
110	
111		cellBaseURL := strings.TrimRight(dataOrigin, "/")
112		if isEntireIOBFF(dataOrigin) {
113			cellBaseURL, err = resolveCellAPIBaseURL(ctx, jurisdictionCoreURL(jurisdiction, selected.CoreURL), loginJWT, jurisdiction, httpClient)
114			if err != nil {
115				return nil, err
116			}
117		}
118	
119		audience := jurisdictionAudience(jurisdiction)
120		token, err := exchangeJurisdictionToken(ctx, jurisdictionCoreURL(jurisdiction, selected.CoreURL), loginJWT, audience, httpClient)
121		if err != nil {
122			return nil, fmt.Errorf("exchange jurisdictional identity token: %w", err)
123		}
124	
125		return api.NewClientWithBaseURL(token, cellBaseURL), nil
126	}
