128	func isEntireIOBFF(origin string) bool {
129		u, err := url.Parse(origin)
130		if err != nil || u.Host == "" {
131			return false
132		}
133		host := strings.ToLower(u.Hostname())
134		if strings.Contains(host, ".api.") {
135			return false
136		}
137		return host == "entire.io" || strings.HasSuffix(host, ".entire.io")
138	}
