140	func jurisdictionAudience(jurisdiction string) string {
141		tmpl := strings.TrimSpace(os.Getenv("ENTIRE_API_AUDIENCE_TEMPLATE"))
142		if tmpl == "" {
143			tmpl = defaultJurisdictionAudienceTemplate
144		}
145		return strings.ReplaceAll(strings.TrimRight(tmpl, "/"), "{jurisdiction}", jurisdiction)
146	}
