148	func jurisdictionCoreURL(homeJurisdiction, fallbackCore string) string {
149		tmpl := strings.TrimSpace(os.Getenv("ENTIRE_CORE_BASE_URL_TEMPLATE"))
150		if tmpl == "" {
151			tmpl = defaultCoreBaseURLTemplate
152		}
153		if strings.Contains(tmpl, "{jurisdiction}") {
154			return strings.ReplaceAll(strings.TrimRight(tmpl, "/"), "{jurisdiction}", homeJurisdiction)
155		}
156		return strings.TrimRight(fallbackCore, "/")
157	}
