159	func homeJurisdictionFromLoginJWT(loginJWT string) (string, error) {
160		parts := strings.Split(loginJWT, ".")
161		if len(parts) < 2 {
162			return "", errors.New("login token is not a JWT")
163		}
164		payload, err := base64.RawURLEncoding.DecodeString(parts[1])
165		if err != nil {
166			return "", fmt.Errorf("decode login token payload: %w", err)
167		}
168		var claims struct {
169			HomeJurisdiction string `json:"home_jurisdiction"`
170		}
171		if err := json.Unmarshal(payload, &claims); err != nil {
172			return "", fmt.Errorf("parse login token payload: %w", err)
173		}
174		return claims.HomeJurisdiction, nil
175	}
