177	type clusterListingRow struct {
178		Jurisdiction string `json:"jurisdiction"`
179		IsDefault    bool   `json:"isDefault"`
180		APIURL       string `json:"apiUrl"`
181	}
182	
183	func resolveCellAPIBaseURL(ctx context.Context, coreURL, loginJWT, jurisdiction string, httpClient *http.Client) (string, error) {
184		req, err := http.NewRequestWithContext(ctx, http.MethodGet, strings.TrimRight(coreURL, "/")+"/api/v1/clusters", nil)
185		if err != nil {
186			return "", fmt.Errorf("build clusters request: %w", err)
187		}
188		req.Header.Set("Authorization", "Bearer "+loginJWT)
189		req.Header.Set("Accept", "application/json")
190	
191		resp, err := httpClient.Do(req)
192		if err != nil {
193			return "", fmt.Errorf("list clusters: %w", err)
194		}
195		defer resp.Body.Close()
196		if resp.StatusCode != http.StatusOK {
197			body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
198			return "", fmt.Errorf("list clusters: HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
199		}
200	
201		var listing struct {
202			Clusters []clusterListingRow `json:"clusters"`
203		}
204		if err := json.NewDecoder(resp.Body).Decode(&listing); err != nil {
205			return "", fmt.Errorf("decode clusters response: %w", err)
206		}
207	
208		var matches []clusterListingRow
209		for _, row := range listing.Clusters {
210			if row.Jurisdiction == jurisdiction && strings.TrimSpace(row.APIURL) != "" {
211				matches = append(matches, row)
212			}
213		}
214		if len(matches) == 0 {
215			return "", fmt.Errorf("no entire-api cell configured for home jurisdiction %q", jurisdiction)
216		}
217		chosen := matches[0]
218		for _, row := range matches {
219			if row.IsDefault {
220				chosen = row
221				break
222			}
223		}
224		return strings.TrimRight(chosen.APIURL, "/"), nil
225	}
226	
227	func exchangeJurisdictionToken(ctx context.Context, coreURL, loginJWT, audience string, httpClient *http.Client) (string, error) {
228		if coreURL == "" {
229			return "", errors.New("no entire-core URL configured for jurisdiction token exchange")
230		}
231		form := url.Values{}
232		form.Set("grant_type", httputil.GrantTypeTokenExchange)
233		form.Set("subject_token_type", "urn:ietf:params:oauth:token-type:access_token")
234		form.Set("subject_token", loginJWT)
235		form.Set("requested_token_type", "urn:ietf:params:oauth:token-type:access_token")
236		form.Set("audience", audience)
237		form.Set("scope", jurisdictionIdentityScope)
238		form.Set("client_id", oauthClientID)
239	
240		token, _, err := httputil.PostOAuthToken(ctx, httpClient, coreURL, form)
241		if err != nil {
242			return "", err
243		}
244		return token, nil
245	}
