202	func runExperts(ctx context.Context, out, errOut io.Writer, args []string, f *expertsFlags) error {
203		if f.staged && strings.TrimSpace(f.repo) != "" {
204			return errors.New("--staged cannot be used with --repo")
205		}
206		if f.limit <= 0 {
207			f.limit = expertsDefaultLimit
208		}
209		if f.limit > expertsMaxLimit {
210			f.limit = expertsMaxLimit
211		}
212	
213		// The data API (entire-api) is repo-ULID keyed. --repo may be a ULID (used
214		// directly) or an owner/repo, which we resolve to its ULID after the client
215		// exists (via the caller's accessible-repo list). With no --repo we derive
216		// owner/repo from the git origin.
217		repoOverride := strings.TrimSpace(f.repo)
218		repoIsULID := looksLikeULID(repoOverride)
219		var repoFullName string
220		if !repoIsULID {
221			var err error
222			repoFullName, err = resolveExpertsRepo(ctx, f.repo)
223			if err != nil {
224				return err
225			}
226		}
227	
228		req := expertsRequest{Limit: f.limit, EvidenceLimit: 3}
229		if strings.TrimSpace(f.branch) != "" {
230			req.Branch = strings.TrimSpace(f.branch)
231		}
232	
233		if f.staged {
234			scopes, err := stagedExpertScopes(ctx)
235			if err != nil {
236				return err
237			}
238			if len(scopes) == 0 {
239				fmt.Fprintln(errOut, "No staged files found.")
240				return NewSilentError(errors.New("no staged files"))
241			}
242			req.Scopes = scopes
243		} else {
244			input := strings.TrimSpace(strings.Join(args, " "))
245			if input == "" {
246				return errors.New("scope or query required unless --staged is set")
247			}
248			if strings.TrimSpace(f.repo) != "" && looksLikeExpertPath(input) {
249				req.Scopes = []string{normalizeExpertScope(input)}
250			} else {
251				local, err := localExpertScope(ctx, input)
252				if err != nil {
253					return err
254				}
255				if local.isLocal {
256					if !repoIsULID && repoOverride != "" && local.validateRepo {
257						currentRepo, err := resolveExpertsRepo(ctx, "")
258						if err == nil && !strings.EqualFold(currentRepo, repoFullName) {
259							return fmt.Errorf("local path belongs to %s, not --repo %s", currentRepo, repoFullName)
260						}
261					}
262					req.Scopes = []string{local.scope}
263				} else {
264					query := input
265					req.Query = &query
266				}
267			}
268		}
269	
270		client, err := newExpertsAPIClient(ctx, f.insecureHTTP)
271		if err != nil {
272			return fmt.Errorf("create experts API client: %w", err)
273		}
274	
275		repoID := repoOverride
276		if !repoIsULID {
277			repoID, err = resolveExpertsRepoID(ctx, client, repoFullName)
278			if err != nil {
279				return err
280			}
281		}
282	
283		resp, err := client.Post(ctx, expertsAPIPath(repoID), req)
284		if err != nil {
285			return fmt.Errorf("post experts request: %w", err)
286		}
287		defer resp.Body.Close()
288	
289		if err := api.CheckResponse(resp); err != nil {
290			var httpErr *api.HTTPError
291			if errors.As(err, &httpErr) &&
292				httpErr.StatusCode == http.StatusServiceUnavailable &&
293				req.Query != nil &&
294				strings.Contains(strings.ToLower(httpErr.Message), "code search") {
295				fmt.Fprintln(errOut, "Code search is not configured for natural-language experts queries.")
296				return NewSilentError(err)
297			}
298			return fmt.Errorf("fetch experts: %w", err)
299		}
300	
301		var decoded expertsResponse
302		if err := api.DecodeJSON(resp, &decoded); err != nil {
303			return fmt.Errorf("decode experts response: %w", err)
304		}
305	
306		if f.json {
307			enc := json.NewEncoder(out)
308			enc.SetIndent("", "  ")
309			if err := enc.Encode(decoded); err != nil {
310				return fmt.Errorf("write experts JSON: %w", err)
311			}
312			return nil
313		}
314	
315		// The interactive viewer is opt-in and only runs on a real terminal with
316		// results to show. Piped/accessible output and empty results always fall
317		// through to the deterministic plain renderer so agents and scripts get
318		// stable output.
319		if f.tui && len(decoded.Profiles) > 0 && interactive.IsTerminalWriter(out) && !IsAccessibleMode() {
320			return runExpertsTUI(decoded, shouldUseColor(out))
321		}
322	
323		renderExperts(out, decoded)
324		return nil
325	}
