327	func resolveExpertsRepo(ctx context.Context, override string) (string, error) {
328		if strings.TrimSpace(override) != "" {
329			return parseExpertsRepo(override)
330		}
331		_, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
332		if err != nil {
333			return "", fmt.Errorf("resolve repo from origin: %w", err)
334		}
335		if owner == "" || repo == "" {
336			return "", errors.New("could not resolve owner/repo from origin")
337		}
338		return owner + "/" + repo, nil
339	}
340	
341	func parseExpertsRepo(value string) (string, error) {
342		trimmed := strings.Trim(strings.TrimSpace(value), "/")
343		parts := strings.Split(trimmed, "/")
344		if len(parts) == 3 && parts[0] == "gh" {
345			parts = parts[1:]
346		}
347		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
348			return "", fmt.Errorf("invalid --repo %q (use owner/repo)", value)
349		}
350		return parts[0] + "/" + strings.TrimSuffix(parts[1], ".git"), nil
351	}
