358	// data plane, which is ULID-keyed. It reads the caller's accessible-repo list
359	// (GET /api/v1/repos) and matches on full name — an authz-safe resolution (the
360	// list only contains repos the caller can read, so it never reveals a repo they
361	// can't see). A ULID is passed straight through by the caller, so this is only
362	// hit for the owner/repo form.
363	func resolveExpertsRepoID(ctx context.Context, client expertsAPIClient, fullName string) (string, error) {
364		repos, err := listExpertsAccessibleRepos(ctx, client)
365		if err != nil {
366			return "", err
367		}
368		want := strings.ToLower(fullName)
369		for _, r := range repos {
370			if r.ID != "" && strings.ToLower(r.FullName) == want {
371				return r.ID, nil
372			}
373		}
374		return "", fmt.Errorf("repo %q is not among your accessible repos on this API (is it onboarded to Entire, and do you have access?)", fullName)
375	}
