419	//   - otherwise (local dev API like 127.0.0.1) fall back to the canonical
420	//     https://entire.io so links still resolve to the proper site.
421	func expertsWebBaseURL() string {
422		if raw := strings.TrimSpace(os.Getenv("ENTIRE_WEB_BASE_URL")); raw != "" {
423			return strings.TrimRight(raw, "/")
