453	func localExpertScope(ctx context.Context, input string) (expertLocalScopeResult, error) {
454		root, err := paths.WorktreeRoot(ctx)
455		if err != nil {
456			if looksLikeExpertPath(input) {
457				return expertLocalScopeResult{
458					scope: normalizeExpertScope(input), isLocal: true,
459				}, nil
460			}
461			return expertLocalScopeResult{}, nil
462		}
463	
464		candidates := make([]string, 0, 2)
465		if filepath.IsAbs(input) {
466			candidates = append(candidates, input)
467		} else {
468			cwdAbs, err := filepath.Abs(input)
469			if err != nil {
470				return expertLocalScopeResult{}, fmt.Errorf("resolve cwd-relative path: %w", err)
471			}
472			candidates = append(candidates, cwdAbs, filepath.Join(root, input))
473		}
474		candidates = uniqueStrings(candidates)
475	
476		for _, candidate := range candidates {
477			info, err := os.Stat(candidate)
478			if err != nil {
479				if os.IsNotExist(err) {
480					continue
481				}
482				return expertLocalScopeResult{}, fmt.Errorf("stat local scope: %w", err)
483			}
484			scope, err := localPathScope(root, candidate, input)
485			if err != nil {
486				return expertLocalScopeResult{}, err
487			}
488			if info.IsDir() && !strings.HasSuffix(scope, "/") {
489				scope += "/"
490			}
491			return expertLocalScopeResult{scope: scope, isLocal: true, validateRepo: true}, nil
492		}
493	
494		if looksLikeExpertPath(input) {
495			missingCandidates := make([]string, 0, 3)
496			if filepath.IsAbs(input) {
497				missingCandidates = append(missingCandidates, input)
498			} else {
499				cwdAbs, err := filepath.Abs(input)
500				if err != nil {
501					return expertLocalScopeResult{}, fmt.Errorf("resolve cwd-relative path: %w", err)
502				}
503				missingCandidates = append(missingCandidates, cwdAbs, filepath.Join(root, input))
504			}
505			for _, candidate := range uniqueStrings(missingCandidates) {
506				scope, err := localPathScope(root, candidate, input)
507				if err != nil {
508					continue
509				}
510				return expertLocalScopeResult{scope: scope, isLocal: true}, nil
511			}
512			return expertLocalScopeResult{
513				scope: normalizeExpertScope(input), isLocal: true,
514			}, nil
515		}
516		return expertLocalScopeResult{}, nil
517	}
