519	func localPathScope(root, candidate, original string) (string, error) {
520		rel, err := filepath.Rel(canonicalPathForRel(root), canonicalPathForRel(candidate))
521		if err != nil {
522			return "", fmt.Errorf("relativize local scope: %w", err)
523		}
524		if rel == "." {
525			return "./", nil
526		}
527		if strings.HasPrefix(rel, ".."+string(filepath.Separator)) || rel == ".." {
528			return "", fmt.Errorf("path %q is outside the git worktree", original)
529		}
530		return filepath.ToSlash(rel), nil
531	}
532	
533	func canonicalPathForRel(path string) string {
534		resolved, err := filepath.EvalSymlinks(path)
535		if err == nil {
536			return resolved
537		}
538	
539		var missing []string
540		current := path
541		for {
542			parent := filepath.Dir(current)
543			base := filepath.Base(current)
544			if parent == current {
545				return path
546			}
547			missing = append([]string{base}, missing...)
548			resolvedParent, err := filepath.EvalSymlinks(parent)
549			if err == nil {
550				return filepath.Join(append([]string{resolvedParent}, missing...)...)
551			}
552			current = parent
553		}
554	}
