556	func uniqueStrings(values []string) []string {
557		seen := make(map[string]bool, len(values))
558		out := make([]string, 0, len(values))
559		for _, value := range values {
560			if seen[value] {
561				continue
562			}
563			seen[value] = true
564			out = append(out, value)
565		}
566		return out
567	}
