596	// parseGitStagedScopeLines normalizes git name-only output into repo-relative
597	// path scopes. Windows git may emit CRLF line endings; strip them before split.
598	func parseGitStagedScopeLines(raw string) []string {
599		trimmed := strings.TrimSpace(raw)
600		trimmed = strings.ReplaceAll(trimmed, "\r\n", "\n")
601		lines := strings.Split(trimmed, "\n")
602		scopes := make([]string, 0, len(lines))
603		seen := make(map[string]bool, len(lines))
604		for _, line := range lines {
605			scope := strings.TrimSpace(filepath.ToSlash(line))
606			if scope == "" || seen[scope] {
607				continue
608			}
609			seen[scope] = true
610			scopes = append(scopes, scope)
611		}
612		return scopes
613	}
