	})
	target := resolveExpertsCellTarget(context.Background(), "acme/widget", "")
	if target == nil || target.Jurisdiction != "eu" || target.BaseURL != "https://eu.api.entire.io" {
		t.Fatalf("target = %+v, want eu cell", target)
