export const meta = {
  name: 'final-audit-experts-cell-routing',
  description: 'Third/final adversarial pass over the experts cell-routing fix — real defects only',
  phases: [{ title: 'Find' }, { title: 'Verify' }],
}

const CONTEXT = `
Final audit pass. HEAD is dd7370ddb on branch codex/experts-cell-routing in /Users/suhaan/devenv/cli. The full feature diff is main..HEAD across:
- cmd/entire/cli/auth/cell_data_api.go (+_test.go)
- cmd/entire/cli/experts_cell_target.go (+_test.go)
- cmd/entire/cli/api_client.go, experts_cmd.go (+experts_test.go), repo_clone.go (listMirrorsForRepo now takes a mirrorLister interface)

Two prior audit passes already fixed: cross-jurisdiction routing (now resolves the repo's own cell via coreapi mirrors/GetRepo + ListClusters, best-effort with home-jurisdiction fallback, 5s deadline), staging/family templates, local-dev core, https guards (requireSafeExchangeURL requires https affirmatively), jurisdiction-label validation + lowercasing, mirror status filtering (skip failed/suspended), and extensive tests.

Current state VERIFIED: go build ./... clean; mise run lint = 0 issues; mise run test = 7501 tests, 0 failures.

YOUR JOB: find ONLY real, still-open defects of severity MEDIUM or higher — genuine correctness, security, or data-integrity bugs that would occur in production, OR a regression introduced by the fixes. This is a hidden/labs command whose token-mint mechanism is verified against the BFF and whose cross-region resolution falls back safely. Do NOT report style nits, "add more tests", or theoretical issues already mitigated by the safe fallback. For each finding, construct a concrete failing input and explain why the existing mitigations don't cover it. If you find nothing medium+, return an empty findings array — that is the expected and acceptable result.
`

const FINDINGS_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          file: { type: 'string' },
          lines: { type: 'string' },
          severity: { type: 'string', enum: ['critical', 'high', 'medium'] },
          explanation: { type: 'string' },
          concrete_failing_input: { type: 'string' },
          why_not_mitigated: { type: 'string' },
          suggested_fix: { type: 'string' },
        },
        required: ['title', 'file', 'severity', 'explanation'],
        additionalProperties: false,
      },
    },
  },
  required: ['findings'],
  additionalProperties: false,
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    is_real: { type: 'boolean' },
    is_medium_plus: { type: 'boolean' },
    reasoning: { type: 'string' },
  },
  required: ['is_real', 'is_medium_plus', 'reasoning'],
  additionalProperties: false,
}

const DIMENSIONS = [
  { key: 'correctness', prompt: `Hunt for MEDIUM+ correctness bugs / regressions in the full cell-routing flow (experts_cmd -> api_client -> resolveExpertsCellTarget -> auth.NewEntireAPICellClient). Especially: did the second-pass changes (5s deadline reassigning ctx, mirror-status filter, unconditional core template, jurisdiction lowercasing) break any prior-correct behavior? Does the same-region happy path still work end to end? Any path that dials the wrong cell or mints the wrong audience WITHOUT falling back? ${CONTEXT}` },
  { key: 'security', prompt: `Hunt for MEDIUM+ security defects: any path where the login JWT or identity token is sent to a non-https/non-loopback host, any injection via jurisdiction/host/template, any guard that runs AFTER the request it should protect, any trust-boundary violation. Verify requireSafeExchangeURL actually gates both the core and the cell apiUrl in BOTH target and fallback paths, before any request carrying the JWT. ${CONTEXT}` },
  { key: 'concurrency-resource', prompt: `Hunt for MEDIUM+ resource/robustness defects: leaked response bodies, context/deadline misuse (the new 5s WithTimeout on a reassigned ctx — does it cancel the cell dial that happens AFTER resolution returns?), goroutine issues, the coreapi client lifecycle, pagination loops. Confirm the 5s deadline does NOT prematurely cancel the actual experts request. ${CONTEXT}` },
]

phase('Find')
const results = await pipeline(
  DIMENSIONS,
  (d) => agent(d.prompt, { label: `find:${d.key}`, phase: 'Find', schema: FINDINGS_SCHEMA }),
  (review, d) => {
    const findings = (review && review.findings) || []
    if (!findings.length) return []
    return parallel(findings.map((f) => () =>
      agent(`Adversarially VERIFY against the on-disk code. Read the files. Is this a REAL, still-open, MEDIUM-or-higher production defect (or regression)? Try hard to refute — check whether the safe fallback, the guards, or existing tests already cover it. Return is_real=false if it's mitigated, theoretical, low/nit, or wrong.\n\nFINDING (${d.key}):\n${JSON.stringify(f, null, 2)}\n\n${CONTEXT}`,
      { label: `verify:${d.key}`, phase: 'Verify', schema: VERDICT_SCHEMA }).then((v) => ({ finding: f, verdict: v, dimension: d.key })),
    ))
  },
)

const all = results.flat().filter(Boolean)
const confirmed = all.filter((r) => r.verdict && r.verdict.is_real && r.verdict.is_medium_plus)
log(`Final pass: ${confirmed.length} confirmed medium+ of ${all.length} raised.`)
return {
  clean: confirmed.length === 0,
