export const meta = {
  name: 'reasoning-layer-roadmap',
  description: 'Map each Semantic Reasoning Layer phase to real repos, build the full Linear hierarchy, verify complete coverage',
  phases: [
    { title: 'Map phases' },
    { title: 'Synthesize + completeness' },
  ],
}

const PLAN = `
SEMANTIC REASONING LAYER — remade roadmap (private working doc). The semantic index + durable memory already EXIST as local plugins, so the spine is: GA the local brain -> make it SHARED/hosted -> unify memory -> coordinate -> federate.

P0 GA entire-sem + entire-brain (local brain) [mostly done -> ship]: close entire-brain release blockers; harden entire-sem snapshot/edges; ship both GA with MCP adapter. Leverage: entire-sem, entire-brain, brain-bench.
P1 Shared / hosted brain [the real new frontier]: lift the brain from local/per-machine to shared/synced (server-side, synced via entiredb + checkpoint_remote) so a fleet reasons over ONE brain. Leverage: entiredb, checkpoint_remote, entire-search.
P2 Unified pluggable memory: brain + code-search (peregrine/pgr/symq -> one) + knowledge (librarian + entire-search -> one) behind ONE MCP memory surface; retire duplicates. Leverage: mcp, peregrine, librarian, entire-search.
P3 Semantic collision-free parallel agents: entity-level claims/leases on the brain's entity model, pre-merge semantic conflict detection, structured handovers + MCP auto-hydration, scheduler -> sandboxes, presence + read-receipt messaging. Leverage: agent-planner, cli worktree shadow branches, ferrata/entire-sandbox. PRIVATE reference prototype (ours only, keep off company surfaces): regente-core.
P4 Cross-repo / cross-org shared reasoning: cross-repo semantic discovery over the federated index (mirror-pipeline/entiredb); agent capability registry (extend external-agents); cross-org authz (SpiceDB/MCP).

Sequencing: P0 (finish) -> P1 (differentiator) -> P2 (converge) -> P3 (coordinate) -> P4 (federate).
`

const REPO_MAP = `
Local repos available to read:
- ~/Documents/Coding/entire-sem            (entire sem plugin)
- ~/Documents/Coding/entire-brain          (entire brain plugin; docs/: release-blockers.md, readiness audit, durable_facts_plan.md, semantic_brain_plan.md, pattern_v3.md, semantic_mcp_guide.md, eval_ledger.md)
- ~/Documents/Coding/brain-bench           (brain benchmark / eval gate)
- ~/Documents/Coding/external-agents       (agent registry / external agents)
- ~/Documents/Coding/regente-core          (PRIVATE prototype: symbol claims, fencing, handovers, read-receipt msg, MCP)
- ~/devenv/entiredb                        (git-native storage + transparency log)
- ~/devenv/cli                             (entire CLI; checkpoint/remote at cmd/entire/cli/checkpoint/remote; hidden 'entire mcp' stdio server; worktree shadow-branch strategy at cmd/entire/cli/strategy)
- ~/devenv/entire-api                      (regional data-plane cell; SpiceDB authz)
NOT cloned locally (reference from general knowledge/plan, mark as "referenced, not verified"): peregrine, pgr, symq, librarian, entire-search, agent-planner, mirror-pipeline, ferrata/entire-sandbox, checkpoint_remote server side.
When a repo IS available, VERIFY claims by reading it (commands, docs, release-blockers). Quote concrete evidence (file/command) for every "exists" claim.
`

const LAYER_SCHEMA = {
  type: 'object',
  properties: {
    phase: { type: 'string' },
    summary: { type: 'string' },
    exists: {
      type: 'array',
      items: { type: 'object', properties: {
        capability: { type: 'string' }, evidence: { type: 'string' }, repo: { type: 'string' },
      }, required: ['capability', 'evidence'], additionalProperties: false },
    },
    gaps: { type: 'array', items: { type: 'string' } },
    milestones: {
      type: 'array',
      items: { type: 'object', properties: {
        title: { type: 'string' },
        detail: { type: 'string' },
        issues: { type: 'array', items: { type: 'object', properties: {
          title: { type: 'string' },
          status: { type: 'string', enum: ['exists', 'partial', 'todo'] },
          evidence_or_scope: { type: 'string' },
          leverage: { type: 'string' },
        }, required: ['title', 'status', 'evidence_or_scope'], additionalProperties: false } },
      }, required: ['title', 'issues'], additionalProperties: false },
    },
    leverage_components: {
      type: 'array',
      items: { type: 'object', properties: {
        name: { type: 'string' }, status: { type: 'string', enum: ['shipped', 'near-release', 'partial', 'referenced-not-verified', 'to-build'] }, note: { type: 'string' },
      }, required: ['name', 'status'], additionalProperties: false },
    },
  },
  required: ['phase', 'summary', 'exists', 'gaps', 'milestones', 'leverage_components'],
  additionalProperties: false,
}

const LAYERS = [
  { key: 'P0-local-brain', prompt: `Map PHASE P0 — GA entire-sem + entire-brain (the local brain). READ these repos and verify: ~/Documents/Coding/entire-sem (commands: snapshot/symbols/edges/diff/checkpoint; langs; .brainignore), ~/Documents/Coding/entire-brain (esp. docs/release-blockers.md, readiness audit, durable_facts_plan.md, semantic_brain_plan.md, semantic_mcp_guide.md — extract the ACTUAL remaining release blockers), ~/Documents/Coding/brain-bench. Produce milestones + issues to GA both plugins (close real release blockers, harden entire-sem, MCP adapter, brain-bench eval gate). Tag each issue exists/partial/todo with concrete evidence.` },
  { key: 'P1-shared-brain', prompt: `Map PHASE P1 — Shared / hosted brain (lift local brain to shared/synced). READ ~/devenv/entiredb (git-native storage, transparency log — what sync/hosting primitives exist), ~/devenv/cli/cmd/entire/cli/checkpoint/remote (checkpoint remote sync). Determine what exists for hosting/syncing a brain server-side vs what must be built. Milestones + issues for: server-side brain store, sync protocol over entiredb + checkpoint_remote, multi-machine shared query, auth/tenancy. Tag exists/partial/todo with evidence. This is the highest-leverage NEW work — be concrete about the build.` },
  { key: 'P2-unified-memory', prompt: `Map PHASE P2 — Unified pluggable memory (one MCP memory surface). READ ~/devenv/cli hidden 'entire mcp' stdio server + ~/Documents/Coding/entire-brain semantic_mcp_guide.md + entire-sem MCP adapter. peregrine/pgr/symq (code search) and librarian/entire-search (knowledge) are NOT local — mark referenced-not-verified. Milestones + issues to: converge code-search into one, converge knowledge into one backbone, expose brain+search+knowledge behind ONE MCP surface, retire duplicates. Tag exists/partial/todo.` },
  { key: 'P3-parallel-agents', prompt: `Map PHASE P3 — Semantic collision-free parallel agents (coordination on the brain). READ ~/devenv/cli/cmd/entire/cli/strategy (worktree shadow branches), ~/Documents/Coding/external-agents, and (PRIVATE, ours-only) ~/Documents/Coding/regente-core (symbol claims, fencing, structured handovers, read-receipt messaging, MCP) as the reference prototype. agent-planner + ferrata/entire-sandbox are NOT local — referenced-not-verified. Milestones + issues for: entity-level claims/leases on the brain entity model, pre-merge semantic conflict detection, structured handovers + MCP auto-hydration, scheduler->sandboxes, presence + read-receipt messaging. Keep regente as a PRIVATE reference note (NOT a company-visible issue title). Tag exists/partial/todo.` },
  { key: 'P4-cross-repo', prompt: `Map PHASE P4 — Cross-repo / cross-org shared reasoning. READ ~/devenv/entiredb (federated index / mirror), ~/devenv/entire-api (SpiceDB authz), ~/Documents/Coding/external-agents (capability registry basis). mirror-pipeline NOT local — referenced-not-verified. Milestones + issues for: cross-repo semantic discovery over the federated index, agent capability registry (extend external-agents), cross-org authz (SpiceDB/MCP). Tag exists/partial/todo with evidence.` },
]

phase('Map phases')
const layers = await parallel(LAYERS.map((l) => () =>
  agent(`${l.prompt}\n\nROADMAP CONTEXT:\n${PLAN}\n\nREPOS:\n${REPO_MAP}\n\nBe exhaustive for your phase: every capability the phase outcome implies must appear as an issue (status exists/partial/todo). Verify "exists" against the actual repo and quote evidence.`,
    { label: `map:${l.key}`, phase: 'Map phases', schema: LAYER_SCHEMA })
))

const mapped = layers.filter(Boolean)

phase('Synthesize + completeness')
const SYNTH_SCHEMA = {
  type: 'object',
  properties: {
    roadmap_markdown: { type: 'string' },
    coverage: { type: 'array', items: { type: 'object', properties: {
      vision_piece: { type: 'string' }, covered_by: { type: 'string' }, status: { type: 'string', enum: ['exists', 'partial', 'todo'] },
    }, required: ['vision_piece', 'covered_by', 'status'], additionalProperties: false } },
    missing_or_risks: { type: 'array', items: { type: 'string' } },
    totals: { type: 'object', properties: { projects: { type: 'number' }, milestones: { type: 'number' }, issues: { type: 'number' } }, required: ['projects', 'milestones', 'issues'], additionalProperties: false },
  },
  required: ['roadmap_markdown', 'coverage', 'missing_or_risks', 'totals'],
  additionalProperties: false,
}

const synth = await agent(
  `You are assembling the COMPLETE Linear roadmap for the Semantic Reasoning Layer from the five mapped phases below. Output a single, ready-to-materialize hierarchy: Initiative "Semantic Reasoning Layer" -> 5 Projects (P0..P4) -> Milestones -> Issues, each issue tagged [exists] / [partial] / [todo] with a one-line evidence-or-scope note and its leverage component.

Then run a COMPLETENESS CHECK: for every outcome and every named leverage component in the ROADMAP CONTEXT, confirm it maps to at least one issue; list any vision piece not covered under missing_or_risks. The bar: "every piece is there so everything in the description is fully completed."

Rules:
- roadmap_markdown must be the full, well-structured markdown (Initiative -> Projects -> Milestones -> Issues with status tags). Include a short "what exists vs to-build" line per project.
- Keep regente ONLY as a private reference note inside P3 (never a standalone company-visible issue title).
- Be honest about referenced-not-verified components.

MAPPED PHASES (JSON):
${JSON.stringify(mapped, null, 2)}

ROADMAP CONTEXT:
${PLAN}`,
  { label: 'synthesize', phase: 'Synthesize + completeness', schema: SYNTH_SCHEMA, effort: 'high' },
)

return { synth, mapped_counts: mapped.map((m) => ({ phase: m.phase, milestones: (m.milestones || []).length, issues: (m.milestones || []).reduce((n, ms) => n + (ms.issues || []).length, 0) })) }

