63	func runDash(ctx context.Context, cmd *cobra.Command, opts Options, flags dashFlags, target string) error {
64		startTab, ok := tui.ParseTab(flags.tab)
65		if !ok && flags.tab != "" {
66			return fmt.Errorf("unknown_tab: %q (want home, facts, sessions, history, semantic, or search)", flags.tab)
67		}
68	
69		// Validate the theme up front (like the tab) so a typo fails fast with the
70		// valid names, in any output mode, rather than silently falling back.
71		theme, err := resolveDashTheme(flags.theme)
72		if err != nil {
73			return err
74		}
75	
76		repoDir, brainDir, branch, err := resolveFactsTarget(ctx, opts, target, flags.branch)
77		if err != nil {
78			return err
79		}
80	
81		snap, err := assembleBrainSnapshot(ctx, opts, target, repoDir, brainDir, branch, flags.limit)
82		if err != nil {
83			return err
84		}
85	
86		if flags.json {
87			return writeJSON(cmd, snap)
88		}
89		if flags.plain || !commandOutputIsTTY(cmd) {
90			printDashPlain(cmd, snap)
91			return nil
92		}
93		return tui.Run(snap, theme, brainSearchFunc(brainDir, branch), startTab, cmd.OutOrStdout())
94	}
