96	// brainSearchFunc adapts the lexical retrieval (`entire brain search`) into the
97	// callback the dashboard's `s` key invokes, so search runs the same code path as
98	// the CLI verb while keeping the TUI free of file IO.
99	func brainSearchFunc(brainDir, branch string) tui.SearchFunc {
100		return func(query string) ([]tui.SearchResult, error) {
101			results, err := retrieveUnified(brainDir, branch, query, dashSearchLimit, modeLexical)
102			if err != nil {
103				return nil, err
104			}
105			out := make([]tui.SearchResult, 0, len(results))
106			for _, r := range results {
107				out = append(out, searchResultFromUnified(r, brainDir))
108			}
109			return out, nil
110		}
111	}
112	
113	// searchResultFromUnified maps a retrieval hit to the TUI view model and decides
114	// its "open source" target. Only history and doc hits carry a real
115	// brain-relative file path; a fact's Path is its taxonomy labels (not a file),
116	// so a fact hit gets no open target rather than a bogus one.
117	func searchResultFromUnified(r unifiedResult, brainDir string) tui.SearchResult {
118		sr := tui.SearchResult{
119			Source:  r.Source,
120			ID:      r.ID,
121			Path:    r.Path,
122			Heading: r.Heading,
123			Line:    r.Line,
124			Text:    r.Text,
125			Score:   r.Score,
126		}
127		if r.Path != "" && (r.Source == "history" || r.Source == "doc") {
128			sr.OpenPath = containedPath(brainDir, r.Path)
129			sr.OpenLine = r.Line
130		}
131		return sr
132	}
