134	// assembleBrainSnapshot is the only place that touches the brain on disk. It
135	// reuses the existing loaders to build a read-only tui.Snapshot; no agent calls.
136	func assembleBrainSnapshot(ctx context.Context, opts Options, target, repoDir, brainDir, branch string, limit int) (tui.Snapshot, error) {
137		snap := tui.Snapshot{Repo: repoDir, Branch: branch}
138	
139		status, err := buildBrainStatusReport(ctx, opts, target)
140		if err != nil {
141			return snap, err
142		}
143		if status.Repo.Root != "" {
144			snap.Repo = status.Repo.Root
145		}
146		snap.GeneratedAt = status.Brain.GeneratedAt
147		manifest := status.Manifest
148		snap.Home = dashHomeView(status, manifest, branch)
149	
150		// Facts (per branch).
151		if facts, err := loadFacts(brainDir, branch); err != nil {
152			snap.Home.Warnings = append(snap.Home.Warnings, "facts unavailable: "+err.Error())
153		} else {
154			snap.Facts = dashFactViews(facts, brainDir, limit)
155			snap.Notes = appendCapNote(snap.Notes, "facts", len(facts), len(snap.Facts))
156		}
157	
158		if manifest != nil && manifest.Sources != nil {
159			// Sessions (from the manifest).
160			if s := manifest.Sources.Sessions; s != nil {
161				snap.Sessions = dashSessionViews(s.Sessions, brainDir, limit)
162				snap.Notes = appendCapNote(snap.Notes, "sessions", len(s.Sessions), len(snap.Sessions))
163			}
164			// History (index.json).
165			if h := manifest.Sources.History; h != nil {
166				if idx, err := loadBrainHistoryIndex(brainDir, h); err != nil {
167					snap.Home.Warnings = append(snap.Home.Warnings, "history unavailable: "+err.Error())
168				} else {
169					snap.History = dashHistoryViews(idx.Records, brainDir, limit)
170					snap.Notes = appendCapNote(snap.Notes, "history", len(idx.Records), len(snap.History))
171				}
172			}
173			// Semantic symbols (snapshot.ndjson).
174			if sem := manifest.Sources.Semantic; sem != nil {
175				if syms, err := loadSemanticSymbols(brainDir, sem, limit); err != nil {
176					snap.Home.Warnings = append(snap.Home.Warnings, "semantic unavailable: "+err.Error())
177				} else {
178					snap.Semantic = dashSemanticViews(syms, repoDir)
179					snap.Notes = appendCapNote(snap.Notes, "semantic symbols", sem.Symbols, len(snap.Semantic))
180				}
181			}
182		}
183	
184		return snap, nil
185	}
