187	// dashHomeView maps the status report into the Home tab view model.
188	func dashHomeView(status brainStatusReport, manifest *exportManifest, branch string) tui.HomeView {
189		home := tui.HomeView{
190			Freshness:  brainStatusFreshnessSeverity(status),
191			Warnings:   append([]string(nil), status.Warnings...),
192			BlindSpots: dashBlindSpotLabels(brainStatusBlindSpots(status)),
193		}
194	
195		present := status.Sources
196		detail := dashSourceDetails(manifest)
197		home.Sources = []tui.SourceHealth{
198			{Name: "Seed", Present: present.Seed, Detail: detail["seed"]},
199			{Name: "Sessions", Present: present.Sessions, Detail: detail["sessions"]},
200			{Name: "Semantic", Present: present.Semantic, Detail: detail["semantic"]},
201			{Name: "History", Present: present.History, Detail: detail["history"]},
202			{Name: "Facts", Present: present.Facts, Detail: detail["facts"]},
203		}
204	
205		if status.Semantic != nil && status.Semantic.Freshness != nil {
206			for name, axis := range status.Semantic.Freshness.Axes {
207				home.Axes = append(home.Axes, tui.FreshnessAxis{Name: name, State: axis.State, Detail: axis.Detail})
208			}
209			sortFreshnessAxes(home.Axes)
210		}
211	
212		home.Live = tui.LiveState{
213			Branch:  firstNonEmpty(status.Live.Branch, branch),
214			Head:    status.Live.Head,
215			Dirty:   status.Live.Dirty,
216			Summary: dashLiveSummary(status.Live),
217		}
218	
219		if manifest != nil && manifest.GeneratedAt.IsZero() && !anySource(present) {
220			home.Warnings = append(home.Warnings, "brain not built yet — run `entire brain refresh`")
221		}
222		return home
223	}
