412	// loadSemanticSymbols reads the symbol records from the active semantic snapshot
413	// (NDJSON: a header line followed by one record per line), reusing the snapshot
414	// scanner and path validation. A missing snapshot yields no symbols.
415	func loadSemanticSymbols(brainDir string, source *semanticSourceManifest, limit int) ([]semanticRecord, error) {
416		if source == nil || source.SnapshotPath == "" {
417			return nil, nil
418		}
419		rel, err := validateSemanticSnapshotPath(source.SnapshotPath)
420		if err != nil {
421			return nil, err
422		}
423		full := filepath.Join(brainDir, rel)
424		// A missing snapshot is not an error: an inconsistent or not-yet-built brain
425		// just yields no symbols rather than a scary warning.
426		if _, statErr := os.Stat(full); os.IsNotExist(statErr) {
427			return nil, nil
428		}
429		if err := rejectSymlinkPathComponents(brainDir, rel); err != nil {
430			return nil, err
431		}
432		f, err := os.Open(full)
433		if err != nil {
434			if os.IsNotExist(err) {
435				return nil, nil
436			}
437			return nil, err
438		}
439		defer f.Close()
440		scanner := newSemanticScanner(f)
441		first := true
442		var out []semanticRecord
443		for scanner.Scan() {
444			if first { // skip the header line
445				first = false
446				continue
447			}
448			text := bytes.TrimSpace(scanner.Bytes())
449			if len(text) == 0 {
450				continue
451			}
452			var rec semanticRecord
453			if err := json.Unmarshal(text, &rec); err != nil {
454				return nil, err
455			}
456			if rec.RecordType != "symbol" {
457				continue
458			}
459			out = append(out, rec)
460			if limit > 0 && len(out) >= limit {
461				break
462			}
463		}
464		return out, scanner.Err()
465	}
