504	// ENTIRE_BRAIN_THEME, then the default scheme. A non-empty name that matches no
505	// known theme is an error (so a typo is surfaced, not silently ignored); an
506	// empty name resolves to the default without error.
507	func resolveDashTheme(flagValue string) (tui.Theme, error) {
