528	
529	// containedPath joins a relative path to a base dir, returning "" for an empty,
530	// absolute, rooted, or escaping path. Path values come straight out of on-disk
531	// brain/snapshot files, so a "../"-laden or rooted value must never resolve to an
532	// open target outside the base (the `o` key hands the result to the OS opener).
533	func containedPath(base, rel string) string {
534		// Reject absolute and rooted paths. filepath.IsAbs is OS-specific (on Windows
535		// a leading-slash path like "/etc/passwd" is NOT absolute), so also reject a
536		// leading "/" or "\" explicitly — a rooted path is never a valid relative
537		// anchor on any platform.
538		if rel == "" || filepath.IsAbs(rel) || strings.HasPrefix(rel, "/") || strings.HasPrefix(rel, `\`) {
539			return ""
540		}
541		clean := filepath.Clean(filepath.FromSlash(rel))
542		if clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
543			return ""
544		}
545		full := filepath.Join(base, clean)
546		if r, err := filepath.Rel(base, full); err != nil || r == ".." || strings.HasPrefix(r, ".."+string(filepath.Separator)) {
547			return ""
548		}
549		return full
550	}
