/* entire brain viz — dark theme tokens mirror entire.io/frontend/src/index.css .dark */
:root {
  --surface-sunken: #111111;
  --surface-base: #161616;
  --surface-raised: #1c1c1c;
  --surface-floating: #222222;
  --surface-hover: rgb(255 255 255 / 0.06);
  --surface-active: rgb(255 255 255 / 0.12);
  --surface-selected: rgb(255 255 255 / 0.08);

  --text-default: #f3f3f3;
  --text-muted: #b9b9b9;
  --text-disabled: #707070;

  --border-default: rgb(250 250 250 / 0.10);
  --border-subtle: rgb(250 250 250 / 0.08);

  --accent: #f25333;
  --accent-soft: rgb(242 83 51 / 0.16);
  --focus: var(--accent);

  --k-function: #22d3ee; /* function / method */
  --k-type: #818cf8;     /* type / class / interface / struct */
  --k-value: #fbbf24;    /* const / var / literal */
  --k-entry: #f25333;    /* entry-point / boundary */
  --k-other: #b9b9b9;

  --font-ui: "Entire Headline NEW", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: "Entire Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  --r-sm: 6px;
  --r-md: 10px;
  --r-lg: 14px;

  --shadow-float: 0 2px 4px #00000033, 0 4px 12px -1px #00000040, 0 0 0 1px rgb(255 255 255 / 0.14);
  --ease: cubic-bezier(.2, .7, .2, 1);
}

* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body {
  background: var(--surface-sunken);
  color: var(--text-default);
  font-family: var(--font-ui);
  font-size: 14px;
  line-height: 1.5;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
}
:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; border-radius: 4px; }
button { font: inherit; color: inherit; }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: rgb(255 255 255 / 0.12); border-radius: 999px; border: 2px solid transparent; background-clip: content-box; }
::-webkit-scrollbar-thumb:hover { background: rgb(255 255 255 / 0.2); background-clip: content-box; }

/* ---- app grid ---- */
#app { display: grid; grid-template-columns: 280px 1fr; height: 100%; }
#app.inspector-open { grid-template-columns: 280px 1fr 360px; }

/* ---- left rail ---- */
#rail {
  background: var(--surface-base);
  border-right: 1px solid var(--border-subtle);
  display: flex; flex-direction: column; min-height: 0;
}
.brand { display: flex; align-items: center; gap: 10px; padding: 16px 16px 12px; }
.brand .mark { width: 22px; height: 22px; border-radius: 6px; background: var(--accent); box-shadow: 0 0 16px var(--accent-soft); flex: none; }
.brand .title { font-weight: 600; letter-spacing: -0.01em; }
.brand .sub { color: var(--text-disabled); font-size: 11px; font-family: var(--font-mono); margin-top: 1px; }

.rail-search { padding: 4px 12px 12px; position: relative; }
.rail-search input {
  width: 100%; background: var(--surface-sunken); color: var(--text-default);
  border: 1px solid var(--border-default); border-radius: var(--r-sm);
  padding: 8px 10px 8px 30px; font: inherit; outline: none;
}
.rail-search input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-soft); }
.rail-search .icon { position: absolute; left: 22px; top: 12px; color: var(--text-disabled); pointer-events: none; }
.rail-search .hint { position: absolute; right: 20px; top: 11px; color: var(--text-disabled); font-family: var(--font-mono); font-size: 11px; }

.rail-section { padding: 6px 16px; color: var(--text-disabled); font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; }
.rail-scroll { overflow-y: auto; flex: 1; min-height: 0; }

.result { display: flex; gap: 9px; align-items: baseline; padding: 7px 16px; cursor: pointer; border: none; background: none; width: 100%; text-align: left; }
.result:hover { background: var(--surface-hover); }
.result .dot { width: 8px; height: 8px; border-radius: 50%; flex: none; transform: translateY(1px); }
.result .name { font-family: var(--font-mono); font-size: 12.5px; color: var(--text-default); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.result .meta { color: var(--text-disabled); font-size: 11px; margin-left: auto; flex: none; }

.legend { padding: 10px 16px 16px; border-top: 1px solid var(--border-subtle); display: grid; gap: 7px; }
.legend .row { display: flex; align-items: center; gap: 9px; color: var(--text-muted); font-size: 12px; }
.legend .row .dot { width: 9px; height: 9px; border-radius: 50%; }

.counts { padding: 10px 16px; border-top: 1px solid var(--border-subtle); color: var(--text-muted); font-size: 12px; display: flex; flex-wrap: wrap; gap: 4px 12px; }
.counts b { color: var(--text-default); font-variant-numeric: tabular-nums; font-weight: 600; }

/* ---- stage ---- */
#stage { position: relative; background:
  radial-gradient(1200px 800px at 60% 40%, #191919 0%, var(--surface-sunken) 70%); overflow: hidden; }
#graph { display: block; width: 100%; height: 100%; }
#graph:focus-visible { outline: 2px solid var(--focus); outline-offset: -2px; }

.stage-top { position: absolute; top: 14px; left: 16px; right: 16px; display: flex; align-items: center; gap: 10px; pointer-events: none; }
.crumb { pointer-events: auto; background: var(--surface-floating); border: 1px solid var(--border-default); border-radius: 999px; padding: 6px 12px; font-family: var(--font-mono); font-size: 12px; color: var(--text-muted); box-shadow: var(--shadow-float); max-width: 60%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.stage-tools { margin-left: auto; display: flex; gap: 8px; pointer-events: auto; }
.tool { background: var(--surface-floating); border: 1px solid var(--border-default); border-radius: var(--r-sm); color: var(--text-muted); padding: 6px 10px; font-size: 12px; cursor: pointer; box-shadow: var(--shadow-float); }
.tool:hover { color: var(--text-default); background: var(--surface-raised); }

.tooltip { position: absolute; pointer-events: none; background: var(--surface-floating); border: 1px solid var(--border-default); border-radius: var(--r-sm); box-shadow: var(--shadow-float); padding: 6px 9px; font-family: var(--font-mono); font-size: 12px; color: var(--text-default); transform: translate(-50%, calc(-100% - 12px)); opacity: 0; transition: opacity 120ms var(--ease); max-width: 340px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; z-index: 5; }
.tooltip.show { opacity: 1; }
.tooltip .k { color: var(--text-disabled); }

/* overlays */
.overlay { position: absolute; inset: 0; display: grid; place-items: center; text-align: center; color: var(--text-muted); pointer-events: none; }
.overlay .card { background: var(--surface-floating); border: 1px solid var(--border-default); border-radius: var(--r-lg); box-shadow: var(--shadow-float); padding: 22px 26px; max-width: 380px; pointer-events: auto; }
.overlay h2 { margin: 0 0 6px; font-size: 15px; color: var(--text-default); }
.overlay p { margin: 0; font-size: 13px; }
.overlay code { font-family: var(--font-mono); background: var(--surface-sunken); border: 1px solid var(--border-subtle); border-radius: 5px; padding: 1px 6px; color: var(--text-default); }
.hidden { display: none !important; }

.spinner { width: 26px; height: 26px; border-radius: 50%; border: 2px solid rgb(255 255 255 / 0.1); border-top-color: var(--accent); animation: spin .8s linear infinite; margin: 0 auto 12px; }
@keyframes spin { to { transform: rotate(360deg); } }

/* ---- inspector ---- */
#inspector { background: var(--surface-base); border-left: 1px solid var(--border-subtle); display: flex; flex-direction: column; min-height: 0; transform: translateX(100%); transition: transform 180ms var(--ease); }
#app.inspector-open #inspector { transform: none; }
.insp-head { padding: 16px 16px 12px; border-bottom: 1px solid var(--border-subtle); }
.insp-kind { display: inline-flex; align-items: center; gap: 7px; font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); }
.insp-kind .dot { width: 8px; height: 8px; border-radius: 50%; }
.insp-name { font-family: var(--font-mono); font-size: 16px; color: var(--text-default); margin: 8px 0 2px; word-break: break-word; }
.insp-qual { font-family: var(--font-mono); font-size: 11.5px; color: var(--text-disabled); word-break: break-all; }
.insp-file { font-family: var(--font-mono); font-size: 12px; color: var(--k-function); margin-top: 8px; word-break: break-all; }
.insp-close { position: absolute; top: 12px; right: 12px; background: none; border: none; color: var(--text-disabled); cursor: pointer; font-size: 18px; line-height: 1; padding: 4px; }
.insp-close:hover { color: var(--text-default); }
.insp-actions { display: flex; gap: 8px; padding: 12px 16px; border-bottom: 1px solid var(--border-subtle); }
.insp-actions button { flex: 1; background: var(--surface-raised); border: 1px solid var(--border-default); border-radius: var(--r-sm); color: var(--text-default); padding: 8px; cursor: pointer; font-size: 12.5px; }
.insp-actions button:hover { background: var(--surface-active); }
.insp-actions button.primary { background: var(--accent); border-color: transparent; color: #1a0d09; font-weight: 600; }
.insp-scroll { overflow-y: auto; padding: 12px 16px 24px; flex: 1; min-height: 0; }
.insp-sig { font-family: var(--font-mono); font-size: 12px; color: var(--text-muted); background: var(--surface-sunken); border: 1px solid var(--border-subtle); border-radius: var(--r-sm); padding: 10px; white-space: pre-wrap; word-break: break-word; margin-bottom: 16px; }
.insp-h { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-disabled); margin: 14px 0 8px; }
.neighbor { display: flex; align-items: baseline; gap: 8px; padding: 6px 8px; border-radius: var(--r-sm); cursor: pointer; }
.neighbor:hover { background: var(--surface-hover); }
.neighbor .dot { width: 7px; height: 7px; border-radius: 50%; flex: none; transform: translateY(1px); }
.neighbor .n { font-family: var(--font-mono); font-size: 12.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.neighbor .rel { margin-left: auto; color: var(--text-disabled); font-size: 10.5px; font-family: var(--font-mono); flex: none; }
.empty-note { color: var(--text-disabled); font-size: 12.5px; font-style: italic; }

/* ---- command palette ---- */
#palette { position: fixed; inset: 0; background: rgb(0 0 0 / 0.5); display: grid; place-items: start center; padding-top: 14vh; z-index: 20; }
#palette .box { width: min(600px, 92vw); background: var(--surface-floating); border: 1px solid var(--border-default); border-radius: var(--r-lg); box-shadow: var(--shadow-float); overflow: hidden; }
#palette input { width: 100%; background: none; border: none; border-bottom: 1px solid var(--border-subtle); color: var(--text-default); font: inherit; font-size: 16px; padding: 16px 18px; outline: none; }
#palette .list { max-height: 46vh; overflow-y: auto; }
#palette .item { display: flex; gap: 10px; align-items: baseline; padding: 10px 18px; cursor: pointer; }
#palette .item.active, #palette .item:hover { background: var(--surface-active); }
#palette .item .dot { width: 8px; height: 8px; border-radius: 50%; flex: none; transform: translateY(2px); }
#palette .item .name { font-family: var(--font-mono); font-size: 13.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#palette .item .src { margin-left: auto; color: var(--text-disabled); font-size: 11px; flex: none; }
#palette .foot { padding: 8px 18px; border-top: 1px solid var(--border-subtle); color: var(--text-disabled); font-size: 11px; display: flex; gap: 14px; }
#palette kbd { font-family: var(--font-mono); background: var(--surface-sunken); border: 1px solid var(--border-subtle); border-radius: 4px; padding: 0 5px; font-size: 10.5px; }

@media (prefers-reduced-motion: reduce) {
  * { transition-duration: 0ms !important; animation-duration: 0ms !important; }
}

// graph.js — self-contained Canvas2D force-directed graph with a Barnes-Hut
// quadtree for repulsion. No dependencies. ~1–5K nodes at 60fps.

const REDUCED = matchMedia('(prefers-reduced-motion: reduce)').matches;

function cssVar(name) {
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
}

export function colorForKind(kind) {
  const k = (kind || '').toLowerCase();
  if (/func|method|constructor|closure/.test(k)) return cssVar('--k-function');
  if (/class|struct|interface|type|enum|trait|record|protocol/.test(k)) return cssVar('--k-type');
  if (/const|var|field|property|constant|literal|enum_member/.test(k)) return cssVar('--k-value');
  if (/module|package|file|namespace|entrypoint|entry|main/.test(k)) return cssVar('--k-entry');
  return cssVar('--k-other');
}

export function createGraph(canvas, handlers = {}) {
  const ctx = canvas.getContext('2d');
  let nodes = [], edges = [], byId = new Map();
  let cam = { scale: 1, tx: 0, ty: 0 };
  let alpha = 0, alphaTarget = 0;
  const alphaDecay = 1 - Math.pow(0.001, 1 / 300);
  const velocityDecay = 0.6;
  let hover = null, selected = null, focusSet = null;
  let dirty = true, W = 0, H = 0, dpr = 1;

  // ---------- sizing ----------
  function resize() {
    dpr = Math.min(window.devicePixelRatio || 1, 2);
    const r = canvas.getBoundingClientRect();
    W = r.width; H = r.height;
    canvas.width = Math.round(W * dpr);
    canvas.height = Math.round(H * dpr);
    dirty = true;
  }
  new ResizeObserver(resize).observe(canvas);
  resize();

  // ---------- data ----------
  function radius(n) { return Math.min(3 + Math.sqrt(n.degree || 0) * 1.5, 16); }

  function setData(rawNodes, rawEdges) {
    byId = new Map();
    nodes = rawNodes.map((d) => {
      const angle = Math.random() * Math.PI * 2, rad = 60 + Math.random() * 380;
      const n = { ...d, x: Math.cos(angle) * rad, y: Math.sin(angle) * rad, vx: 0, vy: 0, degree: 0, fixed: false };
      byId.set(n.id, n);
      return n;
    });
    edges = [];
    for (const e of rawEdges) {
      const s = byId.get(e.from), t = byId.get(e.to);
      if (!s || !t || s === t) continue;
      s.degree++; t.degree++;
      edges.push({ ...e, source: s, target: t });
    }
    selected = null; hover = null; focusSet = null;
    reheat(1);
    zoomToFit(false);
  }

  function mergeData(rawNodes, rawEdges) {
    let added = 0;
    const anchor = selected || nodes[0] || { x: 0, y: 0 };
    for (const d of rawNodes) {
      if (byId.has(d.id)) continue;
      const a = Math.random() * Math.PI * 2, rad = 30 + Math.random() * 40;
      const n = { ...d, x: anchor.x + Math.cos(a) * rad, y: anchor.y + Math.sin(a) * rad, vx: 0, vy: 0, degree: 0, fixed: false };
      byId.set(n.id, n); nodes.push(n); added++;
    }
    const seen = new Set(edges.map((e) => e.from + '�' + e.to + '�' + e.type));
    for (const e of rawEdges) {
      const key = e.from + '�' + e.to + '�' + e.type;
      if (seen.has(key)) continue;
      const s = byId.get(e.from), t = byId.get(e.to);
      if (!s || !t || s === t) continue;
      s.degree++; t.degree++; edges.push({ ...e, source: s, target: t }); seen.add(key);
    }
    reheat(0.5);
    return added;
  }

  // ---------- simulation ----------
  function reheat(a = 0.6) { alpha = Math.max(alpha, a); dirty = true; if (REDUCED) settle(); }
  function settle() { for (let i = 0; i < 400 && alpha > 0.001; i++) tick(); alpha = 0; dirty = true; }

  function buildQuadtree() {
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    for (const n of nodes) { if (n.x < x0) x0 = n.x; if (n.y < y0) y0 = n.y; if (n.x > x1) x1 = n.x; if (n.y > y1) y1 = n.y; }
    if (!isFinite(x0)) return null;
    const size = Math.max(x1 - x0, y1 - y0, 1) + 1;
    const root = { cx: (x0 + x1) / 2, cy: (y0 + y1) / 2, half: size / 2, mass: 0, mx: 0, my: 0, node: null, kids: null };
    const insert = (q, n, depth) => {
      q.mass++; q.mx += n.x; q.my += n.y;
      if (!q.kids && !q.node) { q.node = n; return; }
      if (!q.kids) {
        q.kids = [null, null, null, null];
        const old = q.node; q.node = null;
        if (old) place(q, old, depth);
      }
      place(q, n, depth);
    };
    const place = (q, n, depth) => {
      const i = (n.x >= q.cx ? 1 : 0) + (n.y >= q.cy ? 2 : 0);
      let k = q.kids[i];
      if (!k) {
        const h = q.half / 2;
        k = q.kids[i] = { cx: q.cx + (i & 1 ? h : -h), cy: q.cy + (i & 2 ? h : -h), half: h, mass: 0, mx: 0, my: 0, node: null, kids: null };
      }
      if (depth > 24) { k.mass++; k.mx += n.x; k.my += n.y; k.node = k.node || n; return; }
      insert(k, n, depth + 1);
    };
    for (const n of nodes) insert(root, n, 0);
    return root;
  }

  function applyCharge() {
    const root = buildQuadtree();
    if (!root) return;
    const theta2 = 0.81, strength = -34 * alpha;
    for (const n of nodes) {
      const stack = [root];
      while (stack.length) {
        const q = stack.pop();
        if (!q || q.mass === 0) continue;
        const cxm = q.mx / q.mass, cym = q.my / q.mass;
        let dx = cxm - n.x, dy = cym - n.y;
        let d2 = dx * dx + dy * dy;
        const w = q.half * 2;
        if (q.node === n && !q.kids) continue;
        if (!q.kids || (w * w) / (d2 || 1e-6) < theta2) {
          if (d2 < 1) { d2 = 1; dx += (Math.random() - 0.5) * 0.5; dy += (Math.random() - 0.5) * 0.5; }
          const f = (strength * q.mass) / d2;
          n.vx += dx * f; n.vy += dy * f;
        } else {
          for (const k of q.kids) if (k) stack.push(k);
        }
      }
    }
  }

  function applyLinks() {
    const dist = 46, k = 0.06 * alpha;
    for (const e of edges) {
      const s = e.source, t = e.target;
      let dx = t.x - s.x, dy = t.y - s.y;
      let d = Math.sqrt(dx * dx + dy * dy) || 1e-6;
      const f = ((d - dist) / d) * k;
      dx *= f; dy *= f;
      if (!t.fixed) { t.vx -= dx; t.vy -= dy; }
      if (!s.fixed) { s.vx += dx; s.vy += dy; }
    }
  }

  function applyGravity() {
    const g = 0.045 * alpha;
    for (const n of nodes) { n.vx -= n.x * g; n.vy -= n.y * g; }
  }

  function tick() {
    if (alpha < 0.001) return;
    alpha += (alphaTarget - alpha) * alphaDecay;
    applyCharge(); applyLinks(); applyGravity();
    for (const n of nodes) {
      if (n.fixed) { n.vx = 0; n.vy = 0; continue; }
      n.vx *= velocityDecay; n.vy *= velocityDecay;
      n.x += n.vx; n.y += n.vy;
    }
    dirty = true;
  }

  // ---------- camera ----------
  const toScreen = (x, y) => [(x * cam.scale) + cam.tx, (y * cam.scale) + cam.ty];
  const toWorld = (sx, sy) => [(sx - cam.tx) / cam.scale, (sy - cam.ty) / cam.scale];

  function zoomToFit(animate = true) {
    if (!nodes.length) return;
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    for (const n of nodes) { x0 = Math.min(x0, n.x); y0 = Math.min(y0, n.y); x1 = Math.max(x1, n.x); y1 = Math.max(y1, n.y); }
    const pad = 80, gw = Math.max(x1 - x0, 1), gh = Math.max(y1 - y0, 1);
    const s = Math.min((W - pad) / gw, (H - pad) / gh, 2.2);
    const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
    const target = { scale: s, tx: W / 2 - cx * s, ty: H / 2 - cy * s };
    animate && !REDUCED ? tweenCam(target) : (cam = target, dirty = true);
  }

  let camTween = null;
  function tweenCam(target) {
    const from = { ...cam }, t0 = performance.now(), dur = 420;
    camTween = () => {
      const p = Math.min((performance.now() - t0) / dur, 1);
      const e = 1 - Math.pow(1 - p, 3);
      cam.scale = from.scale + (target.scale - from.scale) * e;
      cam.tx = from.tx + (target.tx - from.tx) * e;
      cam.ty = from.ty + (target.ty - from.ty) * e;
      dirty = true;
      if (p >= 1) camTween = null;
    };
  }

  function focus(id) {
    const n = byId.get(id); if (!n) return;
    selected = n;
    focusSet = new Set([n.id]);
    for (const e of edges) { if (e.source === n) focusSet.add(e.target.id); if (e.target === n) focusSet.add(e.source.id); }
    const target = { scale: Math.max(cam.scale, 1.1), tx: W / 2 - n.x * Math.max(cam.scale, 1.1), ty: H / 2 - n.y * Math.max(cam.scale, 1.1) };
    REDUCED ? (cam = target) : tweenCam(target);
    dirty = true;
  }
  function clearFocus() { selected = null; focusSet = null; dirty = true; }

  // ---------- rendering ----------
  function draw() {
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);
    const showLabels = cam.scale > 0.9;
    const hi = hover || selected;
    const incident = hi ? new Set() : null;
    if (hi) for (const e of edges) { if (e.source === hi || e.target === hi) { incident.add(e); } }

    // edges
    ctx.lineWidth = 1;
    for (const e of edges) {
      const [x1, y1] = toScreen(e.source.x, e.source.y);
      const [x2, y2] = toScreen(e.target.x, e.target.y);
      let a = 0.16;
      let col = '185,185,185';
      if (hi) {
        if (incident.has(e)) { a = 0.85; col = hexToRgb(colorForKind(e.source.kind)); }
        else a = 0.04;
      } else if (focusSet && (focusSet.has(e.source.id) && focusSet.has(e.target.id))) {
        a = 0.5;
      }
      ctx.strokeStyle = `rgba(${col},${a})`;
      ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
      if (incident && incident.has(e)) drawArrow(x1, y1, x2, y2, radius(e.target) * cam.scale);
    }

    // nodes
    for (const n of nodes) {
      const [x, y] = toScreen(n.x, n.y);
      if (x < -50 || y < -50 || x > W + 50 || y > H + 50) continue;
      const r = Math.max(radius(n) * cam.scale, 1.5);
      const col = colorForKind(n.kind);
      const dim = hi && n !== hi && !(incident && [...incident].some((e) => e.source === n || e.target === n));
      const focusDim = !hi && focusSet && !focusSet.has(n.id);
      ctx.globalAlpha = (dim || focusDim) ? 0.28 : 1;
      if (n === hi || n === selected) { ctx.shadowColor = col; ctx.shadowBlur = 16; }
      ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2);
      ctx.fillStyle = col; ctx.fill();
      ctx.shadowBlur = 0;
      if (n === selected) { ctx.lineWidth = 2; ctx.strokeStyle = '#fff'; ctx.stroke(); }
      else if (n.fixed) { ctx.lineWidth = 1.5; ctx.strokeStyle = 'rgba(255,255,255,0.5)'; ctx.stroke(); }
      if (showLabels && (n.degree > 1 || n === hi || n === selected)) {
        ctx.globalAlpha = (dim || focusDim) ? 0.25 : 0.92;
        ctx.fillStyle = '#f3f3f3';
        ctx.font = '11px ui-monospace, Menlo, monospace';
        ctx.textAlign = 'center';
        const label = n.name || n.id;
        ctx.fillText(label.length > 28 ? label.slice(0, 27) + '…' : label, x, y - r - 5);
      }
      ctx.globalAlpha = 1;
    }
  }

  function drawArrow(x1, y1, x2, y2, back) {
    const ang = Math.atan2(y2 - y1, x2 - x1);
    const ex = x2 - Math.cos(ang) * (back + 3), ey = y2 - Math.sin(ang) * (back + 3);
    const s = 6;
    ctx.fillStyle = 'rgba(242,83,51,0.9)';
    ctx.beginPath();
    ctx.moveTo(ex, ey);
    ctx.lineTo(ex - Math.cos(ang - 0.4) * s, ey - Math.sin(ang - 0.4) * s);
    ctx.lineTo(ex - Math.cos(ang + 0.4) * s, ey - Math.sin(ang + 0.4) * s);
    ctx.closePath(); ctx.fill();
  }

  function hexToRgb(hex) {
    hex = (hex || '').replace('#', '');
    if (hex.length === 3) hex = hex.split('').map((c) => c + c).join('');
    const n = parseInt(hex || 'b9b9b9', 16);
    return `${(n >> 16) & 255},${(n >> 8) & 255},${n & 255}`;
  }

  // ---------- loop ----------
  function frame() {
    if (camTween) camTween();
    if (alpha >= 0.001) tick();
    if (dirty) { draw(); dirty = false; }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);

  // ---------- picking + interaction ----------
  function pick(sx, sy) {
    const [wx, wy] = toWorld(sx, sy);
    let best = null, bestD = Infinity;
    for (const n of nodes) {
      const dx = n.x - wx, dy = n.y - wy, d = dx * dx + dy * dy;
      const rr = Math.pow((radius(n) + 7) / cam.scale, 2);
      if (d < rr && d < bestD) { bestD = d; best = n; }
    }
    return best;
  }

  let drag = null, panning = null, moved = false;
  canvas.addEventListener('pointerdown', (ev) => {
    canvas.setPointerCapture(ev.pointerId);
    moved = false;
    const rect = canvas.getBoundingClientRect();
    const sx = ev.clientX - rect.left, sy = ev.clientY - rect.top;
    const n = pick(sx, sy);
    if (n) { drag = { n, sx, sy }; n.fixed = true; }
    else { panning = { sx, sy, tx: cam.tx, ty: cam.ty }; }
  });
  canvas.addEventListener('pointermove', (ev) => {
    const rect = canvas.getBoundingClientRect();
    const sx = ev.clientX - rect.left, sy = ev.clientY - rect.top;
    if (drag) {
      moved = true;
      const [wx, wy] = toWorld(sx, sy);
      drag.n.x = wx; drag.n.y = wy; drag.n.vx = 0; drag.n.vy = 0;
      reheat(0.3); dirty = true; return;
    }
    if (panning) { moved = true; cam.tx = panning.tx + (sx - panning.sx); cam.ty = panning.ty + (sy - panning.sy); dirty = true; return; }
    const n = pick(sx, sy);
    if (n !== hover) { hover = n; dirty = true; handlers.onHover && handlers.onHover(n, ev.clientX, ev.clientY); }
    else if (n) handlers.onHover && handlers.onHover(n, ev.clientX, ev.clientY);
    canvas.style.cursor = n ? 'pointer' : 'grab';
  });
  canvas.addEventListener('pointerup', (ev) => {
    const rect = canvas.getBoundingClientRect();
    const sx = ev.clientX - rect.left, sy = ev.clientY - rect.top;
    if (drag) { if (!moved) drag.n.fixed = false; const n = drag.n; drag = null; if (!moved) { handlers.onClick && handlers.onClick(n); } return; }
    if (panning) { const wasClick = !moved; panning = null; if (wasClick) { handlers.onBackground && handlers.onBackground(); } }
  });
  canvas.addEventListener('dblclick', (ev) => {
    const rect = canvas.getBoundingClientRect();
    const n = pick(ev.clientX - rect.left, ev.clientY - rect.top);
    if (n) handlers.onExpand && handlers.onExpand(n);
  });
  canvas.addEventListener('wheel', (ev) => {
    ev.preventDefault();
    const rect = canvas.getBoundingClientRect();
    const sx = ev.clientX - rect.left, sy = ev.clientY - rect.top;
    const [wx, wy] = toWorld(sx, sy);
    const factor = Math.exp(-ev.deltaY * 0.0015);
    cam.scale = Math.max(0.05, Math.min(cam.scale * factor, 8));
    cam.tx = sx - wx * cam.scale; cam.ty = sy - wy * cam.scale;
    dirty = true;
  }, { passive: false });

  return {
    setData, mergeData, focus, clearFocus, zoomToFit,
    getNode: (id) => byId.get(id),
    reheat,
    get count() { return nodes.length; },
  };
}

// app.js — wires the API to the graph, inspector, search, and ⌘K palette.
import { createGraph, colorForKind } from './graph.js';

const $ = (id) => document.getElementById(id);
const app = $('app');
let graph = null;
let currentSel = null;

async function api(path) {
  const res = await fetch(path, { headers: { Accept: 'application/json' } });
  if (!res.ok) throw new Error(`${path}: ${res.status}`);
  return res.json();
}
function debounce(fn, ms) { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; }
const esc = (s) => (s || '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

// ---------- boot ----------
(async function boot() {
  graph = createGraph($('graph'), {
    onHover: showTooltip,
    onClick: (n) => openNode(n.id),
    onExpand: expandNode,
    onBackground: closeInspector,
  });

  try {
    const summary = await api('/api/summary');
    renderSummary(summary);
  } catch (e) { /* summary is best-effort */ }

  try {
    const g = await api('/api/graph');
    $('loading').classList.add('hidden');
    if (!g.nodes || g.nodes.length === 0) {
      showEmpty(g.warnings);
      return;
    }
    graph.setData(g.nodes, g.edges || []);
    $('results-label').textContent = `${g.nodes.length} symbols` + (g.truncated ? ` of ${g.total} — raise --limit` : '');
  } catch (e) {
    $('loading').classList.add('hidden');
    showEmpty([String(e.message || e)]);
  }
})();

function renderSummary(s) {
  $('brand-sub').textContent = [s.repo ? s.repo.split('/').pop() : '', s.branch].filter(Boolean).join(' · ') || 'viz';
  const c = s.counts || {};
  const parts = [
    ['symbols', c.symbols], ['relations', c.relations], ['files', c.files],
    ['facts', c.facts], ['history', c.history], ['sessions', c.sessions],
  ].filter(([, v]) => v > 0).map(([k, v]) => `<span>${k} <b>${v}</b></span>`);
  $('counts').innerHTML = parts.join('');
}

function showEmpty(warnings) {
  const box = $('empty');
  box.classList.remove('hidden');
  if (warnings && warnings.length) {
    $('empty-title').textContent = 'Nothing to show yet';
    $('empty-body').innerHTML = warnings.map(esc).join('<br>') + '<br><br>Run <code>entire brain refresh</code>, then reopen viz.';
  }
}

// ---------- tooltip ----------
const tip = $('tooltip');
function showTooltip(n, clientX, clientY) {
  if (!n) { tip.classList.remove('show'); return; }
  const file = n.file ? `<br><span class="k">${esc(n.file)}${n.line ? ':' + n.line : ''}</span>` : '';
  tip.innerHTML = `<span style="color:${colorForKind(n.kind)}">${esc(n.name || n.id)}</span> <span class="k">${esc(n.kind)}</span>${file}`;
  tip.style.left = clientX + 'px';
  tip.style.top = clientY + 'px';
  tip.classList.add('show');
}

// ---------- inspector ----------
async function openNode(id) {
  currentSel = id;
  graph.focus(id);
  app.classList.add('inspector-open');
  const base = graph.getNode(id) || { id };
  paintInspectorHead(base);
  $('insp-body').innerHTML = '<div class="empty-note">Loading…</div>';
  try {
    const d = await api('/api/node?id=' + encodeURIComponent(id));
    if (currentSel !== id) return;
    paintInspectorHead(d.symbol || base);
    paintInspectorBody(d);
  } catch (e) {
    $('insp-body').innerHTML = `<div class="empty-note">Could not load: ${esc(String(e.message || e))}</div>`;
  }
}

function paintInspectorHead(n) {
  const col = colorForKind(n.kind);
  const kind = $('insp-kind');
  kind.querySelector('.dot').style.background = col;
  kind.querySelector('span:last-child').textContent = n.kind || 'symbol';
  $('insp-name').textContent = n.name || n.id;
  $('insp-qual').textContent = n.qualified_name && n.qualified_name !== n.name ? n.qualified_name : '';
  $('insp-file').textContent = n.file ? n.file + (n.line ? ':' + n.line : '') : '';
}

function paintInspectorBody(d) {
  const sel = d.symbol || {};
  let html = '';
  if (sel.signature) html += `<div class="insp-sig">${esc(sel.signature)}</div>`;
  if (d.snippet && d.snippet.trim() && d.snippet.trim() !== (sel.signature || '').trim()) {
    html += `<div class="insp-h">Source</div><div class="insp-sig">${esc(d.snippet.slice(0, 1400))}</div>`;
  }
  const neighbors = d.neighbors || [];
  html += `<div class="insp-h">Neighbors · ${neighbors.length}</div>`;
  if (!neighbors.length) html += `<div class="empty-note">No linked symbols.</div>`;
  else {
    const relOf = (nid) => {
      for (const r of d.relations || []) {
        if (r.from === sel.id && r.to === nid) return '→ ' + r.type;
        if (r.to === sel.id && r.from === nid) return '← ' + r.type;
      }
      return '';
    };
    html += neighbors.map((nb) =>
      `<div class="neighbor" data-id="${esc(nb.id)}"><span class="dot" style="background:${colorForKind(nb.kind)}"></span>` +
      `<span class="n" title="${esc(nb.qualified_name || nb.name)}">${esc(nb.name || nb.id)}</span>` +
      `<span class="rel">${esc(relOf(nb.id))}</span></div>`).join('');
  }
  const body = $('insp-body');
  body.innerHTML = html;
  body.querySelectorAll('.neighbor').forEach((el) => el.addEventListener('click', () => openNode(el.dataset.id)));
}

async function expandNode(n) {
  try {
    const d = await api('/api/node?id=' + encodeURIComponent(n.id));
    const added = graph.mergeData(d.neighbors || [], d.relations || []);
    if (added > 0) graph.reheat(0.6);
  } catch (e) { /* best-effort */ }
}

function closeInspector() { app.classList.remove('inspector-open'); currentSel = null; graph && graph.clearFocus(); }
$('insp-close').addEventListener('click', closeInspector);
$('insp-focus').addEventListener('click', () => currentSel && graph.focus(currentSel));
$('insp-expand').addEventListener('click', () => { const n = currentSel && graph.getNode(currentSel); if (n) expandNode(n); });
$('fit').addEventListener('click', () => graph.zoomToFit());

// ---------- rail search ----------
const results = $('results');
const runSearch = debounce(async (q) => {
  if (!q.trim()) { results.innerHTML = ''; $('results-label').textContent = 'Graph'; $('legend').classList.remove('hidden'); return; }
  $('legend').classList.add('hidden');
  try {
    const r = await api('/api/search?q=' + encodeURIComponent(q));
    renderResults(results, r.hits || []);
    $('results-label').textContent = `${(r.hits || []).length} results`;
  } catch (e) { results.innerHTML = `<div class="empty-note" style="padding:8px 16px">search failed</div>`; }
}, 160);
$('search').addEventListener('input', (e) => runSearch(e.target.value));

function renderResults(container, hits) {
  if (!hits.length) { container.innerHTML = `<div class="empty-note" style="padding:8px 16px">No matches</div>`; return; }
  container.innerHTML = hits.map((h, i) => {
    const col = h.source === 'symbol' ? colorForKind(h.kind) : 'var(--text-disabled)';
    return `<button class="result" data-i="${i}"><span class="dot" style="background:${col}"></span>` +
      `<span class="name" title="${esc(h.text || h.title)}">${esc(h.title || h.text || h.id)}</span>` +
      `<span class="meta">${esc(h.source)}</span></button>`;
  }).join('');
  container.querySelectorAll('.result').forEach((el) => el.addEventListener('click', () => selectHit(hits[+el.dataset.i])));
}

function selectHit(h) {
  if (h.source === 'symbol' && graph.getNode(h.id)) { openNode(h.id); return; }
  if (h.source === 'symbol') { openNode(h.id); return; } // may 404 gracefully
  // non-graph memory hit: show its text in the inspector
  app.classList.add('inspector-open');
  currentSel = null;
  $('insp-kind').querySelector('.dot').style.background = 'var(--text-disabled)';
  $('insp-kind').querySelector('span:last-child').textContent = h.source;
  $('insp-name').textContent = h.title || h.source;
  $('insp-qual').textContent = h.path || '';
  $('insp-file').textContent = '';
  $('insp-body').innerHTML = `<div class="insp-sig">${esc(h.text || '')}</div>`;
}

// ---------- ⌘K palette ----------
const pal = $('palette'), palInput = $('palette-input'), palList = $('palette-list');
let palHits = [], palActive = 0;
function openPalette() { pal.classList.remove('hidden'); palInput.value = ''; palList.innerHTML = ''; palHits = []; palActive = 0; palInput.focus(); }
function closePalette() { pal.classList.add('hidden'); }
const runPalette = debounce(async (q) => {
  if (!q.trim()) { palList.innerHTML = ''; palHits = []; return; }
  try {
    const r = await api('/api/search?q=' + encodeURIComponent(q));
    palHits = r.hits || []; palActive = 0; renderPalette();
  } catch (e) { palList.innerHTML = `<div class="item"><span class="name">search failed</span></div>`; }
}, 140);
function renderPalette() {
  palList.innerHTML = palHits.map((h, i) => {
    const col = h.source === 'symbol' ? colorForKind(h.kind) : 'var(--text-disabled)';
    return `<div class="item ${i === palActive ? 'active' : ''}" data-i="${i}"><span class="dot" style="background:${col}"></span>` +
      `<span class="name">${esc(h.title || h.text || h.id)}</span><span class="src">${esc(h.source)}</span></div>`;
  }).join('');
  palList.querySelectorAll('.item').forEach((el) => el.addEventListener('click', () => { closePalette(); selectHit(palHits[+el.dataset.i]); }));
  const active = palList.querySelector('.item.active');
  active && active.scrollIntoView({ block: 'nearest' });
}
palInput.addEventListener('input', (e) => runPalette(e.target.value));
palInput.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowDown') { e.preventDefault(); palActive = Math.min(palActive + 1, palHits.length - 1); renderPalette(); }
  else if (e.key === 'ArrowUp') { e.preventDefault(); palActive = Math.max(palActive - 1, 0); renderPalette(); }
  else if (e.key === 'Enter') { e.preventDefault(); if (palHits[palActive]) { closePalette(); selectHit(palHits[palActive]); } }
});
pal.addEventListener('click', (e) => { if (e.target === pal) closePalette(); });

// ---------- global keys ----------
window.addEventListener('keydown', (e) => {
  const typing = /^(INPUT|TEXTAREA)$/.test(document.activeElement.tagName);
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); pal.classList.contains('hidden') ? openPalette() : closePalette(); return; }
  if (e.key === 'Escape') { if (!pal.classList.contains('hidden')) return closePalette(); if (app.classList.contains('inspector-open')) return closeInspector(); }
  if (typing) return;
  if (e.key === '/') { e.preventDefault(); $('search').focus(); }
  else if (e.key === '0') { e.preventDefault(); graph && graph.zoomToFit(); }
});

package entirebrain

import "embed"

// WebUI holds the embedded static assets for the `entire brain viz` local web
// interface (webui/dist). It lives at the module root because go:embed cannot
// reference parent directories, mirroring Templates and EmbedModel — so
// internal/cli serves it via entirebrain.WebUI. The assets are hand-authored and
// fully self-contained (no CDN); they are served from a loopback-only server, so
// the plugin stays a single static binary with no network dependency.
//
//go:embed webui/dist
var WebUI embed.FS

package cli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"net"
	"net/http"
	"os/exec"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"time"

	"github.com/spf13/cobra"

	entirebrain "github.com/ashtom/entire-brain"
)

// vizDefaultLimit caps how many symbols load into the graph. Large brains hold
// many thousands of symbols; the cap keeps the force simulation smooth and a
// "truncated" flag tells the UI to surface it. 0 = no cap.
const vizDefaultLimit = 4000

type vizFlags struct {
	port   int
	branch string
	noOpen bool
	limit  int
}

// newVizCommand builds `entire brain viz` — a local, no-egress web interface
// that renders the brain's semantic graph. It mirrors newDashCommand's shape
// (dash.go) but serves a browser UI instead of a terminal TUI.
func newVizCommand(opts Options) *cobra.Command {
	var flags vizFlags
	cmd := &cobra.Command{
		Use:   "viz [path]",
		Short: "Explore the brain as a visual graph in your browser (local, offline)",
		Long: `viz starts a local, no-egress web interface that renders the brain's
semantic graph — code entities and their CALLS/IMPORTS relations — as an
explorable, force-directed graph with search and a symbol inspector.

It binds to 127.0.0.1 only, serves a self-contained embedded UI (no CDN), and
reads the brain from disk read-only: no agent calls, no outbound network.`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runViz(cmd.Context(), cmd, opts, flags, agentSurfaceTarget(opts, args))
		},
	}
	cmd.Flags().IntVar(&flags.port, "port", 0, "Port to bind on 127.0.0.1 (0 = auto-pick a free port)")
	cmd.Flags().StringVar(&flags.branch, "branch", "", "Branch whose brain to load (default: current branch)")
	cmd.Flags().BoolVar(&flags.noOpen, "no-open", false, "Do not open a browser automatically")
	cmd.Flags().IntVar(&flags.limit, "limit", vizDefaultLimit, "Max symbols loaded into the graph (0 = no cap)")
	return cmd
}

// vizServer holds the resolved brain location for the lifetime of one server.
// Like the dashboard, it captures a single brain (brainDir/branch/manifest) at
// startup; re-run `viz` to pick up a fresh `refresh`.
type vizServer struct {
	opts     Options
	target   string
	repoDir  string
	brainDir string
	branch   string
	manifest *exportManifest
	limit    int
}

func runViz(ctx context.Context, cmd *cobra.Command, opts Options, flags vizFlags, target string) error {
	repoDir, brainDir, branch, err := resolveFactsTarget(ctx, opts, target, flags.branch)
	if err != nil {
		return err
	}

	// Best-effort: an unbuilt brain still serves — the UI shows an empty state
	// ("run `entire brain refresh`") rather than failing the command.
	var manifest *exportManifest
	if status, serr := buildBrainStatusReport(ctx, opts, target); serr == nil {
		manifest = status.Manifest
	}

	srv := &vizServer{opts: opts, target: target, repoDir: repoDir, brainDir: brainDir, branch: branch, manifest: manifest, limit: flags.limit}

	// Loopback only — never 0.0.0.0. The interface is a personal, read-only view
	// of local data and must not be reachable off-host.
	ln, err := net.Listen("tcp", "127.0.0.1:"+strconv.Itoa(flags.port))
	if err != nil {
		return fmt.Errorf("bind viz server: %w", err)
	}
	url := "http://" + ln.Addr().String()
	fmt.Fprintf(cmd.OutOrStdout(), "entire brain viz — %s\n", url)
	fmt.Fprintln(cmd.OutOrStdout(), "Read-only, loopback-only, no network. Press Ctrl-C to stop.")
	if !flags.noOpen {
		openBrowser(url)
	}

	httpSrv := &http.Server{Handler: vizSecurityHeaders(srv.mux()), ReadHeaderTimeout: 5 * time.Second}
	go func() {
		<-ctx.Done()
		shutCtx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
		defer cancel()
		_ = httpSrv.Shutdown(shutCtx)
	}()
	if err := httpSrv.Serve(ln); err != nil && !errors.Is(err, http.ErrServerClosed) {
		return fmt.Errorf("viz server: %w", err)
	}
	return nil
}

func (s *vizServer) mux() http.Handler {
	m := http.NewServeMux()
	m.HandleFunc("/api/summary", s.handleSummary)
	m.HandleFunc("/api/graph", s.handleGraph)
	m.HandleFunc("/api/node", s.handleNode)
	m.HandleFunc("/api/search", s.handleSearch)
	if sub, err := fs.Sub(entirebrain.WebUI, "webui/dist"); err == nil {
		m.Handle("/", http.FileServer(http.FS(sub)))
	}
	return m
}

// vizSecurityHeaders makes the no-egress guarantee machine-checkable: the CSP
// forbids any off-origin fetch (script/style/img/font/connect all 'self'), so
// even a compromised asset can't call home. Structural, not just a comment.
func vizSecurityHeaders(next http.Handler) http.Handler {
	const csp = "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; font-src 'self'; base-uri 'none'; frame-ancestors 'none'"
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Security-Policy", csp)
		w.Header().Set("X-Content-Type-Options", "nosniff")
		w.Header().Set("Referrer-Policy", "no-referrer")
		next.ServeHTTP(w, r)
	})
}

// ---- JSON view models (clean shapes; never leak raw semanticRecord) ----

type vizNode struct {
	ID            string `json:"id"`
	Name          string `json:"name"`
	QualifiedName string `json:"qualified_name,omitempty"`
	Kind          string `json:"kind"`
	File          string `json:"file,omitempty"`
	Line          int    `json:"line,omitempty"`
	Language      string `json:"language,omitempty"`
	Signature     string `json:"signature,omitempty"`
	ContainerID   string `json:"container_id,omitempty"`
}

type vizEdge struct {
	From       string  `json:"from"`
	To         string  `json:"to"`
	Type       string  `json:"type"`
	Confidence float64 `json:"confidence,omitempty"`
	Scope      string  `json:"scope,omitempty"`
	Resolution string  `json:"resolution,omitempty"`
}

type vizGraphResp struct {
	Nodes     []vizNode `json:"nodes"`
	Edges     []vizEdge `json:"edges"`
	Total     int       `json:"total,omitempty"`
	Truncated bool      `json:"truncated,omitempty"`
	Warnings  []string  `json:"warnings,omitempty"`
}

type vizNodeResp struct {
	Symbol    vizNode   `json:"symbol"`
	Neighbors []vizNode `json:"neighbors"`
	Relations []vizEdge `json:"relations"`
	Snippet   string    `json:"snippet,omitempty"`
	Warnings  []string  `json:"warnings,omitempty"`
}

type vizCounts struct {
	Symbols   int `json:"symbols"`
	Relations int `json:"relations"`
	Files     int `json:"files"`
	History   int `json:"history"`
	Facts     int `json:"facts"`
	Sessions  int `json:"sessions"`
}

type vizSummaryResp struct {
	Repo        string    `json:"repo"`
	Branch      string    `json:"branch"`
	GeneratedAt string    `json:"generated_at,omitempty"`
	Counts      vizCounts `json:"counts"`
	Warnings    []string  `json:"warnings,omitempty"`
}

type vizHit struct {
	Source string  `json:"source"`
	ID     string  `json:"id"`
	Title  string  `json:"title,omitempty"`
	Text   string  `json:"text,omitempty"`
	Kind   string  `json:"kind,omitempty"`
	Path   string  `json:"path,omitempty"`
	Line   int     `json:"line,omitempty"`
	Score  float64 `json:"score,omitempty"`
}

type vizSearchResp struct {
	Hits []vizHit `json:"hits"`
}

func nodeJSON(r semanticRecord) vizNode {
	return vizNode{
		ID: r.ID, Name: r.Name, QualifiedName: r.QualifiedName, Kind: r.Kind,
		File: r.FilePath, Line: r.StartLine, Language: r.Language,
		Signature: r.Signature, ContainerID: r.ContainerID,
	}
}

func edgeJSON(r semanticRecord) vizEdge {
	return vizEdge{From: r.FromID, To: r.ToID, Type: r.Type, Confidence: r.Confidence, Scope: r.RelationScope, Resolution: r.Resolution}
}

// ---- handlers ----

func (s *vizServer) handleSummary(w http.ResponseWriter, r *http.Request) {
	resp := vizSummaryResp{Repo: s.repoDir, Branch: s.branch}
	if status, err := buildBrainStatusReport(r.Context(), s.opts, s.target); err == nil {
		if status.Repo.Root != "" {
			resp.Repo = status.Repo.Root
		}
		resp.GeneratedAt = status.Brain.GeneratedAt
		resp.Warnings = status.Warnings
		if m := status.Manifest; m != nil && m.Sources != nil {
			if sem := m.Sources.Semantic; sem != nil {
				resp.Counts.Symbols = sem.Symbols
				resp.Counts.Relations = sem.Relations
				resp.Counts.Files = sem.Files
			}
			if h := m.Sources.History; h != nil {
				resp.Counts.History = h.Records
			}
			if f := m.Sources.Facts; f != nil {
				resp.Counts.Facts = f.Facts
			}
			if ss := m.Sources.Sessions; ss != nil {
				resp.Counts.Sessions = len(ss.Sessions)
			}
		}
	}
	writeJSONHTTP(w, http.StatusOK, resp)
}

func (s *vizServer) semanticSource() *semanticSourceManifest {
	if s.manifest == nil || s.manifest.Sources == nil {
		return nil
	}
	return s.manifest.Sources.Semantic
}

func (s *vizServer) handleGraph(w http.ResponseWriter, r *http.Request) {
	limit := s.limit
	if v := r.URL.Query().Get("limit"); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			limit = n
		}
	}
	resp := vizGraphResp{Nodes: []vizNode{}, Edges: []vizEdge{}}
	sem := s.semanticSource()
	if sem == nil {
		resp.Warnings = append(resp.Warnings, "no semantic graph yet — run `entire brain refresh`")
		writeJSONHTTP(w, http.StatusOK, resp)
		return
	}
	syms, err := loadSemanticSymbols(s.brainDir, sem, limit)
	if err != nil {
		resp.Warnings = append(resp.Warnings, "semantic symbols: "+err.Error())
		writeJSONHTTP(w, http.StatusOK, resp)
		return
	}
	if len(syms) == 0 {
		resp.Warnings = append(resp.Warnings, "the semantic snapshot has no symbols yet — run `entire brain refresh`")
		writeJSONHTTP(w, http.StatusOK, resp)
		return
	}
	resp.Total = sem.Symbols
	resp.Truncated = sem.Symbols > len(syms)

	idset := make(map[string]bool, len(syms))
	for i := range syms {
		resp.Nodes = append(resp.Nodes, nodeJSON(syms[i]))
		idset[syms[i].ID] = true
	}
	relLimit := limit * 4
	if relLimit <= 0 {
		relLimit = 0
	}
	if rels, rerr := s.relationsForSymbols(sem, syms, relLimit); rerr != nil {
		resp.Warnings = append(resp.Warnings, "relations: "+rerr.Error())
	} else {
		for i := range rels {
			e := rels[i]
			if idset[e.FromID] && idset[e.ToID] {
				resp.Edges = append(resp.Edges, edgeJSON(e))
			}
		}
	}
	writeJSONHTTP(w, http.StatusOK, resp)
}

func (s *vizServer) handleNode(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimSpace(r.URL.Query().Get("id"))
	resp := vizNodeResp{Neighbors: []vizNode{}, Relations: []vizEdge{}}
	if id == "" {
		writeJSONHTTP(w, http.StatusBadRequest, vizNodeResp{Warnings: []string{"missing id"}})
		return
	}
	sem := s.semanticSource()
	if sem == nil {
		resp.Warnings = append(resp.Warnings, "no semantic graph")
		writeJSONHTTP(w, http.StatusOK, resp)
		return
	}
	node, neighbors, rels, err := s.nodeDetail(sem, id)
	if err != nil {
		resp.Warnings = append(resp.Warnings, err.Error())
		writeJSONHTTP(w, http.StatusOK, resp)
		return
	}
	if node == nil {
		writeJSONHTTP(w, http.StatusNotFound, vizNodeResp{Neighbors: []vizNode{}, Relations: []vizEdge{}, Warnings: []string{"symbol not found: " + id}})
		return
	}
	resp.Symbol = nodeJSON(*node)
	resp.Snippet = node.Blob
	for i := range neighbors {
		resp.Neighbors = append(resp.Neighbors, nodeJSON(neighbors[i]))
	}
	for i := range rels {
		resp.Relations = append(resp.Relations, edgeJSON(rels[i]))
	}
	writeJSONHTTP(w, http.StatusOK, resp)
}

func (s *vizServer) handleSearch(w http.ResponseWriter, r *http.Request) {
	q := strings.TrimSpace(r.URL.Query().Get("q"))
	limit := 25
	if v := r.URL.Query().Get("limit"); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 {
			limit = n
		}
	}
	resp := vizSearchResp{Hits: []vizHit{}}
	if q == "" {
		writeJSONHTTP(w, http.StatusOK, resp)
		return
	}
	// Symbol matches first so ⌘K / rail search can jump straight to a graph node.
	if sem := s.semanticSource(); sem != nil {
		if syms, _, _, err := semanticContextFacts(s.brainDir, sem, q, limit, 0); err == nil {
			for _, sy := range syms {
				resp.Hits = append(resp.Hits, vizHit{Source: "symbol", ID: sy.ID, Title: sy.Name, Text: sy.QualifiedName, Kind: sy.Kind, Path: sy.FilePath, Line: sy.StartLine})
			}
		}
	}
	// Memory hits (facts / history / docs), same code path as `entire brain search`.
	if u, err := retrieveUnified(s.brainDir, s.branch, q, limit, modeLexical); err == nil {
		for _, h := range u {
			resp.Hits = append(resp.Hits, vizHit{Source: h.Source, ID: h.ID, Title: h.Heading, Text: h.Text, Path: h.Path, Line: h.Line, Score: h.Score})
		}
	}
	writeJSONHTTP(w, http.StatusOK, resp)
}

// relationsForSymbols returns the relations among the given symbols, mirroring
// the SQLite-vs-snapshot branch semanticContextFacts uses (semantic.go).
func (s *vizServer) relationsForSymbols(sem *semanticSourceManifest, syms []semanticRecord, limit int) ([]semanticRecord, error) {
	if sem.StorePath != "" {
		storePath, err := validateSemanticDeclaredStore(s.brainDir, sem)
		if err != nil {
			return nil, err
		}
		return findSemanticRelationsForSymbolsInSQLite(storePath, syms, limit)
	}
	full, err := s.snapshotFullPath(sem)
	if err != nil {
		return nil, err
	}
	return findSemanticRelationsForSymbols(full, syms, limit)
}

// nodeDetail resolves one symbol by exact id plus its relations and neighbors,
// mirroring semanticContextFacts but seeded by id rather than a search query.
func (s *vizServer) nodeDetail(sem *semanticSourceManifest, id string) (*semanticRecord, []semanticRecord, []semanticRecord, error) {
	const limit = 80
	if sem.StorePath != "" {
		storePath, err := validateSemanticDeclaredStore(s.brainDir, sem)
		if err != nil {
			return nil, nil, nil, err
		}
		byID, err := loadSemanticSymbolsByIDsSQLite(storePath, []string{id})
		if err != nil {
			return nil, nil, nil, err
		}
		node, ok := byID[id]
		if !ok {
			return nil, nil, nil, nil
		}
		rels, err := findSemanticRelationsForSymbolsInSQLite(storePath, []semanticRecord{node}, limit*4)
		if err != nil {
			return nil, nil, nil, err
		}
		neighbors, err := s.resolveNeighbors(node, rels, func(ids []string) (map[string]semanticRecord, error) {
			return loadSemanticSymbolsByIDsSQLite(storePath, ids)
		}, limit)
		if err != nil {
			return nil, nil, nil, err
		}
		return &node, neighbors, rels, nil
	}
	full, err := s.snapshotFullPath(sem)
	if err != nil {
		return nil, nil, nil, err
	}
	byID, err := loadSemanticSymbolsByIDsSnapshot(full, []string{id})
	if err != nil {
		return nil, nil, nil, err
	}
	node, ok := byID[id]
	if !ok {
		return nil, nil, nil, nil
	}
	rels, err := findSemanticRelationsForSymbols(full, []semanticRecord{node}, limit*4)
	if err != nil {
		return nil, nil, nil, err
	}
	neighbors, err := s.resolveNeighbors(node, rels, func(ids []string) (map[string]semanticRecord, error) {
		return loadSemanticSymbolsByIDsSnapshot(full, ids)
	}, limit)
	if err != nil {
		return nil, nil, nil, err
	}
	return &node, neighbors, rels, nil
}

func (s *vizServer) resolveNeighbors(node semanticRecord, rels []semanticRecord, load func([]string) (map[string]semanticRecord, error), limit int) ([]semanticRecord, error) {
	ids := neighborCandidateIDs([]semanticRecord{node}, rels)
	if len(ids) == 0 {
		return nil, nil
	}
	byID, err := load(ids)
	if err != nil {
		return nil, err
	}
	return resolveContextNeighbors([]semanticRecord{node}, rels, byID, limit), nil
}

func (s *vizServer) snapshotFullPath(sem *semanticSourceManifest) (string, error) {
	snap, err := validateSemanticSnapshotPath(sem.SnapshotPath)
	if err != nil {
		return "", err
	}
	if err := rejectSymlinkPathComponents(s.brainDir, snap); err != nil {
		return "", err
	}
	return filepath.Join(s.brainDir, snap), nil
}

func writeJSONHTTP(w http.ResponseWriter, code int, v any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(v)
}

// openBrowser best-effort opens url in the default browser. Failure never fails
// the command — the URL is already printed for manual navigation.
func openBrowser(url string) {
	var c *exec.Cmd
	switch runtime.GOOS {
	case "darwin":
		c = exec.Command("open", url)
	case "windows":
		c = exec.Command("rundll32", "url.dll,FileProtocolHandler", url)
	default:
		c = exec.Command("xdg-open", url)
	}
	_ = c.Start()
}

