func (s *vizServer) handleFacts(w http.ResponseWriter, r *http.Request) {
	limit := vizQueryLimit(r, 500)
	facts, err := loadFacts(s.brainDir, s.branch)
	if err != nil {
		writeJSONHTTP(w, http.StatusOK, vizListResp{Items: []vizFact{}, Warnings: []string{"facts unavailable: " + err.Error()}})
