input.content:
// Minimal CDP driver: open the viz, drill into a feature, optionally set the
// node slider, settle, screenshot, and report diagnostics. Node 24 global WebSocket.
import fs from 'node:fs';

const [url, featureKey, sliderValue, settleMs, outPng] = process.argv.slice(2);

const newTab = await (await fetch(`http://127.0.0.1:9222/json/new?${encodeURIComponent(url)}`, { method: 'PUT' })).json();
const ws = new WebSocket(newTab.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
const send = (method, params = {}) => new Promise((res) => { const i = ++id; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
ws.addEventListener('message', (m) => {
  const msg = JSON.parse(m.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg.result); pending.delete(msg.id); }
});
await new Promise((res) => ws.addEventListener('open', res));

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const evalJS = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result?.value;

await send('Page.enable');
await send('Runtime.enable');
await send('Page.navigate', { url });
await sleep(2500);
if (featureKey) {
  await evalJS(`document.querySelector('.feature-node[data-key="${featureKey}"]').dispatchEvent(new MouseEvent('click',{bubbles:true}))`);
  await sleep(4000);
}
if (sliderValue && Number(sliderValue) > 0) {
  await evalJS(`(()=>{const s=document.getElementById('node-slider');s.value='${sliderValue}';s.dispatchEvent(new Event('input',{bubbles:true}));return s.value;})()`);
  await sleep(Number(settleMs) || 6000);
} else {
  await sleep(Number(settleMs) || 4000);
}
const diag = await evalJS(`JSON.stringify({crumb:document.getElementById('crumb-count')?.textContent, sliderVal:document.getElementById('node-slider-val')?.textContent, empty: !document.getElementById('empty')?.classList.contains('hidden')})`);
console.log('DIAG', diag);

const shot = (await send('Page.captureScreenshot', { format: 'png' })).data;
fs.writeFileSync(outPng, Buffer.from(shot, 'base64'));
console.log('SAVED', outPng);
await send('Target.closeTarget', { targetId: newTab.id }).catch(() => {});
ws.close();
process.exit(0);

