// Drive a session replay: open Sessions, spiral-click a well-connected session,
// hit "Replay on graph", let it run to a middle step, screenshot.
import fs from 'node:fs';
const [url, outPng] = process.argv.slice(2);
const newTab = await (await fetch(`http://127.0.0.1:9222/json/new?${encodeURIComponent(url)}`, { method: 'PUT' })).json();
const ws = new WebSocket(newTab.webSocketDebuggerUrl);
let id = 0; const pending = new Map();
const send = (m, p = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method: m, params: p })); });
ws.addEventListener('message', (m) => { const x = JSON.parse(m.data); if (x.id && pending.has(x.id)) { pending.get(x.id)(x.result); pending.delete(x.id); } });
await new Promise((r) => ws.addEventListener('open', r));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const ev = async (e) => (await send('Runtime.evaluate', { expression: e, returnByValue: true })).result?.value;
await send('Page.enable'); await send('Runtime.enable');
await send('Page.navigate', { url }); await sleep(2500);
// open sessions
await ev(`document.querySelector('.feature-node[data-key="sessions"]').dispatchEvent(new MouseEvent('click',{bubbles:true}))`);
await sleep(4500);
// spiral-click center to open a well-connected session inspector, then click Replay
const clicked = await ev(`(() => {
  const c=document.getElementById('graph'); c.setPointerCapture=()=>{}; c.releasePointerCapture=()=>{};
  const fire=(x,y)=>{c.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:1,clientX:x,clientY:y}));c.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:1,clientX:x,clientY:y}));};
  const app=document.getElementById('app'); const cx=980,cy=520; let hit=false;
  for(let r=0;r<=280&&!hit;r+=10){for(let a=0;a<360&&!hit;a+=18){const x=cx+r*Math.cos(a*Math.PI/180),y=cy+r*Math.sin(a*Math.PI/180);fire(x,y);if(app.classList.contains('inspector-open'))hit=true;}}
  const rb=document.querySelector('#insp-body .insp-replay'); if(rb){rb.click(); return 'replay-clicked';} return 'no-replay-btn:'+hit;
})()`);
console.log('CLICK', clicked);
await sleep(5000); // let it load + run a couple steps
const diag = await ev(`JSON.stringify({crumb:document.getElementById('crumb-title')?.textContent, step:document.getElementById('rp-step')?.textContent, file:document.getElementById('rp-file')?.textContent, empty:!document.getElementById('empty')?.classList.contains('hidden')})`);
console.log('DIAG', diag);
const shot = (await send('Page.captureScreenshot', { format: 'png' })).data;
fs.writeFileSync(outPng, Buffer.from(shot, 'base64'));
console.log('SAVED', outPng);
ws.close(); process.exit(0);

