// Open a replay, then scrub to the step with the MOST symbols (the wall-of-text
// stress case) and screenshot to confirm the label/ring cap holds.
import fs from 'node:fs';
const [url, outPng] = process.argv.slice(2);
const newTab = await (await fetch(`http://127.0.0.1:9222/json/new?${encodeURIComponent(url)}`, { method: 'PUT' })).json();
const ws = new WebSocket(newTab.webSocketDebuggerUrl);
let id = 0; const pending = new Map();
const send = (m, p = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method: m, params: p })); });
ws.addEventListener('message', (m) => { const x = JSON.parse(m.data); if (x.id && pending.has(x.id)) { pending.get(x.id)(x.result); pending.delete(x.id); } });
await new Promise((r) => ws.addEventListener('open', r));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const ev = async (e) => (await send('Runtime.evaluate', { expression: e, returnByValue: true })).result?.value;
await send('Page.enable'); await send('Runtime.enable');
await send('Page.navigate', { url }); await sleep(2500);
await ev(`document.querySelector('.feature-node[data-key="sessions"]').dispatchEvent(new MouseEvent('click',{bubbles:true}))`);
await sleep(4500);
// spiral-click to open a session inspector, prefer one with many touched files
const clicked = await ev(`(() => {
  const c=document.getElementById('graph'); c.setPointerCapture=()=>{}; c.releasePointerCapture=()=>{};
  const fire=(x,y)=>{c.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:1,clientX:x,clientY:y}));c.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:1,clientX:x,clientY:y}));};
  const app=document.getElementById('app'); const cx=1100,cy=520; let hit=false;
  for(let r=0;r<=320&&!hit;r+=10){for(let a=0;a<360&&!hit;a+=14){const x=cx+r*Math.cos(a*Math.PI/180),y=cy+r*Math.sin(a*Math.PI/180);fire(x,y);if(app.classList.contains('inspector-open'))hit=true;}}
  const rb=document.querySelector('#insp-body .insp-replay'); if(rb){rb.click(); return 'replay-clicked';} return 'no-replay-btn:'+hit;
})()`);
console.log('CLICK', clicked);
await sleep(4000); // load + initial settle
// Pause playback, then scrub to the step with the largest symbol count.
const info = await ev(`(() => {
  const bar=document.getElementById('replaybar'); if(!bar || bar.classList.contains('hidden')) return 'no-bar';
  const play=document.getElementById('rp-play'); // pause if playing
  return 'ok';
})()`);
console.log('BAR', info);
// Drive the scrubber across all steps, record the max-symbol step index.
const maxStep = await ev(`(async () => {
  const scrub=document.getElementById('rp-scrub'); const max=parseInt(scrub.max,10);
  let best=0, bestN=-1, log=[];
  for(let i=0;i<=max;i++){
    scrub.value=String(i); scrub.dispatchEvent(new Event('input',{bubbles:true}));
    await new Promise(r=>setTimeout(r,80));
    const t=document.getElementById('rp-file').textContent||''; const m=t.match(/(\\d+)\\s+symbols/);
    const n=m?parseInt(m[1],10):0; log.push(i+':'+n); if(n>bestN){bestN=n;best=i;}
  }
  scrub.value=String(best); scrub.dispatchEvent(new Event('input',{bubbles:true}));
  return JSON.stringify({best, bestN, total:max+1, log});
})()`);
console.log('MAXSTEP', maxStep);
await sleep(1500); // let the big step settle visually
const diag = await ev(`JSON.stringify({step:document.getElementById('rp-step')?.textContent, file:document.getElementById('rp-file')?.textContent})`);
console.log('DIAG', diag);
const shot = (await send('Page.captureScreenshot', { format: 'png' })).data;
fs.writeFileSync(outPng, Buffer.from(shot, 'base64'));
console.log('SAVED', outPng);
ws.close(); process.exit(0);

