859	func (s *vizServer) handleGraph(w http.ResponseWriter, r *http.Request) {
860		// `limit` is the number of symbols to RENDER (the node-count slider drives it).
861		// We load a wider pool, rank it by degree, and keep the top `limit` so the view
862		// is always the most-connected slice at any size the user picks.
863		view := vizGraphViewCap
864		if v := r.URL.Query().Get("limit"); v != "" {
865			if n, err := strconv.Atoi(v); err == nil && n > 0 {
866				view = n
867			}
868		}
869		if view > vizGraphMaxView {
870			view = vizGraphMaxView
871		}
872		resp := vizGraphResp{Nodes: []vizNode{}, Edges: []vizEdge{}}
873		sem := s.semanticSource()
874		if sem == nil {
875			resp.Warnings = append(resp.Warnings, "no semantic graph yet — run `entire brain refresh`")
876			writeJSONHTTP(w, http.StatusOK, resp)
877			return
878		}
879		pool := view * 3
880		if pool < 4000 {
881			pool = 4000
882		}
883		syms, err := loadSemanticSymbols(s.brainDir, sem, pool)
884		if err != nil {
885			resp.Warnings = append(resp.Warnings, "semantic symbols: "+err.Error())
886			writeJSONHTTP(w, http.StatusOK, resp)
887			return
888		}
889		if len(syms) == 0 {
890			resp.Warnings = append(resp.Warnings, "the semantic snapshot has no symbols yet — run `entire brain refresh`")
891			writeJSONHTTP(w, http.StatusOK, resp)
892			return
893		}
894		resp.Total = sem.Symbols
895	
896		// Rank the pool by degree so any `view` size keeps the most-connected symbols
897		// (loadSemanticSymbols returns storage order, so an unranked cap keeps leaves).
898		poolSet := make(map[string]bool, len(syms))
899		for i := range syms {
900			poolSet[syms[i].ID] = true
901		}
902		relLimit := pool * 4
903		var rels []semanticRecord
904		if r, rerr := s.relationsForSymbols(sem, syms, relLimit); rerr != nil {
905			resp.Warnings = append(resp.Warnings, "relations: "+rerr.Error())
906		} else {
907			rels = r
908		}
909		deg := make(map[string]int, len(syms))
910		for i := range rels {
911			e := rels[i]
912			if poolSet[e.FromID] && poolSet[e.ToID] {
913				deg[e.FromID]++
914				deg[e.ToID]++
915			}
916		}
917		kept := syms
918		if view > 0 && len(syms) > view {
919			ranked := make([]semanticRecord, len(syms))
920			copy(ranked, syms)
921			sort.SliceStable(ranked, func(i, j int) bool { return deg[ranked[i].ID] > deg[ranked[j].ID] })
922			kept = ranked[:view]
923		}
924		keptSet := make(map[string]bool, len(kept))
925		for i := range kept {
926			resp.Nodes = append(resp.Nodes, nodeJSON(kept[i]))
927			keptSet[kept[i].ID] = true
928		}
929		// Cap edges for render/sim budget, but choose them for COVERAGE first: a naive
930		// first-N cap piles all edges onto a few hubs and leaves most nodes edgeless, so
931		// they fly apart under repulsion and the whole graph fits to a dot. Pass 1 keeps
932		// edges that connect a still-unconnected node; pass 2 fills the remaining budget.
933		seen := make(map[string]bool)
934		covered := make(map[string]int)
935		addEdge := func(e semanticRecord) {
936			k := vizEdgeKey(e.FromID, e.ToID)
937			if seen[k] {
938				return
939			}
940			seen[k] = true
941			resp.Edges = append(resp.Edges, edgeJSON(e))
942			covered[e.FromID]++
943			covered[e.ToID]++
944		}
945		for i := range rels {
946			if len(resp.Edges) >= vizGraphMaxEdges {
947				break
948			}
949			e := rels[i]
950			if keptSet[e.FromID] && keptSet[e.ToID] && (covered[e.FromID] == 0 || covered[e.ToID] == 0) {
951				addEdge(e)
952			}
953		}
954		for i := range rels {
955			if len(resp.Edges) >= vizGraphMaxEdges {
956				break
957			}
958			e := rels[i]
959			if keptSet[e.FromID] && keptSet[e.ToID] {
960				addEdge(e)
961			}
962		}
963		resp.Truncated = sem.Symbols > len(kept)
964		writeJSONHTTP(w, http.StatusOK, resp)
965	}
