]

phase('Review')
const results = await pipeline(
  DIMENSIONS,
  (d) => agent(`${CTX}\n\n${d.prompt}`, { label: `review:${d.key}`, phase: 'Review', schema: FINDINGS_SCHEMA }),
  (review, d) => {
    const finds = (review && review.findings) || []
    if (!finds.length) return { key: d.key, findings: [], verdicts: [] }
    return parallel(finds.map((f) => () =>
      agent(`${CTX}\n\nA reviewer (lens: ${d.key}) filed this finding. Your job: adversarially VERIFY it. Read the cited code yourself and try to REFUTE it. Only mark real=true if it is a genuine defect in THIS PR that warrants a fix; if the code already handles it, or the trigger can't actually occur, mark real=false. Be concrete.\n\nFINDING:\n- title: ${f.title}\n- file: ${f.file}:${f.line}\n- severity: ${f.severity}\n- description: ${f.description}\n- trigger: ${f.trigger}\n- suggested fix: ${f.fix || '(none)'}\n`,
        { label: `verify:${d.key}`, phase: 'Verify', effort: 'high', schema: VERDICT_SCHEMA })
        .then((v) => ({ finding: f, verdict: v }))
    )).then((verdicts) => ({ key: d.key, findings: finds, verdicts: verdicts.filter(Boolean) }))
