func TestPostgresCopyFromStdinParses(t *testing.T) {
	src := "COPY users (id, name) FROM stdin;\n1\tAlice\n2\tBob\n\\.\n" +
		"CREATE TABLE after_tbl (id int);\n"
	entities, _, status := TreeSitterParser{}.ParseWithStatus("schema.sql", src)
