// repo_key (repoKeyFromRemote: "<provider>/<owner>/<repo>", lowercased): the
// provider slug prefix ("gh") plus the lowercased "owner/repo".
type brainSlugResolver struct {
	store *store.RepoStore
}

// Resolve returns the wire-contract slug for repoID, or "" when the repo has no
// slug on record (the publish handler maps "" -> 404, fail closed). A store error
// propagates so the handler fails closed too.
func (r brainSlugResolver) Resolve(ctx context.Context, repoID string) (string, error) {
	fullName, err := r.store.GitHubFullName(ctx, repoID)
	if err != nil {
		return "", fmt.Errorf("resolve repo slug for %s: %w", repoID, err)
	}
	if fullName == "" {
		return "", nil
	}
	return brainProviderPrefixGitHub + "/" + strings.ToLower(fullName), nil
}
