func (r brainSlugResolver) Resolve(ctx context.Context, repoID string) (string, error) {
	fullName, err := r.store.GitHubFullName(ctx, repoID)
	if err != nil {
		return "", fmt.Errorf("resolve repo slug for %s: %w", repoID, err)
	}
	if fullName == "" {
		return "", nil
	}
	return brainProviderPrefixGitHub + "/" + wireRepoPath(fullName), nil
}

// repoKeyUnsafeChars mirrors entire-brain's env.go: any run of chars outside
// [a-zA-Z0-9._-] collapses to a single '-'.
var repoKeyUnsafeChars = regexp.MustCompile(`[^a-zA-Z0-9._-]+`)

// wireRepoPath normalizes an "owner/repo" path to the exact form the client's
// repoKeyFromRemote produces, so the server-resolved slug is byte-identical to
// the manifest's repo_key. Each component is lowercased, has unsafe runs
// replaced with '-', and leading/trailing '-._' trimmed (safeRepoPathComponent);
// e.g. "acme/.github" -> "acme/github", not "acme/.github".
func wireRepoPath(fullName string) string {
	parts := strings.Split(fullName, "/")
	for i, p := range parts {
		parts[i] = strings.Trim(repoKeyUnsafeChars.ReplaceAllString(strings.ToLower(p), "-"), "-._")
	}
	return strings.Join(parts, "/")
}

