package server

import "testing"

// wireRepoPath must produce byte-identical output to entire-brain's
// repoKeyFromRemote (per-component: lowercase, unsafe->'-', trim "-._"), so the
// server-resolved slug matches the client's manifest repo_key exactly.
func TestWireRepoPath(t *testing.T) {
	cases := []struct{ in, want string }{
		{"org/repo", "org/repo"},
		{"Org/Repo", "org/repo"},                 // lowercased
		{"acme/.github", "acme/github"},          // leading dot trimmed (the audit case)
		{"acme/repo.", "acme/repo"},              // trailing dot trimmed
		{"acme/-lead-trail-", "acme/lead-trail"}, // leading/trailing '-' trimmed
		{"acme/_under_", "acme/under"},           // leading/trailing '_' trimmed
		{"acme/a b", "acme/a-b"},                 // unsafe run -> '-'
		{"acme/keep.dot-dash_under", "acme/keep.dot-dash_under"}, // interior punctuation preserved
	}
	for _, c := range cases {
		if got := wireRepoPath(c.in); got != c.want {
			t.Errorf("wireRepoPath(%q) = %q, want %q", c.in, got, c.want)
		}
	}
}

