131	func (e *EncryptingStore) Put(ctx context.Context, key BrainKey, data []byte) error {
132		// Validate before any side effect: a malformed key must not seal, write an
133		// object, or touch the DEK store.
134		if err := key.validate(); err != nil {
135			return err
136		}
137		repoID, sessionID := aadFor(key)
138		ciphertext, wrappedDEK, err := e.cipher.Seal(ctx, repoID, sessionID, data)
139		if err != nil {
140			return fmt.Errorf("brainstore: seal %s: %w", key.String(), err)
141		}
142		version := ciphertextVersion(ciphertext)
143		if err := e.inner.Put(ctx, versionedKey(key, version), ciphertext); err != nil {
144			return fmt.Errorf("brainstore: put ciphertext %s: %w", key.String(), err)
145		}
146		if err := e.deks.PutDEK(ctx, key, wrappedDEK, version); err != nil {
147			return fmt.Errorf("brainstore: put dek %s: %w", key.String(), err)
148		}
149		return nil
150	}
151	
152	// Get loads (wrapped DEK, version) from the DEKStore, fetches the ciphertext at
153	// versionedKey(key, version), and opens it. Because the version was committed with
154	// the wrapped DEK, the object fetched is always the exact one that DEK decrypts. A
155	// missing record (including after Shred) returns ErrNotFound; the encrypted inner
156	// bytes are never returned.
157	func (e *EncryptingStore) Get(ctx context.Context, key BrainKey) ([]byte, error) {
158		if err := key.validate(); err != nil {
159			return nil, err
160		}
161		wrappedDEK, version, err := e.deks.GetDEK(ctx, key)
162		if err != nil {
163			// ErrNotFound (no record, or shredded) propagates as a fail-closed miss;
164			// any other DEKStore error propagates too. Either way, no bytes returned.
165			return nil, err
166		}
167		ciphertext, err := e.inner.Get(ctx, versionedKey(key, version))
168		if err != nil {
169			return nil, err
