export const meta = {
  name: 'confirm-m1-5-client',
  description: 'Lean confirmation the publish client identity fix is clean',
  phases: [{ title: 'Review' }],
}
const WT = '/private/tmp/claude-501/-Users-suhaan-devenv/de272aad-c620-4d71-bbdd-27dd2d3dc8af/scratchpad/brain-publish-wt'
const CTX = `Final confirmation audit of the entire brain publish client after the github.com-only restriction, on a branch. Worktree: ${WT}, branch feat/p1-m1.5-publish-client, HEAD is the latest fix. Read: cd ${WT} && git show HEAD; internal/cli/publish.go (canonicalWireRepoKey, isGitHubDotComHost), publish_test.go. Reference: server /private/tmp/claude-501/-Users-suhaan-devenv/de272aad-c620-4d71-bbdd-27dd2d3dc8af/scratchpad/entire-api-work/internal/server/brain.go (wireRepoPath).
The fix: isGitHubDotComHost now returns normalizeRepoHost(host)==\"github.com\" (exact); non-github.com hosts (incl. GitHub Enterprise + look-alikes) fast-fail client-side, no HTTP. canonicalWireRepoKey = \"gh/\"+join(normalized components) matches the server's \"gh/\"+wireRepoPath(owner/repo) for every valid github.com repo. Size preflight was already verified correct in a prior pass (do not re-audit it).
Confirm the identity fix is NOW correct + complete: client wire repo_key == server slug for all valid github.com repos, no host false pos/neg, no-egress still intact, comments true. Report ONLY real remaining defects with file:line. No mutating commands.`
const FIND = { type:'object', additionalProperties:false, required:['findings'], properties:{ findings:{ type:'array', items:{
  type:'object', additionalProperties:false, required:['title','file','line','severity','description','trigger'],
  properties:{ title:{type:'string'}, file:{type:'string'}, line:{type:'string'}, severity:{type:'string', enum:['critical','high','medium','low','nit']}, description:{type:'string'}, trigger:{type:'string'}, fix:{type:'string'} } } } } }
const VERDICT = { type:'object', additionalProperties:false, required:['real','confidence','reasoning'], properties:{ real:{type:'boolean'}, confidence:{type:'string', enum:['high','medium','low']}, reasoning:{type:'string'}, fix_summary:{type:'string'} } }
phase('Review')
const rev = await agent(`${CTX}\n\nLENS: adversarial final sweep of the identity fix. Try to break it: (1) any github.com origin form (https, scp git@github.com:, trailing .git, ports, uppercase, www.github.com?) where isGitHubDotComHost wrongly rejects a real github.com repo (false negative) or accepts a non-github.com host (false positive) — check normalizeRepoHost handling of www./ports/case; (2) any valid github.com repo where the client wire key != server wireRepoPath output; (3) did the fix keep no-egress intact (fast-fail before any HTTP, gates before buildPublishBundle); (4) comments now true (no lingering GitHub-Enterprise-parity claim). Report only genuine defects.`, { label:'final-sweep', phase:'Review', effort:'high', schema:FIND })
const fs = (rev && rev.findings) || []
let confirmed=[]
if(fs.length){ const vs = await parallel(fs.map((f)=>()=>agent(`${CTX}\n\nAdversarially VERIFY. Read cited code + server wireRepoPath, try to REFUTE. real=true only if a genuine defect remains. A client!=server key for a real github.com repo, or a host false pos/neg = medium+; a doc nit = low.\n\nFINDING:\n${JSON.stringify(f,null,2)}`, { label:'verify', phase:'Review', effort:'high', schema:VERDICT }).then((v)=>({finding:f,verdict:v}))))
  confirmed = vs.filter(Boolean).filter(x=>x.verdict&&x.verdict.real).map(x=>({...x.finding,verdict:x.verdict})) }
log(`M1.5-client final confirm: ${confirmed.length} real`)
return { confirmed, clean: confirmed.length===0 }

export const meta = {
  name: 'audit-m1-6c-seams',
  description: 'Audit P1.M1.6c store-facing worker seams (work clone), verify each finding',
  phases: [{ title: 'Review' }, { title: 'Verify' }],
}
const CLONE = '/private/tmp/claude-501/-Users-suhaan-devenv/de272aad-c620-4d71-bbdd-27dd2d3dc8af/scratchpad/entire-api-work'
const CTX = `You are auditing P1.M1.6c (real store-facing worker seams) as a LOCAL commit in an isolated work clone. Clone: ${CLONE}, branch m1-integrated, commit HEAD (332688b). Read: cd ${CLONE} && git show HEAD; files internal/brainbuild/store_seams.go(+test), and for context internal/brainbuild/{worker.go,policy.go}, internal/brainstore/{encrypting_store.go,validating_store.go}, internal/httpapi/brain.go.
Design: StorePublisher.Publish layers a fresh ValidatingStore over the shared EncryptingStore and Puts each artifact (validate→encrypt→store, mirrors publishBrain); coordinates: snapshot/manifest/facts@head-commit, overlay@"base..head". StorePromoter.Promote reads the overlay (KindOverlay@base..head) and re-stores its content as KindSnapshot@head (no explicit baseline pointer exists — a commit's baseline IS the snapshot at its ref). StoreOverlayGC.GC calls EncryptingStore.GC(repoID, KindOverlay, minAge, now) — absence-of-reference sweep. NATS RefEventSource + runner BrainBuilder remain stubbed (infra). ADR-P1-C: default push→UpdateBaseline, feature→PublishOverlay, merge→PromoteOverlay, branch-delete→GCOverlays.
Report ONLY real defects in THIS commit. Concrete file:line + trigger. No mutating commands.`
const FIND = { type:'object', additionalProperties:false, required:['findings'], properties:{ findings:{ type:'array', items:{
  type:'object', additionalProperties:false, required:['title','file','line','severity','description','trigger'],
  properties:{ title:{type:'string'}, file:{type:'string'}, line:{type:'string'}, severity:{type:'string', enum:['critical','high','medium','low','nit']}, description:{type:'string'}, trigger:{type:'string'}, fix:{type:'string'} } } } } }
const VERDICT = { type:'object', additionalProperties:false, required:['real','confidence','reasoning'], properties:{ real:{type:'boolean'}, confidence:{type:'string', enum:['high','medium','low']}, reasoning:{type:'string'}, fix_summary:{type:'string'} } }
const LENSES = [
  { key:'semantics', prompt:`LENS: seam semantics vs ADR-P1-C + the store model. (1) Promoter: re-storing the overlay's decrypted content as KindSnapshot@head — is that a CORRECT promotion? An overlay artifact (a base..head DIFF/delta) is NOT necessarily a full baseline snapshot; storing a delta as if it were the baseline snapshot could make head's "baseline" a partial/delta blob that a consumer rehydrating from KindSnapshot@head would misread. Is an overlay's content actually a full snapshot, or a diff? If diff, promotion is semantically wrong (should rebuild the full baseline, not alias the delta). Check what PublishOverlay/the wire contract says an overlay CONTAINS. (2) GCOverlays(branch): the seam is handed a BRANCH but overlays are keyed base..head with no branch — so GC(repoID, KindOverlay) sweeps repo-wide ORPHANS, NOT the deleted branch's (still-live) overlays. On a branch delete, ADR-P1-C wants that branch's overlays retired, but EncryptingStore.GC only reaps already-unreferenced versions — a live overlay of the deleted branch is NEVER retired (its DEK pointer is still current). So GCOverlays is effectively a no-op for its stated purpose. Is that an un-flagged correctness gap or honestly deferred? (3) does Promote leave the overlay in place (now orphaned) — reaped? Construct the semantic failure.` },
  { key:'seamcorrect', prompt:`LENS: seam implementation correctness. (1) Publisher: fresh ValidatingStore per Publish — correct (no Expect bleed)? does it validate the manifest artifact (the schema gate) and fail-closed on a bad one with nothing stored? are all bundle kinds stored under the right BrainKey/ref? (2) repoID used directly as BrainKey.RepoKey — but the M1.5 endpoint resolves ULID→slug; does the worker's repoID arrive as the slug (matching the store's keying) or a ULID (mismatch → artifacts keyed differently than the publish endpoint would)? If the worker keys by a different identity than M1.5, the same repo's brain splits across two namespaces. (3) Promoter AAD: re-storing under KindSnapshot@head re-seals with a fresh DEK under the snapshot coordinate's AAD — correct, but does reading the overlay decrypt correctly (overlay AAD) first? (4) OverlayGC minAge/now: sane defaults, injected clock? (5) error handling: partial bundle publish failure, missing overlay, context propagation, nil enc. (6) any concurrency/idempotency issue. Construct the incorrect-store or identity-split trigger.` },
]
phase('Review')
const results = await pipeline(LENSES,
  (l)=>agent(`${CTX}\n\n${l.prompt}`, { label:`review:${l.key}`, phase:'Review', schema:FIND }),
  (rev,l)=>{ const fs=(rev&&rev.findings)||[]; if(!fs.length) return {key:l.key,verdicts:[]};
    return parallel(fs.map((f)=>()=>agent(`${CTX}\n\nAdversarially VERIFY (lens ${l.key}). Read cited code + the wire contract for what an overlay contains, try to REFUTE. real=true only if genuine defect in THIS commit. A promotion that stores a delta as a baseline, or an identity-split, = high; a clearly-documented deferral (GC per-branch) is not a defect if honestly flagged. Construct the concrete trigger.\n\nFINDING:\n${JSON.stringify(f,null,2)}`, { label:`verify:${l.key}`, phase:'Verify', effort:'high', schema:VERDICT }).then((v)=>({finding:f,verdict:v})))).then((vs)=>({key:l.key,verdicts:vs.filter(Boolean)})) })
const confirmed=[]
for(const r of results.filter(Boolean)) for(const vv of r.verdicts){ if(vv.verdict&&vv.verdict.real) confirmed.push({lens:r.key,...vv.finding,verdict:vv.verdict}) }
const rank={critical:0,high:1,medium:2,low:3,nit:4}
confirmed.sort((a,b)=>(rank[a.severity]??5)-(rank[b.severity]??5))
log(`M1.6c audit: ${confirmed.length} confirmed`)
return { confirmed, clean: confirmed.length===0 }

