9	
10	export function colorForKind(kind) {
11	  const k = (kind || '').toLowerCase();
12	  if (/func|method|constructor|closure/.test(k)) return cssVar('--k-function');
13	  if (/class|struct|interface|type|enum|trait|record|protocol/.test(k)) return cssVar('--k-type');
14	  if (/const|var|field|property|constant|literal|enum_member/.test(k)) return cssVar('--k-value');
15	  if (/module|package|file|namespace|entrypoint|entry|main/.test(k)) return cssVar('--k-entry');
16	  return cssVar('--k-other');
17	}
18	
19	// nodeColor prefers an explicit node.color (feature graphs set one per group);
20	// otherwise it falls back to the code-kind palette (the semantic graph).
21	export function nodeColor(n) { return (n && n.color) || colorForKind(n && n.kind); }
