35	  let replayLead = null; // top-degree active ids that get labels/rings (a file can touch 100s of symbols)
36	  let autoFit = false; // keep the view framed while the sim settles (any graph size)
37	  let dirty = true, W = 0, H = 0, dpr = 1;
38	
39	  // ---------- sizing ----------
40	  function resize() {
41	    dpr = Math.min(window.devicePixelRatio || 1, 2);
42	    const r = canvas.getBoundingClientRect();
43	    W = r.width; H = r.height;
44	    canvas.width = Math.round(W * dpr);
