54	  function setData(rawNodes, rawEdges) {
55	    byId = new Map();
56	    nodes = rawNodes.map((d) => {
57	      const angle = Math.random() * Math.PI * 2, rad = 60 + Math.random() * 380;
58	      const n = { ...d, x: Math.cos(angle) * rad, y: Math.sin(angle) * rad, vx: 0, vy: 0, degree: 0, fixed: false };
59	      byId.set(n.id, n);
60	      return n;
61	    });
62	    edges = [];
63	    for (const e of rawEdges) {
64	      const s = byId.get(e.from), t = byId.get(e.to);
65	      if (!s || !t || s === t) continue;
66	      s.degree++; t.degree++;
67	      edges.push({ ...e, source: s, target: t });
68	    }
