70	    // Fewer settling ticks for very large graphs (each tick rebuilds the quadtree);
71	    // the coverage-capped edge set keeps the layout well-spread regardless.
72	    const iters = nodes.length > 6000 ? 220 : 300;
73	    alphaDecay = 1 - Math.pow(0.001, 1 / iters);
