77	  }
78	
79	  function mergeData(rawNodes, rawEdges) {
80	    let added = 0;
81	    const anchor = selected || nodes[0] || { x: 0, y: 0 };
82	    for (const d of rawNodes) {
83	      if (byId.has(d.id)) continue;
84	      const a = Math.random() * Math.PI * 2, rad = 30 + Math.random() * 40;
85	      const n = { ...d, x: anchor.x + Math.cos(a) * rad, y: anchor.y + Math.sin(a) * rad, vx: 0, vy: 0, degree: 0, fixed: false };
86	      byId.set(n.id, n); nodes.push(n); added++;
87	    }
88	    const seen = new Set(edges.map((e) => e.from + ' ' + e.to + ' ' + e.type));
89	    for (const e of rawEdges) {
90	      const key = e.from + ' ' + e.to + ' ' + e.type;
91	      if (seen.has(key)) continue;
92	      const s = byId.get(e.from), t = byId.get(e.to);
93	      if (!s || !t || s === t) continue;
94	      s.degree++; t.degree++; edges.push({ ...e, source: s, target: t }); seen.add(key);
95	    }
96	    reheat(0.5);
