100	  // ---------- simulation ----------
101	  function reheat(a = 0.6) { alpha = Math.max(alpha, a); dirty = true; if (REDUCED) settle(); }
102	  function settle() { for (let i = 0; i < 400 && alpha > 0.001; i++) tick(); alpha = 0; dirty = true; }
103	
104	  function buildQuadtree() {
105	    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
106	    for (const n of nodes) { if (n.x < x0) x0 = n.x; if (n.y < y0) y0 = n.y; if (n.x > x1) x1 = n.x; if (n.y > y1) y1 = n.y; }
107	    if (!isFinite(x0)) return null;
108	    const size = Math.max(x1 - x0, y1 - y0, 1) + 1;
109	    const root = { cx: (x0 + x1) / 2, cy: (y0 + y1) / 2, half: size / 2, mass: 0, mx: 0, my: 0, node: null, kids: null };
110	    const insert = (q, n, depth) => {
111	      q.mass++; q.mx += n.x; q.my += n.y;
112	      if (!q.kids && !q.node) { q.node = n; return; }
113	      if (!q.kids) {
114	        q.kids = [null, null, null, null];
115	        const old = q.node; q.node = null;
116	        if (old) place(q, old, depth);
117	      }
118	      place(q, n, depth);
119	    };
120	    const place = (q, n, depth) => {
121	      const i = (n.x >= q.cx ? 1 : 0) + (n.y >= q.cy ? 2 : 0);
122	      let k = q.kids[i];
123	      if (!k) {
124	        const h = q.half / 2;
125	        k = q.kids[i] = { cx: q.cx + (i & 1 ? h : -h), cy: q.cy + (i & 2 ? h : -h), half: h, mass: 0, mx: 0, my: 0, node: null, kids: null };
126	      }
127	      if (depth > 24) { k.mass++; k.mx += n.x; k.my += n.y; k.node = k.node || n; return; }
128	      insert(k, n, depth + 1);
129	    };
130	    for (const n of nodes) insert(root, n, 0);
131	    return root;
132	  }
133	
134	  function applyCharge() {
135	    const root = buildQuadtree();
136	    if (!root) return;
137	    // Repulsion must grow with the node count, or dense graphs (many edges pulling
138	    // inward) collapse along one axis into a spindle instead of spreading in 2D.
139	    const chargeScale = Math.min(1 + nodes.length / 500, 4.5);
140	    const theta2 = 0.81;
141	    const strength = -34 * chargeScale * alpha;
142	    for (const n of nodes) {
143	      const stack = [root];
144	      while (stack.length) {
145	        const q = stack.pop();
146	        if (!q || q.mass === 0) continue;
147	        const cxm = q.mx / q.mass, cym = q.my / q.mass;
148	        let dx = cxm - n.x, dy = cym - n.y;
149	        let d2 = dx * dx + dy * dy;
150	        const w = q.half * 2;
151	        if (q.node === n && !q.kids) continue;
152	        if (!q.kids || (w * w) / (d2 || 1e-6) < theta2) {
153	          if (d2 < 1) { d2 = 1; dx += (Math.random() - 0.5) * 0.5; dy += (Math.random() - 0.5) * 0.5; }
154	          const f = (strength * q.mass) / d2;
155	          n.vx += dx * f; n.vy += dy * f;
156	        } else {
157	          for (const k of q.kids) if (k) stack.push(k);
158	        }
159	      }
160	    }
161	  }
