163	  function applyLinks() {
164	    // Weaken each link by the lesser endpoint degree (d3's bias): without this,
165	    // a hub with hundreds of edges gets pulled inward hundreds of times and
166	    // collapses dense graphs into a cigar. Leaves (degree 1) stay firmly attached.
167	    const dist = 46, stiff = 0.32 * alpha;
168	    for (const e of edges) {
169	      const s = e.source, t = e.target;
170	      let dx = t.x - s.x, dy = t.y - s.y;
171	      let d = Math.sqrt(dx * dx + dy * dy) || 1e-6;
172	      // Relax leaves (÷degree) but FLOOR the denominator so hub<->hub links never
173	      // go to ~zero — otherwise mega-hubs decouple, fly apart on repulsion, and
174	      // string the graph into a diagonal tail. Floor of 10 keeps hubs bound.
175	      const k = stiff / Math.min(Math.min(s.degree || 1, t.degree || 1), 10);
176	      const f = ((d - dist) / d) * k;
177	      dx *= f; dy *= f;
178	      if (!t.fixed) { t.vx -= dx; t.vy -= dy; }
179	      if (!s.fixed) { s.vx += dx; s.vy += dy; }
180	    }
181	  }
