185	    // repulsion and helps the collapse, so keep it light for large graphs.
186	    const g = (nodes.length > 700 ? 0.022 : 0.045) * alpha;
187	    for (const n of nodes) { n.vx -= n.x * g; n.vy -= n.y * g; }
188	  }
