195	    for (const n of nodes) {
196	      if (n.fixed) { n.vx = 0; n.vy = 0; continue; }
197	      n.vx *= velocityDecay; n.vy *= velocityDecay;
198	      if (n.vx > maxV) n.vx = maxV; else if (n.vx < -maxV) n.vx = -maxV;
199	      if (n.vy > maxV) n.vy = maxV; else if (n.vy < -maxV) n.vy = -maxV;
200	      n.x += n.vx; n.y += n.vy;
201	    }
202	    dirty = true;
203	  }
