205	  // ---------- camera ----------
206	  const toScreen = (x, y) => [(x * cam.scale) + cam.tx, (y * cam.scale) + cam.ty];
207	  const toWorld = (sx, sy) => [(sx - cam.tx) / cam.scale, (sy - cam.ty) / cam.scale];
208	
209	  function zoomToFit(animate = true) {
210	    if (!nodes.length) return;
211	    let x0, y0, x1, y1;
212	    if (nodes.length >= 12) {
213	      // Robust bounds: frame the 2nd–98th percentile so a handful of weakly-linked
214	      // drifters can't blow up the bounding box and squash the core into a sliver.
215	      const xs = nodes.map((n) => n.x).sort((a, b) => a - b);
216	      const ys = nodes.map((n) => n.y).sort((a, b) => a - b);
217	      const lo = Math.floor(nodes.length * 0.02), hi = Math.min(nodes.length - 1, Math.ceil(nodes.length * 0.98));
218	      x0 = xs[lo]; x1 = xs[hi]; y0 = ys[lo]; y1 = ys[hi];
219	    } else {
220	      x0 = Infinity; y0 = Infinity; x1 = -Infinity; y1 = -Infinity;
221	      for (const n of nodes) { x0 = Math.min(x0, n.x); y0 = Math.min(y0, n.y); x1 = Math.max(x1, n.x); y1 = Math.max(y1, n.y); }
222	    }
223	    const pad = 80, gw = Math.max(x1 - x0, 1), gh = Math.max(y1 - y0, 1);
224	    const s = Math.min((W - pad) / gw, (H - pad) / gh, 2.2);
225	    const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
226	    const target = { scale: s, tx: W / 2 - cx * s, ty: H / 2 - cy * s };
