235	      const e = 1 - Math.pow(1 - p, 3);
236	      cam.scale = from.scale + (target.scale - from.scale) * e;
237	      cam.tx = from.tx + (target.tx - from.tx) * e;
238	      cam.ty = from.ty + (target.ty - from.ty) * e;
239	      dirty = true;
240	      if (p >= 1) camTween = null;
241	    };
242	  }
