260	    replayVisited = new Set(visitedIds || []);
261	    // A single step is one file, which can map to hundreds of symbols. Only the
262	    // few highest-degree ones get a label + ring + glow; the rest just brighten,
263	    // so the step reads as "this cluster lit up" instead of a wall of text.
264	    const active = (activeIds || []).map((id) => byId.get(id)).filter(Boolean);
265	    active.sort((a, b) => (b.degree || 0) - (a.degree || 0));
266	    replayLead = new Set(active.slice(0, 5).map((n) => n.id));
267	    dirty = true;
268	  }
269	  function clearReplay() { replayActive = null; replayVisited = null; replayLead = null; dirty = true; }
270	  function panToIds(ids, scale) {
271	    autoFit = false;
272	    const pts = (ids || []).map((id) => byId.get(id)).filter(Boolean);
273	    if (!pts.length) return;
274	    let cx = 0, cy = 0;
275	    for (const n of pts) { cx += n.x; cy += n.y; }
276	    cx /= pts.length; cy /= pts.length;
277	    const sc = scale || Math.max(cam.scale, 1.0);
278	    const target = { scale: sc, tx: W / 2 - cx * sc, ty: H / 2 - cy * sc };
279	    REDUCED ? (cam = target, dirty = true) : tweenCam(target);
280	  }
281	
282	  // ---------- rendering ----------
283	  function draw() {
284	    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
285	    ctx.clearRect(0, 0, W, H);
286	    const showLabels = cam.scale > 1.15;
287	    const replaying = replayActive !== null;
288	    const pulse = replaying ? (0.5 + 0.5 * Math.sin(performance.now() / 240)) : 0;
289	    const hi = hover || selected;
290	    const incident = hi ? new Set() : null;
291	    if (hi) for (const e of edges) { if (e.source === hi || e.target === hi) { incident.add(e); } }
292	
293	    // edges
294	    ctx.lineWidth = 1;
295	    for (const e of edges) {
296	      const [x1, y1] = toScreen(e.source.x, e.source.y);
297	      const [x2, y2] = toScreen(e.target.x, e.target.y);
298	      let a = 0.16;
299	      let col = '185,185,185';
300	      if (replaying) {
301	        const both = replayVisited.has(e.source.id) && replayVisited.has(e.target.id);
302	        a = both ? 0.55 : 0.03;
303	        if (both) col = hexToRgb(nodeColor(e.source));
304	      } else if (hi) {
305	        if (incident.has(e)) { a = 0.85; col = hexToRgb(nodeColor(e.source)); }
306	        else a = 0.04;
307	      } else if (focusSet && (focusSet.has(e.source.id) && focusSet.has(e.target.id))) {
308	        a = 0.5;
309	      }
310	      ctx.strokeStyle = `rgba(${col},${a})`;
311	      ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
312	      if (incident && incident.has(e)) drawArrow(x1, y1, x2, y2, radius(e.target) * cam.scale);
313	    }
314	
315	    // nodes
316	    for (const n of nodes) {
317	      const [x, y] = toScreen(n.x, n.y);
318	      if (x < -50 || y < -50 || x > W + 50 || y > H + 50) continue;
319	      const r = Math.max(radius(n) * cam.scale, 1.5);
320	      const col = nodeColor(n);
321	      let alpha = 1, isActive = false, isLead = false;
322	      if (replaying) {
323	        isActive = replayActive.has(n.id);
324	        isLead = isActive && replayLead && replayLead.has(n.id);
325	        alpha = isActive ? 1 : (replayVisited.has(n.id) ? 0.42 : 0.1);
326	      } else {
327	        const dim = hi && n !== hi && !(incident && [...incident].some((e) => e.source === n || e.target === n));
328	        const focusDim = !hi && focusSet && !focusSet.has(n.id);
329	        // Keep dimmed context clearly visible (0.5, not near-invisible) so moving
330	        // the cursor over a sparse graph doesn't make everything flicker away.
331	        alpha = (dim || focusDim) ? 0.5 : 1;
332	      }
333	      if (isLead) { // expanding pulse ring on the few lead symbols only (not all 100s)
334	        ctx.globalAlpha = 0.55 * (1 - pulse * 0.7);
335	        ctx.beginPath(); ctx.arc(x, y, r + 4 + pulse * 11, 0, Math.PI * 2);
336	        ctx.strokeStyle = col; ctx.lineWidth = 2; ctx.stroke();
337	      }
338	      ctx.globalAlpha = alpha;
339	      if (n === hi || n === selected || isLead) { ctx.shadowColor = col; ctx.shadowBlur = isLead ? 18 : 16; }
340	      ctx.beginPath(); ctx.arc(x, y, isActive ? r + 1.5 : r, 0, Math.PI * 2);
341	      ctx.fillStyle = col; ctx.fill();
342	      ctx.shadowBlur = 0;
343	      if (n === selected) { ctx.lineWidth = 2; ctx.strokeStyle = '#fff'; ctx.stroke(); }
344	      else if (n.fixed) { ctx.lineWidth = 1.5; ctx.strokeStyle = 'rgba(255,255,255,0.5)'; ctx.stroke(); }
345	      // During replay label ONLY the few lead symbols of the active step — a file
346	      // can touch hundreds of symbols and labeling all of them is an unreadable wall.
347	      const wantLabel = n === hi || n === selected || isLead || (!replaying && showLabels && n.degree >= 5);
348	      if (wantLabel) {
349	        ctx.globalAlpha = alpha < 0.5 ? 0.25 : 0.92;
350	        ctx.fillStyle = '#f3f3f3';
351	        ctx.font = '11px ui-monospace, Menlo, monospace';
352	        ctx.textAlign = 'center';
353	        const label = n.name || n.id;
354	        ctx.fillText(label.length > 28 ? label.slice(0, 27) + '...' : label, x, y - (isActive ? r + 2 : r) - 5);
355	      }
356	      ctx.globalAlpha = 1;
357	    }
358	  }
359	
360	  function drawArrow(x1, y1, x2, y2, back) {
361	    const ang = Math.atan2(y2 - y1, x2 - x1);
362	    const ex = x2 - Math.cos(ang) * (back + 3), ey = y2 - Math.sin(ang) * (back + 3);
363	    const s = 6;
364	    ctx.fillStyle = 'rgba(242,83,51,0.9)';
365	    ctx.beginPath();
366	    ctx.moveTo(ex, ey);
367	    ctx.lineTo(ex - Math.cos(ang - 0.4) * s, ey - Math.sin(ang - 0.4) * s);
368	    ctx.lineTo(ex - Math.cos(ang + 0.4) * s, ey - Math.sin(ang + 0.4) * s);
369	    ctx.closePath(); ctx.fill();
370	  }
371	
372	  function hexToRgb(hex) {
373	    hex = (hex || '').replace('#', '');
374	    if (hex.length === 3) hex = hex.split('').map((c) => c + c).join('');
375	    const n = parseInt(hex || 'b9b9b9', 16);
376	    return `${(n >> 16) & 255},${(n >> 8) & 255},${n & 255}`;
377	  }
378	
379	  // ---------- loop ----------
380	  function frame() {
381	    if (camTween) camTween();
382	    if (alpha >= 0.001) tick();
383	    // Keep the graph framed as it expands during settling; stop once it's at rest.
384	    if (autoFit && !camTween) { zoomToFit(false); if (alpha < 0.02) autoFit = false; }
385	    if (replayActive && !REDUCED) dirty = true; // keep the pulse animating during replay
386	    if (dirty) { draw(); dirty = false; }
387	    requestAnimationFrame(frame);
388	  }
389	  requestAnimationFrame(frame);
390	
391	  // ---------- picking + interaction ----------
392	  function pick(sx, sy) {
393	    const [wx, wy] = toWorld(sx, sy);
394	    let best = null, bestD = Infinity;
395	    for (const n of nodes) {
396	      const dx = n.x - wx, dy = n.y - wy, d = dx * dx + dy * dy;
397	      const rr = Math.pow((radius(n) + 7) / cam.scale, 2);
398	      if (d < rr && d < bestD) { bestD = d; best = n; }
399	    }
400	    return best;
401	  }
402	
403	  let drag = null, panning = null, moved = false;
404	  canvas.addEventListener('pointerdown', (ev) => {
405	    canvas.setPointerCapture(ev.pointerId);
406	    autoFit = false;
407	    moved = false;
408	    const rect = canvas.getBoundingClientRect();
409	    const sx = ev.clientX - rect.left, sy = ev.clientY - rect.top;
410	    const n = pick(sx, sy);
411	    if (n) { drag = { n, sx, sy }; n.fixed = true; }
412	    else { panning = { sx, sy, tx: cam.tx, ty: cam.ty }; }
413	  });
414	  canvas.addEventListener('pointermove', (ev) => {
415	    const rect = canvas.getBoundingClientRect();
416	    const sx = ev.clientX - rect.left, sy = ev.clientY - rect.top;
417	    if (drag) {
418	      moved = true;
419	      const [wx, wy] = toWorld(sx, sy);
420	      drag.n.x = wx; drag.n.y = wy; drag.n.vx = 0; drag.n.vy = 0;
421	      reheat(0.3); dirty = true; return;
422	    }
423	    if (panning) { moved = true; cam.tx = panning.tx + (sx - panning.sx); cam.ty = panning.ty + (sy - panning.sy); dirty = true; return; }
424	    const n = pick(sx, sy);
425	    if (n !== hover) { hover = n; dirty = true; handlers.onHover && handlers.onHover(n, ev.clientX, ev.clientY); }
426	    else if (n) handlers.onHover && handlers.onHover(n, ev.clientX, ev.clientY);
427	    canvas.style.cursor = n ? 'pointer' : 'grab';
428	  });
429	  canvas.addEventListener('pointerup', (ev) => {
430	    const rect = canvas.getBoundingClientRect();
431	    const sx = ev.clientX - rect.left, sy = ev.clientY - rect.top;
432	    if (drag) { if (!moved) drag.n.fixed = false; const n = drag.n; drag = null; if (!moved) { handlers.onClick && handlers.onClick(n); } return; }
433	    if (panning) { const wasClick = !moved; panning = null; if (wasClick) { handlers.onBackground && handlers.onBackground(); } }
434	  });
435	  canvas.addEventListener('dblclick', (ev) => {
436	    const rect = canvas.getBoundingClientRect();
437	    const n = pick(ev.clientX - rect.left, ev.clientY - rect.top);
438	    if (n) handlers.onExpand && handlers.onExpand(n);
439	  });
440	  canvas.addEventListener('wheel', (ev) => {
441	    ev.preventDefault();
442	    autoFit = false;
443	    const rect = canvas.getBoundingClientRect();
444	    const sx = ev.clientX - rect.left, sy = ev.clientY - rect.top;
445	    const [wx, wy] = toWorld(sx, sy);
446	    const factor = Math.exp(-ev.deltaY * 0.0015);
447	    cam.scale = Math.max(0.05, Math.min(cam.scale * factor, 8));
448	    cam.tx = sx - wx * cam.scale; cam.ty = sy - wy * cam.scale;
449	    dirty = true;
450	  }, { passive: false });
451	
452	  return {
453	    setData, mergeData, focus, clearFocus, zoomToFit,
454	    setReplay, clearReplay, panToIds,
455	    getNode: (id) => byId.get(id),
456	    reheat,
457	    get count() { return nodes.length; },
458	  };
459	}
