1	/* entire brain viz — dark theme tokens mirror entire.io/frontend/src/index.css .dark */
2	:root {
3	  --surface-sunken: #111111;
4	  --surface-base: #161616;
5	  --surface-raised: #1c1c1c;
6	  --surface-floating: #222222;
7	  --surface-hover: rgb(255 255 255 / 0.06);
8	  --surface-active: rgb(255 255 255 / 0.12);
9	  --surface-selected: rgb(255 255 255 / 0.08);
10	
11	  --text-default: #f3f3f3;
12	  --text-muted: #b9b9b9;
13	  --text-disabled: #707070;
14	
15	  --border-default: rgb(250 250 250 / 0.10);
16	  --border-subtle: rgb(250 250 250 / 0.08);
17	
18	  --accent: #f25333;
19	  --accent-soft: rgb(242 83 51 / 0.16);
20	  --focus: var(--accent);
21	
22	  --k-function: #22d3ee; /* function / method */
23	  --k-type: #818cf8;     /* type / class / interface / struct */
24	  --k-value: #fbbf24;    /* const / var / literal */
25	  --k-entry: #f25333;    /* entry-point / boundary */
26	  --k-other: #b9b9b9;
27	
28	  --font-ui: "Entire Headline NEW", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
29	  --font-mono: "Entire Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;
30	
31	  --r-sm: 6px;
32	  --r-md: 10px;
33	  --r-lg: 14px;
34	
35	  --shadow-float: 0 2px 4px #00000033, 0 4px 12px -1px #00000040, 0 0 0 1px rgb(255 255 255 / 0.14);
36	  --ease: cubic-bezier(.2, .7, .2, 1);
37	}
38	
39	* { box-sizing: border-box; }
40	html, body { height: 100%; margin: 0; }
41	body {
42	  background: var(--surface-sunken);
43	  color: var(--text-default);
44	  font-family: var(--font-ui);
45	  font-size: 14px;
46	  line-height: 1.5;
47	  overflow: hidden;
48	  -webkit-font-smoothing: antialiased;
49	}
50	:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; border-radius: 4px; }
51	button { font: inherit; color: inherit; }
52	::-webkit-scrollbar { width: 10px; height: 10px; }
53	::-webkit-scrollbar-thumb { background: rgb(255 255 255 / 0.12); border-radius: 999px; border: 2px solid transparent; background-clip: content-box; }
54	::-webkit-scrollbar-thumb:hover { background: rgb(255 255 255 / 0.2); background-clip: content-box; }
