56	/* ---- app grid ---- */
57	/* The inspector is always the 3rd grid column; collapse it to 0 (and clip its
58	   content via #inspector overflow:hidden) when closed, so it never spills into
59	   an implicit bottom row. */
60	#app { display: grid; grid-template-columns: 280px 1fr 0px; height: 100%; transition: grid-template-columns 180ms var(--ease); }
61	#app.inspector-open { grid-template-columns: 280px 1fr 360px; }
62	
63	#main { position: relative; min-width: 0; display: flex; flex-direction: column; overflow: hidden; }
64	.view { flex: 1; min-height: 0; position: relative; overflow: auto; }
65	.view.hidden { display: none; }
