67	.topbar .back { background: var(--surface-raised); border: 1px solid var(--border-default); color: var(--text-default); border-radius: var(--r-sm); padding: 5px 11px; cursor: pointer; font-size: 12.5px; }
68	.topbar .back:hover { background: var(--surface-active); }
