package brainbuild

import (
	"context"
	"errors"
	"fmt"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/entirehq/entire-api/internal/brainstore"
)

// PgOverlayBranchIndex is the durable OverlayBranchIndex backing brainbuild in
// production: one row per (repo_key, branch, overlay_ref) in the
// brain_overlay_branches table (migration 037). It mirrors the store package's
// pgxpool patterns (unqualified names via search_path, pgx.ErrNoRows mapped).
type PgOverlayBranchIndex struct {
	pool *pgxpool.Pool
}

// NewPgOverlayBranchIndex builds the durable index over the given pool. The pool
// must resolve unqualified names in the `repo` schema and hold the repo_rw grants
// on brain_overlay_branches AND brain_deks (RetireRef shreds a DEK row in the same
// tx) — the same serve pool the DEK store uses satisfies both.
func NewPgOverlayBranchIndex(pool *pgxpool.Pool) *PgOverlayBranchIndex {
	return &PgOverlayBranchIndex{pool: pool}
}

// Record inserts the (repo_key, branch, overlay_ref) row, idempotently. ON
// CONFLICT DO NOTHING makes a re-publish of the same overlay a no-op.
func (s *PgOverlayBranchIndex) Record(ctx context.Context, repoKey, branch, overlayRef string) error {
	if repoKey == "" || branch == "" || overlayRef == "" {
		return errors.New("brainbuild: empty repoKey/branch/overlayRef in Record")
	}
	_, err := s.pool.Exec(ctx, `
		INSERT INTO brain_overlay_branches (repo_key, branch, overlay_ref)
		VALUES ($1, $2, $3)
		ON CONFLICT (repo_key, branch, overlay_ref) DO NOTHING`,
		repoKey, branch, overlayRef)
	if err != nil {
		return fmt.Errorf("brainbuild: record overlay branch %s/%s/%s: %w", repoKey, branch, overlayRef, err)
	}
	return nil
}

// Overlays returns the overlay refs recorded for branch — its retirement worklist.
func (s *PgOverlayBranchIndex) Overlays(ctx context.Context, repoKey, branch string) ([]string, error) {
	rows, err := s.pool.Query(ctx,
		`SELECT overlay_ref FROM brain_overlay_branches WHERE repo_key = $1 AND branch = $2`,
		repoKey, branch)
	if err != nil {
		return nil, fmt.Errorf("brainbuild: list overlays %s/%s: %w", repoKey, branch, err)
	}
	defer rows.Close()
	var out []string
	for rows.Next() {
		var ref string
		if err := rows.Scan(&ref); err != nil {
			return nil, fmt.Errorf("brainbuild: scan overlay %s/%s: %w", repoKey, branch, err)
		}
		out = append(out, ref)
	}
	return out, rows.Err()
}

// RetireRef is the load-bearing atomic op. In ONE transaction it:
//
//	(1) DELETEs this branch's (repo_key, branch, overlay_ref) index row;
//	(2) counts the SIBLING rows on OTHER branches for the same (repo_key,
//	    overlay_ref) — the cross-branch refcount, taken AFTER (1) so it excludes
//	    this row;
//	(3) if that count is 0, DELETEs the overlay's brain_deks row RETURNING its
//	    ciphertext_version (the crypto-shred).
//
// Because the index-row delete and the DEK delete COMMIT TOGETHER, a failure at
// (3) rolls BOTH back — the row is never de-indexed without its DEK being shred,
// so a retry can complete the shred. And because the refcount at (2) gates the
// shred, a coordinate two branches share (same base..head) is shredded only by the
// LAST branch to retire it — never over-reaped. A remaining count > 0, or a DEK
// row already gone (a prior shred), commits the de-index alone and reports
// shredded=false.
func (s *PgOverlayBranchIndex) RetireRef(ctx context.Context, repoKey, branch, overlayRef string) (string, bool, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return "", false, fmt.Errorf("brainbuild: retire begin %s/%s/%s: %w", repoKey, branch, overlayRef, err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // no-op after commit; rolls back both deletes on any error

	// (1) de-index this branch's row.
	if _, err := tx.Exec(ctx,
		`DELETE FROM brain_overlay_branches WHERE repo_key = $1 AND branch = $2 AND overlay_ref = $3`,
		repoKey, branch, overlayRef); err != nil {
		return "", false, fmt.Errorf("brainbuild: retire delete index %s/%s/%s: %w", repoKey, branch, overlayRef, err)
	}

	// (2) cross-branch refcount (excludes the row just deleted).
	var remaining int
	if err := tx.QueryRow(ctx,
		`SELECT count(*) FROM brain_overlay_branches WHERE repo_key = $1 AND overlay_ref = $2`,
		repoKey, overlayRef).Scan(&remaining); err != nil {
		return "", false, fmt.Errorf("brainbuild: retire refcount %s/%s: %w", repoKey, overlayRef, err)
	}
	if remaining > 0 {
		// A sibling branch still references the coordinate: de-index only, no shred.
		if err := tx.Commit(ctx); err != nil {
			return "", false, fmt.Errorf("brainbuild: retire commit (deindex) %s/%s/%s: %w", repoKey, branch, overlayRef, err)
		}
		return "", false, nil
	}

	// (3) last reference — crypto-shred the DEK in the SAME tx (kind = overlay).
	var version string
	err = tx.QueryRow(ctx,
		`DELETE FROM brain_deks WHERE repo_key = $1 AND kind = $2 AND ref = $3 RETURNING ciphertext_version`,
		repoKey, brainstore.KindOverlay, overlayRef).Scan(&version)
	if errors.Is(err, pgx.ErrNoRows) {
		// DEK already gone (a prior shred). Commit the de-index alone.
		if err := tx.Commit(ctx); err != nil {
			return "", false, fmt.Errorf("brainbuild: retire commit (dek absent) %s/%s/%s: %w", repoKey, branch, overlayRef, err)
		}
		return "", false, nil
	}
	if err != nil {
		// Shred failed: rollback (deferred) undoes the de-index too — no
		// de-index-without-shred; the row survives for retry.
		return "", false, fmt.Errorf("brainbuild: retire shred dek %s/%s: %w", repoKey, overlayRef, err)
	}
	if err := tx.Commit(ctx); err != nil {
		return "", false, fmt.Errorf("brainbuild: retire commit (shred) %s/%s/%s: %w", repoKey, branch, overlayRef, err)
	}
