package brainbuild

import (
	"context"
	"errors"
	"sync"

	"github.com/entirehq/entire-api/internal/brainstore"
)

// OverlayBranchIndex records which overlay coordinates a feature branch published,
// so a branch delete can retire exactly those overlays. It is the refcount source
// of truth for shredding: because two branches can independently publish the SAME
// base..head overlay coordinate, an overlay is crypto-shredded only when the LAST
// branch referencing it retires.
//
// The keys are the repo SLUG (repoKey), the branch name, and the overlay's
// LOGICAL ref ("base..head" — see OverlayRef). It is deliberately NOT keyed by the
// raw repo ULID: everything downstream keys by the wire slug (matching the M1.5
// publish endpoint), and the DEK rows RetireRef shreds are slug-keyed too.
type OverlayBranchIndex interface {
	// Record notes that branch published the overlay at overlayRef. Idempotent —
	// recording the same (repoKey, branch, overlayRef) twice is a no-op.
	Record(ctx context.Context, repoKey, branch, overlayRef string) error
	// Overlays returns the overlay refs currently recorded for branch (its
	// retirement worklist).
	Overlays(ctx context.Context, repoKey, branch string) ([]string, error)
	// RetireRef atomically removes (repoKey, branch, overlayRef) from the index
	// and, IFF no other branch still references overlayRef, crypto-shreds the
	// overlay's DEK — reporting the shredded ciphertext version. The index-row
	// removal and the DEK deletion succeed or fail TOGETHER: a shred failure leaves
	// the index row intact for retry (never de-index-without-shred), and a shared
	// coordinate is shredded only by the last branch to retire it (never
	// over-reaped). shredded is false (and shreddedVersion "") when a sibling still
	// references overlayRef or the DEK was already gone.
	RetireRef(ctx context.Context, repoKey, branch, overlayRef string) (shreddedVersion string, shredded bool, err error)
}

// OverlayRef renders the logical overlay coordinate ref for a base..head range.
// An overlay's BrainKey is {slug, KindOverlay, OverlayRef(base, head)}; a fresh
// create has an empty base, yielding "..head".
func OverlayRef(base, head string) string {
	return base + ".." + head
}

// MemOverlayBranchIndex is an in-process OverlayBranchIndex for dev/test. It
// mirrors the Pg implementation's atomicity under a SINGLE mutex: RetireRef
// counts cross-branch siblings, shreds the DEK via the shared DEKStore only when
// none remain, and removes the index row only AFTER any required shred succeeds —
// so a DEK-delete failure leaves the row for retry, exactly like the Pg tx
// rolling back.
type MemOverlayBranchIndex struct {
	mu sync.Mutex
	// rows[repoKey][branch] is the set of overlay refs that branch published.
	rows map[string]map[string]map[string]struct{}
	// deks is the SAME DEK store the EncryptingStore uses, so a shred here makes
	// the overlay undecryptable through the store.
	deks brainstore.DEKStore
}

// NewMemOverlayBranchIndex builds an empty in-process index over the shared DEK
// store (the one the EncryptingStore seals under).
func NewMemOverlayBranchIndex(deks brainstore.DEKStore) *MemOverlayBranchIndex {
	return &MemOverlayBranchIndex{rows: map[string]map[string]map[string]struct{}{}, deks: deks}
}

func (m *MemOverlayBranchIndex) Record(ctx context.Context, repoKey, branch, overlayRef string) error {
	if repoKey == "" || branch == "" || overlayRef == "" {
		return errors.New("brainbuild: empty repoKey/branch/overlayRef in Record")
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	branches := m.rows[repoKey]
	if branches == nil {
		branches = map[string]map[string]struct{}{}
		m.rows[repoKey] = branches
	}
	refs := branches[branch]
	if refs == nil {
		refs = map[string]struct{}{}
		branches[branch] = refs
	}
	refs[overlayRef] = struct{}{}
	return nil
}

func (m *MemOverlayBranchIndex) Overlays(ctx context.Context, repoKey, branch string) ([]string, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	set := m.rows[repoKey][branch]
	out := make([]string, 0, len(set))
	for ref := range set {
		out = append(out, ref)
	}
	return out, nil
}

// RetireRef performs the atomic, refcounted retirement under the mutex. The order
// is chosen to be leak-safe: it computes the cross-branch sibling count FIRST
// (without mutating), performs the DEK shred if required, and only removes the
// index row once any needed shred has succeeded. If the shred errors, it returns
// WITHOUT touching the index — the row survives for a retry.
func (m *MemOverlayBranchIndex) RetireRef(ctx context.Context, repoKey, branch, overlayRef string) (string, bool, error) {
	m.mu.Lock()
	defer m.mu.Unlock()

	// remaining = branches OTHER than this one that reference overlayRef. This
	// mirrors the Pg count taken AFTER deleting this branch's row.
	remaining := 0
	for b, refs := range m.rows[repoKey] {
		if b == branch {
			continue
		}
		if _, ok := refs[overlayRef]; ok {
			remaining++
		}
	}

	version := ""
	shredded := false
	if remaining == 0 {
		// Last reference: crypto-shred. Read the live version first (RetireRef must
		// report it), then delete the DEK. Any error here returns BEFORE the index
		// row is removed, so the retirement can be retried.
		key := brainstore.BrainKey{RepoKey: repoKey, Kind: brainstore.KindOverlay, Ref: overlayRef}
		_, v, err := m.deks.GetDEK(ctx, key)
		switch {
		case errors.Is(err, brainstore.ErrNotFound):
			// DEK already gone — nothing to shred; safe to de-index.
		case err != nil:
			return "", false, err // leave the index row for retry
		default:
			if derr := m.deks.DeleteDEK(ctx, key); derr != nil {
				return "", false, derr // leak-safe: index row untouched
			}
			version = v
			shredded = true
		}
	}

	// Remove the index row (reached only after any required shred succeeded).
	if branches := m.rows[repoKey]; branches != nil {
		if set := branches[branch]; set != nil {
			delete(set, overlayRef)
			if len(set) == 0 {
				delete(branches, branch)
			}
		}
		if len(branches) == 0 {
			delete(m.rows, repoKey)
		}
	}
	return version, shredded, nil
}
