package brainbuild

import (
	"context"
	"fmt"
	"sync"

	"github.com/jackc/pgx/v5/pgxpool"
)

// CoordinateLocker serializes work on a single brain coordinate (an overlay
// BrainKey string). WithLock runs fn while holding the named lock and releases it
// when fn returns.
//
// THE INVARIANT (honored by both StorePublisher.Publish and StoreOverlayGC.GC):
// NO party pins a WORK-pool connection while blocked waiting on the coordinate
// lock. The Pg locker holds the advisory lock on a DEDICATED pool, so a publish
// and a GC of the same coordinate — which acquire the SAME lock key first, before
// touching the work pool — mutually exclude WITHOUT either holding a work
// connection during the wait. That eliminates three failures at once: the
// GC↔Publish cross-pool circular wait, concurrent-publish-vs-GC data loss (they
// serialize on the key), and publisher-vs-publisher work-pool starvation.
// Different coordinates never contend.
type CoordinateLocker interface {
	WithLock(ctx context.Context, key string, fn func(ctx context.Context) error) error
}

// MemCoordinateLocker is an in-process CoordinateLocker for dev/test: a refcounted
// keyed mutex. Each key maps to a mutex held for the duration of fn; the entry is
// reclaimed when the last waiter releases it, so the map does not grow unbounded.
type MemCoordinateLocker struct {
	mu    sync.Mutex
	locks map[string]*memLock
}

type memLock struct {
	mu   sync.Mutex
	refs int
}

// NewMemCoordinateLocker builds an empty in-process locker.
func NewMemCoordinateLocker() *MemCoordinateLocker {
	return &MemCoordinateLocker{locks: map[string]*memLock{}}
}

func (l *MemCoordinateLocker) WithLock(ctx context.Context, key string, fn func(ctx context.Context) error) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	// Acquire (or create) the per-key lock and bump its refcount so it isn't
	// reclaimed while we wait on it.
	l.mu.Lock()
	ml, ok := l.locks[key]
	if !ok {
		ml = &memLock{}
		l.locks[key] = ml
	}
	ml.refs++
	l.mu.Unlock()

