package brainbuild

import (
	"context"
	"errors"
	"sync"
)

// ErrFactRefConflict is returned by FactRefIndex.Advance when the compare-and-swap
// loses: the branch's fact-set head no longer equals the oldRef the caller merged
// against (a concurrent member advanced it first, or a create raced another
// create). It is the signal to re-read Current and re-merge — never a hard error.
var ErrFactRefConflict = errors.New("brainbuild: fact-set head changed (CAS conflict)")

// FactRefIndex is the moving per-branch HEAD of a repo's durable fact-set.
//
// Unlike OverlayBranchIndex — an append-only refcount over IMMUTABLE overlay
// coordinates — a fact-set head MOVES: every cross-member merge advances a branch
// from its old fact-blob ref to a new one. Multiple members race to advance the
// SAME (repoKey, branch), so the advance is a compare-and-swap: the caller supplies
// the ref it merged against (oldRef) and the ref it produced (newRef), and the swap
// lands only if the head still equals oldRef. On a mismatch it returns
// ErrFactRefConflict and makes NO change, telling the caller to re-read the (now
// newer) head and re-merge. This is the atomic, conflict-detectable fact-set
// advance the read-merge-CAS sync loop (M2.3) retries against.
//
// The keys are the repo SLUG (repoKey) and branch — the same slug the M1 publish
// endpoint and the DEK/overlay rows key by, NOT the raw repo ULID. A fact-set ref
// is content-addressed (facts-<sha256(canonical merged NDJSON)>): stable across
// re-seals, changing iff the merged fact-set changes.
type FactRefIndex interface {
	// Current returns the branch's current fact-set head ref and its version. found
	// is false (ref "", version 0) when the branch has no head yet — the signal to
	// Advance with an empty oldRef (a create).
	Current(ctx context.Context, repoKey, branch string) (ref string, version int64, found bool, err error)

	// Advance compare-and-swaps the branch head from oldRef to newRef, returning the
	// new version on success. An empty oldRef means CREATE — it succeeds only if no
	// head exists yet. A non-empty oldRef means UPDATE — it succeeds only if the head
	// still equals oldRef. Any losing swap (create raced a create, or update found a
	// moved/absent head) returns ErrFactRefConflict with no change. newRef must be
	// non-empty (a head always points at content); use the retirement/GC path, not an
	// empty Advance, to drop a fact-set.
	Advance(ctx context.Context, repoKey, branch, oldRef, newRef string) (newVersion int64, err error)
}

// MemFactRefIndex is an in-process FactRefIndex for dev/test. It mirrors the Pg
// implementation's CAS semantics under a SINGLE mutex: Current reads the head,
// Advance swaps it only when the observed oldRef still matches — so a concurrent
// Advance that moved the head makes a later stale-oldRef Advance return
// ErrFactRefConflict, exactly like the Pg conditional UPDATE affecting 0 rows.
type MemFactRefIndex struct {
	mu sync.Mutex
	// heads[repoKey][branch] is the branch's current fact-set head.
	heads map[string]map[string]factHead
}

type factHead struct {
	ref     string
	version int64
}

// NewMemFactRefIndex builds an empty in-process fact-set head index.
func NewMemFactRefIndex() *MemFactRefIndex {
	return &MemFactRefIndex{heads: map[string]map[string]factHead{}}
}

func (m *MemFactRefIndex) Current(ctx context.Context, repoKey, branch string) (string, int64, bool, error) {
	if err := ctx.Err(); err != nil {
		return "", 0, false, err
	}
	if repoKey == "" || branch == "" {
		return "", 0, false, errors.New("brainbuild: empty repoKey/branch in Current")
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	h, ok := m.heads[repoKey][branch]
	if !ok {
		return "", 0, false, nil
	}
	return h.ref, h.version, true, nil
}

func (m *MemFactRefIndex) Advance(ctx context.Context, repoKey, branch, oldRef, newRef string) (int64, error) {
	if err := ctx.Err(); err != nil {
		return 0, err
	}
	if repoKey == "" || branch == "" {
		return 0, errors.New("brainbuild: empty repoKey/branch in Advance")
	}
	if newRef == "" {
		return 0, errors.New("brainbuild: empty newRef in Advance (a head always points at content)")
	}
	m.mu.Lock()
	defer m.mu.Unlock()

	branches := m.heads[repoKey]
	cur, exists := branches[branch]

	if oldRef == "" {
		// CREATE: lands only if no head exists yet.
		if exists {
			return 0, ErrFactRefConflict
		}
		if branches == nil {
			branches = map[string]factHead{}
			m.heads[repoKey] = branches
		}
		branches[branch] = factHead{ref: newRef, version: 1}
		return 1, nil
	}

	// UPDATE: lands only if the head still equals oldRef.
	if !exists || cur.ref != oldRef {
		return 0, ErrFactRefConflict
	}
	next := cur.version + 1
	branches[branch] = factHead{ref: newRef, version: next}
	return next, nil
}

package brainbuild

import (
	"context"
	"errors"
	"fmt"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// PgFactRefIndex is the durable FactRefIndex backing cross-member fact sync in
// production: one row per (repo_key, branch) in the brain_fact_refs table
// (migration 038). It mirrors the store package's pgxpool patterns — unqualified
// names resolved via search_path, pgx.ErrNoRows mapped — and implements the CAS
// advance as a single conditional statement so the swap is atomic under DB-level
// row locking without an explicit transaction.
type PgFactRefIndex struct {
	pool *pgxpool.Pool
}

// NewPgFactRefIndex builds the durable fact-set head index over the given pool.
// The pool must resolve unqualified names in the `repo` schema and hold the
// repo_rw SELECT/INSERT/UPDATE grants on brain_fact_refs (038 grants no DELETE —
// heads only ever move). The same serve pool the DEK store uses satisfies this.
func NewPgFactRefIndex(pool *pgxpool.Pool) *PgFactRefIndex {
	return &PgFactRefIndex{pool: pool}
}

// Current reads the branch's fact-set head. A missing row (pgx.ErrNoRows) is the
// "no head yet" signal, returned as found=false — not an error.
func (s *PgFactRefIndex) Current(ctx context.Context, repoKey, branch string) (string, int64, bool, error) {
	if repoKey == "" || branch == "" {
		return "", 0, false, errors.New("brainbuild: empty repoKey/branch in Current")
	}
	var ref string
	var version int64
	err := s.pool.QueryRow(ctx,
		`SELECT current_ref, version FROM brain_fact_refs WHERE repo_key = $1 AND branch = $2`,
		repoKey, branch).Scan(&ref, &version)
	if errors.Is(err, pgx.ErrNoRows) {
		return "", 0, false, nil
	}
	if err != nil {
		return "", 0, false, fmt.Errorf("brainbuild: read fact-set head %s/%s: %w", repoKey, branch, err)
	}
	return ref, version, true, nil
}

// Advance performs the compare-and-swap as a single conditional statement:
//
//   - CREATE (empty oldRef): INSERT ... ON CONFLICT DO NOTHING RETURNING version.
//     A row already existing yields no RETURNING row (pgx.ErrNoRows) → the create
//     lost a race → ErrFactRefConflict.
//   - UPDATE (non-empty oldRef): UPDATE ... WHERE current_ref = oldRef RETURNING
//     version. A moved or absent head matches no row (pgx.ErrNoRows) →
//     ErrFactRefConflict.
//
// Either way the swap is atomic: Postgres row-locks the (repo_key, branch) key for
// the statement, so two concurrent Advances against the same head serialize and
// exactly one wins — the loser sees the other's committed value and its WHERE
// clause matches nothing.
func (s *PgFactRefIndex) Advance(ctx context.Context, repoKey, branch, oldRef, newRef string) (int64, error) {
	if repoKey == "" || branch == "" {
		return 0, errors.New("brainbuild: empty repoKey/branch in Advance")
	}
	if newRef == "" {
		return 0, errors.New("brainbuild: empty newRef in Advance (a head always points at content)")
	}

	var next int64
	var err error
	if oldRef == "" {
		err = s.pool.QueryRow(ctx, `
			INSERT INTO brain_fact_refs (repo_key, branch, current_ref, version)
			VALUES ($1, $2, $3, 1)
			ON CONFLICT (repo_key, branch) DO NOTHING
			RETURNING version`,
			repoKey, branch, newRef).Scan(&next)
	} else {
		err = s.pool.QueryRow(ctx, `
			UPDATE brain_fact_refs
			SET current_ref = $3, version = version + 1, updated_at = now()
			WHERE repo_key = $1 AND branch = $2 AND current_ref = $4
			RETURNING version`,
			repoKey, branch, newRef, oldRef).Scan(&next)
	}
	if errors.Is(err, pgx.ErrNoRows) {
		return 0, ErrFactRefConflict
	}
	if err != nil {
		return 0, fmt.Errorf("brainbuild: advance fact-set head %s/%s: %w", repoKey, branch, err)
	}
	return next, nil
}

