package brainbuild

import (
	"context"
	"errors"
	"testing"
)

// compile-time: MemFactRefIndex satisfies FactRefIndex.
var _ FactRefIndex = (*MemFactRefIndex)(nil)

func TestMemFactRefIndexCreateAdvanceConflict(t *testing.T) {
	ctx := context.Background()
	idx := NewMemFactRefIndex()

	const slug, branch = "gh/acme/widgets", "main"

	// No head yet.
	if ref, v, found, err := idx.Current(ctx, slug, branch); err != nil || found || ref != "" || v != 0 {
		t.Fatalf("Current(empty) = %q, %d, %v, %v; want \"\", 0, false, nil", ref, v, found, err)
	}

	// CREATE: empty oldRef lands only when no head exists.
	v, err := idx.Advance(ctx, slug, branch, "", "facts-aaa")
	if err != nil || v != 1 {
		t.Fatalf("Advance create = %d, %v; want 1, nil", v, err)
	}
	if ref, v, found, err := idx.Current(ctx, slug, branch); err != nil || !found || ref != "facts-aaa" || v != 1 {
		t.Fatalf("Current after create = %q, %d, %v, %v; want facts-aaa, 1, true, nil", ref, v, found, err)
	}

	// CREATE again → conflict (head already exists), no change.
	if _, err := idx.Advance(ctx, slug, branch, "", "facts-bbb"); !errors.Is(err, ErrFactRefConflict) {
		t.Fatalf("Advance create-again err = %v; want ErrFactRefConflict", err)
	}
	if ref, _, _, _ := idx.Current(ctx, slug, branch); ref != "facts-aaa" {
		t.Fatalf("head mutated by losing create: %q", ref)
	}

	// UPDATE with the correct oldRef → advances, version bumps.
	v, err = idx.Advance(ctx, slug, branch, "facts-aaa", "facts-bbb")
	if err != nil || v != 2 {
		t.Fatalf("Advance update = %d, %v; want 2, nil", v, err)
	}

	// UPDATE with a STALE oldRef → conflict, no change.
	if _, err := idx.Advance(ctx, slug, branch, "facts-aaa", "facts-ccc"); !errors.Is(err, ErrFactRefConflict) {
		t.Fatalf("Advance stale-old err = %v; want ErrFactRefConflict", err)
	}
	if ref, v, _, _ := idx.Current(ctx, slug, branch); ref != "facts-bbb" || v != 2 {
		t.Fatalf("head after stale update = %q, %d; want facts-bbb, 2", ref, v)
