}

func TestMemFactRefIndexIsolationAndValidation(t *testing.T) {
	ctx := context.Background()
	idx := NewMemFactRefIndex()

	// Different (repo, branch) heads are independent.
	if _, err := idx.Advance(ctx, "gh/a/x", "main", "", "facts-1"); err != nil {
		t.Fatal(err)
	}
	if _, err := idx.Advance(ctx, "gh/a/x", "feat", "", "facts-2"); err != nil {
		t.Fatal(err) // same repo, other branch — no conflict
	}
	if _, err := idx.Advance(ctx, "gh/b/y", "main", "", "facts-3"); err != nil {
		t.Fatal(err) // other repo, same branch — no conflict
	}
	if ref, _, _, _ := idx.Current(ctx, "gh/a/x", "main"); ref != "facts-1" {
		t.Fatalf("cross-key bleed: gh/a/x@main = %q", ref)
	}

	// Validation: empty newRef rejected (a head always points at content).
	if _, err := idx.Advance(ctx, "gh/a/x", "main", "facts-1", ""); err == nil {
		t.Fatal("Advance with empty newRef should error")
	}
	if _, err := idx.Advance(ctx, "", "main", "", "facts-x"); err == nil {
		t.Fatal("Advance with empty repoKey should error")
	}
	if _, _, _, err := idx.Current(ctx, "gh/a/x", ""); err == nil {
		t.Fatal("Current with empty branch should error")
	}
}

