// TestIntegrationPgFactRefIndex exercises the durable CAS fact-set head against a
// real Postgres: create-once, conditional advance, stale-old conflict, and — the
// load-bearing property — that concurrent racers advancing the SAME head resolve to
// EXACTLY ONE winner, every loser getting a retryable ErrFactRefConflict.
// Skips (via openTestPool) when ACTIVITY_TEST_DATABASE_URL is unset.
func TestIntegrationPgFactRefIndex(t *testing.T) {
	ctx := context.Background()
	pool := openTestPool(t)
	idx := NewPgFactRefIndex(pool)

	const slug, branch = "gh/acme/widgets", "main"

	// No head yet.
	if ref, v, found, err := idx.Current(ctx, slug, branch); err != nil || found || ref != "" || v != 0 {
		t.Fatalf("Current(empty) = %q, %d, %v, %v; want \"\", 0, false, nil", ref, v, found, err)
	}

	// CREATE.
	if v, err := idx.Advance(ctx, slug, branch, "", "facts-aaa"); err != nil || v != 1 {
		t.Fatalf("Advance create = %d, %v; want 1, nil", v, err)
	}
	if ref, v, found, err := idx.Current(ctx, slug, branch); err != nil || !found || ref != "facts-aaa" || v != 1 {
		t.Fatalf("Current after create = %q, %d, %v, %v", ref, v, found, err)
	}

	// CREATE again → conflict (ON CONFLICT DO NOTHING → no RETURNING row).
	if _, err := idx.Advance(ctx, slug, branch, "", "facts-bbb"); !errors.Is(err, ErrFactRefConflict) {
		t.Fatalf("Advance create-again = %v; want ErrFactRefConflict", err)
	}

	// UPDATE with correct oldRef → advances.
	if v, err := idx.Advance(ctx, slug, branch, "facts-aaa", "facts-bbb"); err != nil || v != 2 {
		t.Fatalf("Advance update = %d, %v; want 2, nil", v, err)
	}

	// UPDATE with stale oldRef → conflict, head unchanged.
	if _, err := idx.Advance(ctx, slug, branch, "facts-aaa", "facts-ccc"); !errors.Is(err, ErrFactRefConflict) {
		t.Fatalf("Advance stale-old = %v; want ErrFactRefConflict", err)
	}
	if ref, v, _, _ := idx.Current(ctx, slug, branch); ref != "facts-bbb" || v != 2 {
		t.Fatalf("head after stale update = %q, %d; want facts-bbb, 2", ref, v)
	}

	// CONCURRENT RACERS: all read the same head (facts-bbb) and try to advance it to
	// their own distinct ref. Exactly one CAS must win; the rest get ErrFactRefConflict.
	const racers = 8
	_, _, _, _ = idx.Current(ctx, slug, branch) // shared observed old = facts-bbb
	var wg sync.WaitGroup
	wins := make([]bool, racers)
	conflicts := make([]bool, racers)
	otherErr := make([]error, racers)
	for i := 0; i < racers; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			_, err := idx.Advance(ctx, slug, branch, "facts-bbb", fmt.Sprintf("facts-r%d", i))
			switch {
			case err == nil:
				wins[i] = true
			case errors.Is(err, ErrFactRefConflict):
				conflicts[i] = true
			default:
				otherErr[i] = err
			}
		}(i)
	}
	wg.Wait()

	nWins, nConf := 0, 0
	for i := 0; i < racers; i++ {
		if otherErr[i] != nil {
			t.Fatalf("racer %d unexpected error: %v", i, otherErr[i])
		}
		if wins[i] {
			nWins++
		}
		if conflicts[i] {
			nConf++
		}
	}
	if nWins != 1 || nConf != racers-1 {
		t.Fatalf("racers resolved to %d wins / %d conflicts; want 1 / %d", nWins, nConf, racers-1)
	}

	// The winning head is one of the racer refs at version 3 (bumped once from 2).
	ref, v, _, err := idx.Current(ctx, slug, branch)
	if err != nil || v != 3 {
		t.Fatalf("head after race = %q, ver %d, %v; want a racer ref at ver 3", ref, v, err)
	}
	if len(ref) < len("facts-r") || ref[:len("facts-r")] != "facts-r" {
		t.Fatalf("winning head %q is not a racer ref", ref)
	}
}

