package brainbuild

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"

	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/entirehq/entire-api/internal/brainstore"
)

// Sentinel errors for the store seams.
var (
	// ErrUnresolvedRepo is returned (fail-closed) when a repo ULID resolves to an
	// empty/unknown slug: nothing is stored, promoted, or shredded.
	ErrUnresolvedRepo = errors.New("brainbuild: repo slug unresolved")
	// ErrNotFound is returned by StorePromoter.Promote when the overlay to promote
	// does not exist.
	ErrNotFound = errors.New("brainbuild: not found")
)

// RepoSlugResolver resolves a repo ULID to its wire slug ("gh/owner/repo") — the
// repo_key every brain artifact is stored under. Defined locally (no dependency on
// internal/httpapi); the serve-time brainSlugResolver satisfies it structurally.
// An empty slug means unknown/unresolvable.
type RepoSlugResolver interface {
	Resolve(ctx context.Context, repoID string) (slug string, err error)
}

// resolveSlug resolves repoID to a slug and fails closed: an error propagates and
// an empty slug becomes ErrUnresolvedRepo, so no seam ever stores or shreds under
// a raw ULID or an unknown repo.
func resolveSlug(ctx context.Context, r RepoSlugResolver, repoID string) (string, error) {
	slug, err := r.Resolve(ctx, repoID)
	if err != nil {
		return "", fmt.Errorf("brainbuild: resolve repo slug %q: %w", repoID, err)
	}
	if slug == "" {
		return "", fmt.Errorf("%w: repo %q", ErrUnresolvedRepo, repoID)
	}
	return slug, nil
}

// encStore adapts a *brainstore.EncryptingStore to brainstore.Store so a
// ValidatingStore can sit ABOVE the encryption layer (Validating → Encrypting →
// object store), exactly as the M1.5 publish endpoint composes it. EncryptingStore
// exposes Put/Get/List (embedded) but not the GC-only Tag/ListWithMeta; those are
// unreachable on the publish path and fail closed rather than lie.
type encStore struct {
	*brainstore.EncryptingStore
}

func (encStore) ListWithMeta(context.Context, string, string) ([]brainstore.ObjectMeta, error) {
	return nil, fmt.Errorf("brainbuild: ListWithMeta is not part of the publish path")
}

func (encStore) Tag(context.Context, brainstore.BrainKey, map[string]string) error {
	return fmt.Errorf("brainbuild: Tag is not part of the publish path")
}

// StorePublisher publishes a bundle over the brainstore stack. It resolves the
// repo ULID to its slug ONCE, keys every artifact by that slug, and — for each
// KindOverlay artifact — records the branch→overlay-coordinate mapping in the
// OverlayBranchIndex, taking the coordinate lock around the Put+Record so a
// concurrent GC of the same coordinate is mutually excluded.
type StorePublisher struct {
	enc      *brainstore.EncryptingStore
	index    OverlayBranchIndex
	locker   CoordinateLocker
	resolver RepoSlugResolver
}

// NewStorePublisher composes the publisher.
func NewStorePublisher(enc *brainstore.EncryptingStore, index OverlayBranchIndex, locker CoordinateLocker, resolver RepoSlugResolver) *StorePublisher {
	return &StorePublisher{enc: enc, index: index, locker: locker, resolver: resolver}
}

