package brainbuild

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"

	"github.com/entirehq/entire-api/internal/brainstore"
)

// FactSetRef is the content-addressed logical ref for a facts blob: the sha256 of
// the exact plaintext NDJSON, prefixed. It is stable across re-seals (a fresh DEK
// per seal changes the ciphertext, not this plaintext-content ref) and changes iff
// the merged fact-set changes — so two members that independently merge to the SAME
// fact-set produce the SAME ref, and the CAS head collapses their writes.
func FactSetRef(plaintext []byte) string {
	sum := sha256.Sum256(plaintext)
	return "facts-" + hex.EncodeToString(sum[:])
}

// FactSetStore is the server-side, atomic fact-set head for cross-member sync. It
// composes the EncryptingStore (the encrypted facts blob at rest, keyed by
// KindFacts + content ref) and the FactRefIndex (the CAS branch head). It exposes
// exactly the two operations the read-merge-CAS sync loop drives:
//
//	Current — read the branch head's ref/version and the DECRYPTED facts blob (so an
//	          authorized member/runner can merge against it in plaintext);
//	Advance — store a freshly-merged plaintext blob (sealed under a fresh DEK) and
//	          compare-and-swap the branch head onto it.
//
// Advance uses STORE-THEN-CAS ordering: the blob is durably sealed+stored BEFORE the
// head is advanced onto it, so a head never points at a missing blob. A lost CAS
// (ErrFactRefConflict — a concurrent member advanced first) leaves the just-stored
// blob orphaned; because it is content-addressed it is harmless and reaped by the
// absence-of-reference GC. The runner re-reads Current and re-merges.
//
// Repo identity: callers pass the repo ULID (repoID); FactSetStore resolves it to
// the wire slug ONCE per op and fails closed (ErrUnresolvedRepo) — every blob and
// head row is keyed by the slug, never a raw ULID, matching the M1 publish endpoint.
type FactSetStore struct {
	enc      *brainstore.EncryptingStore
	refs     FactRefIndex
	resolver RepoSlugResolver
}

// NewFactSetStore composes the fact-set store over the encrypting blob store, the
// CAS head index, and the repo-slug resolver.
func NewFactSetStore(enc *brainstore.EncryptingStore, refs FactRefIndex, resolver RepoSlugResolver) *FactSetStore {
	return &FactSetStore{enc: enc, refs: refs, resolver: resolver}
}

// Current returns the branch's current fact-set head (ref, version) and the DECRYPTED
// facts blob it points at. found is false (with nil plaintext) when the branch has no
// head yet — the signal for the runner to merge into an empty base and Advance with an
// empty oldRef (a create). A head that points at a blob the store cannot return is a
// hard error, not a silent empty.
func (s *FactSetStore) Current(ctx context.Context, repoID, branch string) (ref string, version int64, plaintext []byte, found bool, err error) {
	slug, err := resolveSlug(ctx, s.resolver, repoID)
	if err != nil {
		return "", 0, nil, false, err
	}
	ref, version, found, err = s.refs.Current(ctx, slug, branch)
	if err != nil {
		return "", 0, nil, false, fmt.Errorf("brainbuild: current fact-set head %s/%s: %w", slug, branch, err)
	}
	if !found {
		return "", 0, nil, false, nil
	}
	plaintext, err = s.enc.Get(ctx, brainstore.BrainKey{RepoKey: slug, Kind: brainstore.KindFacts, Ref: ref})
	if err != nil {
		return "", 0, nil, false, fmt.Errorf("brainbuild: read fact-set blob %s/%s@%s: %w", slug, branch, ref, err)
	}
	return ref, version, plaintext, true, nil
}

// Advance seals+stores the merged plaintext facts blob and compare-and-swaps the
// branch head onto its content ref. oldRef is the ref the caller merged against — an
// empty oldRef means the caller merged into an empty base (a create). On success it
// returns the new content ref and the new head version. On a losing CAS it returns
// ErrFactRefConflict (the stored blob is left as a harmless content-addressed orphan);
// the caller re-reads Current and re-merges.
//
// A no-op advance (the merge produced exactly the current head's content, so newRef
// == oldRef) is rejected as ErrNoFactSetChange BEFORE any store or CAS — the runner
// should not call Advance when the merge changed nothing.
func (s *FactSetStore) Advance(ctx context.Context, repoID, branch, oldRef string, plaintext []byte) (newRef string, newVersion int64, err error) {
	if len(plaintext) == 0 {
		return "", 0, errors.New("brainbuild: empty plaintext in Advance (a fact-set head always points at content)")
	}
	slug, err := resolveSlug(ctx, s.resolver, repoID)
	if err != nil {
		return "", 0, err
	}
	newRef = FactSetRef(plaintext)
	if newRef == oldRef {
		// The merge changed nothing — advancing would only churn the version and
		// orphan a re-seal of identical content.
		return "", 0, ErrNoFactSetChange
	}

	// STORE-THEN-CAS: seal+store the blob first, so the head never points at a blob
	// that isn't durably present. A lost CAS below orphans this content-addressed
	// blob (GC-reapable), never corrupts the head.
	key := brainstore.BrainKey{RepoKey: slug, Kind: brainstore.KindFacts, Ref: newRef}
	if err := s.enc.Put(ctx, key, plaintext); err != nil {
		return "", 0, fmt.Errorf("brainbuild: seal+store fact-set blob %s/%s@%s: %w", slug, branch, newRef, err)
	}
	newVersion, err = s.refs.Advance(ctx, slug, branch, oldRef, newRef)
	if errors.Is(err, ErrFactRefConflict) {
		return "", 0, ErrFactRefConflict
	}
	if err != nil {
		return "", 0, fmt.Errorf("brainbuild: advance fact-set head %s/%s: %w", slug, branch, err)
	}
	return newRef, newVersion, nil
}

// ErrNoFactSetChange is returned by Advance when the merged plaintext is byte-identical
// to what the current head already points at (newRef == oldRef) — the runner merged in
// facts that were all already present. It is not an error condition; the runner treats
// it as "converged, nothing to publish".
var ErrNoFactSetChange = errors.New("brainbuild: fact-set unchanged by merge")

