package brainbuild

import (
	"context"
	"errors"
	"sort"
	"strings"
	"sync"
	"testing"

	"github.com/entirehq/entire-api/internal/brainstore"
	"github.com/entirehq/entire-api/internal/snapshotcrypt/snapshotcrypttest"
)

// newFactSetStore builds a Mem-backed FactSetStore: EncryptingStore over a mem
// object store + MemDEKStore + local test cipher, a MemFactRefIndex head, and the
// shared fakeResolver (testRepoID → testSlug).
func newFactSetStore() *FactSetStore {
	inner := brainstore.NewMemStore()
	deks := brainstore.NewMemDEKStore()
	enc := brainstore.NewEncryptingStore(inner, snapshotcrypttest.NewCipher(), deks)
	refs := NewMemFactRefIndex()
	resolver := fakeResolver{m: map[string]string{testRepoID: testSlug}}
	return NewFactSetStore(enc, refs, resolver)
}

// unionDedupSort is the test stand-in for the runner's real merge (factmerge, proven
// in entire-brain): keep-both union of NDJSON lines, exact duplicates collapsed, sorted
// deterministically. It mirrors factmerge's dedup-by-id + keep-both at the line level so
// the convergence/CAS/retry ORCHESTRATION can be proven here without importing the
// cgo-heavy brain merge core (ADR-P1-E: merge runs on the runner).
func unionDedupSort(base, incoming []string) []byte {
	set := map[string]struct{}{}
	for _, l := range base {
		if l != "" {
			set[l] = struct{}{}
		}
	}
	for _, l := range incoming {
		if l != "" {
			set[l] = struct{}{}
		}
	}
	out := make([]string, 0, len(set))
	for l := range set {
		out = append(out, l)
	}
	sort.Strings(out)
	if len(out) == 0 {
		return nil
	}
	return []byte(strings.Join(out, "\n") + "\n")
}

func splitLines(b []byte) []string {
	if len(b) == 0 {
		return nil
	}
	var out []string
	for _, l := range strings.Split(strings.TrimRight(string(b), "\n"), "\n") {
		if l != "" {
			out = append(out, l)
		}
	}
	return out
}

// memberSync runs the read-merge-CAS loop the sync runner drives: read the head,
// merge the member's local facts into the current plaintext, advance under CAS, and
// retry on ErrFactRefConflict. ErrNoFactSetChange means the member's facts were all
// already present (converged).
func memberSync(ctx context.Context, store *FactSetStore, repoID, branch string, local []string) error {
	for attempt := 0; attempt < 20; attempt++ {
		ref, _, plaintext, _, err := store.Current(ctx, repoID, branch)
		if err != nil {
			return err
		}
		merged := unionDedupSort(splitLines(plaintext), local)
		_, _, err = store.Advance(ctx, repoID, branch, ref, merged)
		switch {
		case err == nil:
			return nil
		case errors.Is(err, ErrNoFactSetChange):
			return nil
		case errors.Is(err, ErrFactRefConflict):
			continue // a concurrent member advanced first — re-read and re-merge
		default:
			return err
		}
	}
	return errors.New("memberSync: exceeded CAS retries")
}

func TestFactSetStoreCreateReadAdvance(t *testing.T) {
	ctx := context.Background()
	s := newFactSetStore()
	const branch = "main"

	// No head yet.
	if ref, v, pt, found, err := s.Current(ctx, testRepoID, branch); err != nil || found || ref != "" || v != 0 || pt != nil {
		t.Fatalf("Current(empty) = %q,%d,%v,%v,%v", ref, v, pt, found, err)
	}

	// Create: merge into empty base, advance with empty oldRef.
	blob := unionDedupSort(nil, []string{"fact:a", "fact:b"})
	ref1, v1, err := s.Advance(ctx, testRepoID, branch, "", blob)
	if err != nil || v1 != 1 || ref1 != FactSetRef(blob) {
		t.Fatalf("Advance create = %q,%d,%v", ref1, v1, err)
	}

	// Current returns the decrypted blob and the head.
	ref, v, pt, found, err := s.Current(ctx, testRepoID, branch)
	if err != nil || !found || ref != ref1 || v != 1 || string(pt) != string(blob) {
		t.Fatalf("Current after create = %q,%d,%q,%v,%v", ref, v, pt, found, err)
	}

	// No-op advance (identical content) → ErrNoFactSetChange, head untouched.
	if _, _, err := s.Advance(ctx, testRepoID, branch, ref1, blob); !errors.Is(err, ErrNoFactSetChange) {
		t.Fatalf("Advance no-op = %v; want ErrNoFactSetChange", err)
	}

	// Real advance (new fact) bumps the head.
	blob2 := unionDedupSort(splitLines(blob), []string{"fact:c"})
	ref2, v2, err := s.Advance(ctx, testRepoID, branch, ref1, blob2)
	if err != nil || v2 != 2 || ref2 != FactSetRef(blob2) {
		t.Fatalf("Advance update = %q,%d,%v", ref2, v2, err)
	}

	// Stale oldRef → conflict.
	blob3 := unionDedupSort(splitLines(blob), []string{"fact:d"})
	if _, _, err := s.Advance(ctx, testRepoID, branch, ref1, blob3); !errors.Is(err, ErrFactRefConflict) {
		t.Fatalf("Advance stale-old = %v; want ErrFactRefConflict", err)
	}

	// Empty plaintext rejected; unresolved repo fails closed.
	if _, _, err := s.Advance(ctx, testRepoID, branch, ref2, nil); err == nil {
		t.Fatal("Advance empty plaintext should error")
	}
	if _, _, _, _, err := s.Current(ctx, "unknown-ulid", branch); !errors.Is(err, ErrUnresolvedRepo) {
		t.Fatalf("Current unresolved repo = %v; want ErrUnresolvedRepo", err)
	}
}

// TestFactSetStoreTwoMemberConvergence is the load-bearing M2.3 proof: two members
// concurrently sync DISTINCT facts into the same branch through the read-merge-CAS
// loop. They must converge — the final fact-set contains BOTH members' facts, exact
// duplicates collapsed once — and the CAS conflict/retry path must be exercised (one
// member necessarily loses at least one swap and re-merges).
func TestFactSetStoreTwoMemberConvergence(t *testing.T) {
	ctx := context.Background()
	s := newFactSetStore()
	const branch = "main"

	// A shared fact (fact:s) proves dup-collapse; the rest are member-distinct.
	memberA := []string{"fact:s", "fact:a1", "fact:a2"}
	memberB := []string{"fact:s", "fact:b1", "fact:b2"}

	var wg sync.WaitGroup
	errs := make([]error, 2)
	wg.Add(2)
	go func() { defer wg.Done(); errs[0] = memberSync(ctx, s, testRepoID, branch, memberA) }()
	go func() { defer wg.Done(); errs[1] = memberSync(ctx, s, testRepoID, branch, memberB) }()
	wg.Wait()
	for i, err := range errs {
		if err != nil {
			t.Fatalf("member %d sync failed: %v", i, err)
		}
	}

	// Converged head must carry the UNION of both members' facts, deduped.
	_, _, pt, found, err := s.Current(ctx, testRepoID, branch)
	if err != nil || !found {
		t.Fatalf("Current after convergence = found %v, %v", found, err)
	}
	got := splitLines(pt)
	gotSet := map[string]bool{}
	for _, l := range got {
		if gotSet[l] {
			t.Fatalf("duplicate fact in converged set: %q", l)
		}
		gotSet[l] = true
	}
	want := []string{"fact:s", "fact:a1", "fact:a2", "fact:b1", "fact:b2"}
	if len(got) != len(want) {
		t.Fatalf("converged set = %v; want %v (union, deduped)", got, want)
	}
	for _, w := range want {
		if !gotSet[w] {
			t.Fatalf("converged set missing %q; got %v", w, got)
		}
	}
}

