// Package factsync is the runner-side read-merge-CAS loop that syncs a member's
// durable facts into the hosted, shared fact-set head. It is where the two P1.M2
// halves meet: the deterministic merge engine (internal/factmerge) and the hosted
// atomic head (entire-api's FactSetStore, reached here through the Server seam).
//
// Per ADR-P1-E the MERGE runs on the runner (this package), not in the API server:
// the server only stores encrypted blobs and compare-and-swaps the branch head, so
// it never needs the cgo/SQLite-heavy brain merge core. Sync pulls the current head
// in plaintext, keep-both promotes the member's local facts into it via factmerge,
// and pushes the result back under CAS — retrying on a losing swap.
package factsync

import (
	"bytes"
	"context"
	"errors"
	"time"

	"github.com/ashtom/entire-brain/internal/factmerge"
)

// ErrConflict is what a Server.Advance returns when the head moved under it (a
// concurrent member advanced first) — the signal for Sync to re-read and re-merge.
var ErrConflict = errors.New("factsync: fact-set head changed (CAS conflict)")

// ErrNoChange is what a Server.Advance returns when the merged blob is byte-identical
// to the current head — the member's facts were all already present. Sync treats it as
// "converged, nothing to publish", not an error.
var ErrNoChange = errors.New("factsync: fact-set unchanged by merge")

// ErrExhausted is returned when Sync cannot land its merge within maxAttempts CAS
// tries — sustained contention the caller should retry later or escalate.
var ErrExhausted = errors.New("factsync: exceeded CAS retries")

// maxAttempts bounds the read-merge-CAS loop so pathological contention fails loudly
// instead of spinning forever.
const maxAttempts = 32

// Server is the runner's view of the hosted fact-set head (entire-api's FactSetStore
// over HTTP). Current returns the branch head's content ref and the DECRYPTED facts
// blob (found=false, nil blob when the branch has no head yet — merge into empty).
// Advance seals+stores the merged plaintext and compare-and-swaps the head from oldRef
// onto its content ref, returning ErrConflict on a losing swap and ErrNoChange when the
// merge produced exactly the current content.
type Server interface {
	Current(ctx context.Context, repoID, branch string) (ref string, plaintext []byte, found bool, err error)
	Advance(ctx context.Context, repoID, branch, oldRef string, plaintext []byte) (newRef string, err error)
}

// Result reports the outcome of a Sync: whether the head advanced (Published), the new
// content ref, how many CAS attempts it took, and any review Proposals the keep-both
// merge queued (cross-member conflicts a human must resolve — the M2.4 surface).
type Result struct {
	Published bool
	NewRef    string
	Attempts  int
	Proposals []factmerge.Proposal
}

// Sync runs the read-merge-CAS loop: pull the head, keep-both promote local into it via
// factmerge, push under CAS, retry on ErrConflict. `now` is injected for determinism.
// A keep-both merge NEVER silently drops a member's fact (ADR-P1-G): identical facts
// (same content id) union their provenance; genuine conflicts are kept and queued as
// Proposals in the Result.
func Sync(ctx context.Context, srv Server, repoID, branch string, local []factmerge.Record, now time.Time) (Result, error) {
	for attempt := 1; attempt <= maxAttempts; attempt++ {
		ref, plaintext, found, err := srv.Current(ctx, repoID, branch)
		if err != nil {
			return Result{}, err
		}
		var head []factmerge.Record
		if found && len(plaintext) > 0 {
			head, err = factmerge.ParseNDJSON(bytes.NewReader(plaintext))
			if err != nil {
				return Result{}, err
			}
		}

		// Cross-member merge is structurally cross-branch promote: the member's local
		// facts are the "source" promoted (keep-both) into the current head "target".
		merged, proposals, _ := factmerge.Promote(local, head, "keep-both", branch, now)

		var buf bytes.Buffer
		if err := factmerge.WriteNDJSON(&buf, merged); err != nil {
			return Result{}, err
		}

		newRef, err := srv.Advance(ctx, repoID, branch, ref, buf.Bytes())
		switch {
		case err == nil:
			return Result{Published: true, NewRef: newRef, Attempts: attempt, Proposals: proposals}, nil
		case errors.Is(err, ErrNoChange):
			return Result{Published: false, NewRef: ref, Attempts: attempt, Proposals: proposals}, nil
		case errors.Is(err, ErrConflict):
			continue // a concurrent member advanced first — re-read the newer head and re-merge
		default:
			return Result{}, err
		}
	}
	return Result{}, ErrExhausted
}

package factsync

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"sync"
	"testing"
	"time"

	"github.com/ashtom/entire-brain/internal/factmerge"
)

// fakeServer mirrors entire-api's FactSetStore semantics in-memory: a content-addressed
// head (ref = facts-<sha256(plaintext)>) advanced under CAS. Advance returns ErrNoChange
// when the merged blob equals the current content (newRef==oldRef, checked first, exactly
// as FactSetStore.Advance short-circuits before store/CAS) and ErrConflict when the head
// moved under the caller (oldRef != current). Thread-safe for concurrent members.
type fakeServer struct {
	mu    sync.Mutex
	ref   string
	blob  []byte
	found bool
}

func contentRef(plaintext []byte) string {
	sum := sha256.Sum256(plaintext)
	return "facts-" + hex.EncodeToString(sum[:])
}

func (s *fakeServer) Current(_ context.Context, _, _ string) (string, []byte, bool, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if !s.found {
		return "", nil, false, nil
	}
	cp := make([]byte, len(s.blob))
	copy(cp, s.blob)
	return s.ref, cp, true, nil
}

func (s *fakeServer) Advance(_ context.Context, _, _, oldRef string, plaintext []byte) (string, error) {
	newRef := contentRef(plaintext)
	if newRef == oldRef {
		return "", ErrNoChange
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	cur := ""
	if s.found {
		cur = s.ref
	}
	if oldRef != cur {
		return "", ErrConflict
	}
	s.ref, s.blob, s.found = newRef, append([]byte(nil), plaintext...), true
	return newRef, nil
}

// fact builds a fully-formed active distilled Record. Two facts with the same text and
// paths share a content-derived ID, so members that independently learn the same fact
// collapse to one record whose provenance is the UNION of their anchors.
func fact(text string, paths []string, session string, now time.Time) factmerge.Record {
	np := factmerge.NormalizePaths(paths)
	return factmerge.Record{
		ID:         factmerge.RecordID(text, np),
		Paths:      np,
		Text:       text,
		Branch:     "main",
		Origin:     "distilled",
		Status:     factmerge.StatusActive,
		Provenance: []factmerge.Anchor{{SessionID: session}},
		CreatedAt:  now,
		UpdatedAt:  now,
	}
}

func sessionSet(a factmerge.Anchor) string { return a.SessionID }

// TestSyncConvergesAndUnionsProvenance is the load-bearing M2.3 proof with the REAL
// merge engine: two members concurrently sync into one branch. A shared fact (same
// text+paths → same id) carries a DIFFERENT provenance anchor per member; distinct
// facts are member-unique. After both converge, the head must contain every distinct
// fact plus ONE copy of the shared fact whose provenance is the UNION of both members'
// anchors — nothing dropped, exact dup collapsed, provenance merged.
func TestSyncConvergesAndUnionsProvenance(t *testing.T) {
	ctx := context.Background()
	srv := &fakeServer{}
	now := time.Date(2026, 7, 7, 0, 0, 0, 0, time.UTC)

	shared := "the build uses bazel"
	sharedPaths := []string{"build/tooling"}

	memberA := []factmerge.Record{
		fact(shared, sharedPaths, "session-A", now),
		fact("api timeouts default to 30s", []string{"api/config"}, "session-A", now),
	}
	memberB := []factmerge.Record{
		fact(shared, sharedPaths, "session-B", now),
		fact("migrations run on deploy", []string{"ops/deploy"}, "session-B", now),
	}

	var wg sync.WaitGroup
	res := make([]Result, 2)
	errs := make([]error, 2)
	wg.Add(2)
	go func() { defer wg.Done(); res[0], errs[0] = Sync(ctx, srv, "repo", "main", memberA, now) }()
	go func() { defer wg.Done(); res[1], errs[1] = Sync(ctx, srv, "repo", "main", memberB, now) }()
	wg.Wait()
	for i := range errs {
		if errs[i] != nil {
			t.Fatalf("member %d sync failed: %v", i, errs[i])
		}
	}

	// Read the converged head.
	_, blob, found, err := srv.Current(ctx, "repo", "main")
	if err != nil || !found {
		t.Fatalf("Current after convergence: found=%v err=%v", found, err)
	}
	recs, err := factmerge.ParseNDJSON(bytesReader(blob))
	if err != nil {
		t.Fatalf("parse converged head: %v", err)
	}

	byText := map[string]factmerge.Record{}
	for _, r := range recs {
		if _, dup := byText[r.Text]; dup {
			t.Fatalf("duplicate fact text in converged head: %q", r.Text)
		}
		byText[r.Text] = r
	}
	for _, want := range []string{shared, "api timeouts default to 30s", "migrations run on deploy"} {
		if _, ok := byText[want]; !ok {
			t.Fatalf("converged head missing fact %q; got %d records", want, len(recs))
		}
	}
	if len(recs) != 3 {
		t.Fatalf("converged head has %d records; want 3 (union, shared deduped)", len(recs))
	}

	// The shared fact's provenance must be the UNION of both members' sessions.
	sh := byText[shared]
	sessions := map[string]bool{}
	for _, a := range sh.Provenance {
		sessions[sessionSet(a)] = true
	}
	if !sessions["session-A"] || !sessions["session-B"] || len(sh.Provenance) != 2 {
		t.Fatalf("shared fact provenance = %+v; want union of session-A and session-B", sh.Provenance)
	}
}

// TestSyncRetriesOnConflict deterministically exercises the CAS retry path: a member
// reads the head, a competing writer advances it underneath, and the member's Advance
// then loses the swap (ErrConflict), forcing a re-read + re-merge that succeeds and
// preserves BOTH the competitor's and the member's facts.
func TestSyncRetriesOnConflict(t *testing.T) {
	ctx := context.Background()
	now := time.Date(2026, 7, 7, 0, 0, 0, 0, time.UTC)

	// Seed the head with a competitor's fact so the member starts from a non-empty head,
	// then interpose ANOTHER competitor write between the member's read and its advance.
	srv := &conflictOnceServer{
		inner:     &fakeServer{},
		intercept: fact("seeded competitor fact", []string{"misc/seed"}, "session-C", now),
		now:       now,
	}
	// Prime the head to v1 via the competitor.
	if _, err := Sync(ctx, srv.inner, "repo", "main", []factmerge.Record{srv.intercept}, now); err != nil {
		t.Fatalf("prime head: %v", err)
	}
	srv.arm() // next Current will be followed by an interposed competing advance

	member := []factmerge.Record{fact("member local fact", []string{"api/config"}, "session-M", now)}
	res, err := Sync(ctx, srv, "repo", "main", member, now)
	if err != nil {
		t.Fatalf("member sync: %v", err)
	}
	if res.Attempts < 2 {
		t.Fatalf("expected a retry (Attempts>=2), got %d", res.Attempts)
	}

	_, blob, _, _ := srv.inner.Current(ctx, "repo", "main")
	recs, err := factmerge.ParseNDJSON(bytesReader(blob))
	if err != nil {
		t.Fatalf("parse head: %v", err)
	}
	texts := map[string]bool{}
	for _, r := range recs {
		texts[r.Text] = true
	}
	for _, want := range []string{"seeded competitor fact", "member local fact"} {
		if !texts[want] {
			t.Fatalf("post-retry head missing %q; got %v", want, texts)
		}
	}
}

// conflictOnceServer wraps fakeServer and, once armed, interposes exactly one competing
// advance immediately after the next Current — deterministically staling the caller's
// read so its following Advance loses the CAS and must retry.
type conflictOnceServer struct {
	inner     *fakeServer
	intercept factmerge.Record
	now       time.Time
	armed     bool
}

func (s *conflictOnceServer) arm() { s.armed = true }

func (s *conflictOnceServer) Current(ctx context.Context, repoID, branch string) (string, []byte, bool, error) {
	ref, blob, found, err := s.inner.Current(ctx, repoID, branch)
	if s.armed {
		s.armed = false
		// Interpose a competing writer that advances the head, staling the ref just read.
		competitor := fact("interposed competitor fact", []string{"misc/interpose"}, "session-X", s.now)
		if _, aerr := Sync(ctx, s.inner, repoID, branch, []factmerge.Record{competitor}, s.now); aerr != nil {
			return "", nil, false, aerr
		}
	}
	return ref, blob, found, err
}

func (s *conflictOnceServer) Advance(ctx context.Context, repoID, branch, oldRef string, plaintext []byte) (string, error) {
	return s.inner.Advance(ctx, repoID, branch, oldRef, plaintext)
}

