// FactAdvanceEntryHash is the one canonical chain-link hash used by EVERY
// FactAdvanceLog implementation (Mem append, Mem verify, Pg append, Pg verify), so
// the chains are byte-identical regardless of backend:
//
//	entryHash = hex(sha256(
//	    prevHash || "\x00" || repoKey || "\x00" || branch || "\x00" ||
//	    oldRef   || "\x00" || newRef  || "\x00" || strconv.FormatInt(version, 10)))
//
// The NUL separators make the concatenation unambiguous (no field boundary can be
// forged by shifting bytes between adjacent fields). prevHash is the prior entry's
// entryHash on the same (repoKey, branch); it is "" for a branch's first entry.
func FactAdvanceEntryHash(prevHash, repoKey, branch, oldRef, newRef string, version int64) string {
	h := sha256.New()
	h.Write([]byte(prevHash))
	h.Write([]byte{0})
	h.Write([]byte(repoKey))
	h.Write([]byte{0})
	h.Write([]byte(branch))
	h.Write([]byte{0})
	h.Write([]byte(oldRef))
	h.Write([]byte{0})
	h.Write([]byte(newRef))
	h.Write([]byte{0})
	h.Write([]byte(strconv.FormatInt(version, 10)))
	return hex.EncodeToString(h.Sum(nil))
}

input.new_string:
// FactAdvanceEntryHash is the one canonical chain-link hash used by EVERY
// FactAdvanceLog implementation (Mem append, Mem verify, Pg append, Pg verify), so
// the chains are byte-identical regardless of backend:
//
//	entryHash = hex(sha256( LP(prevHash) LP(repoKey) LP(branch) LP(oldRef) LP(newRef)
//	                        LP(strconv.FormatInt(version, 10)) ))
//
// where LP(s) is the LENGTH-PREFIXED encoding of s: an 8-byte big-endian length
// followed by the raw bytes of s. Length-prefixing makes the concatenation
// unambiguous for ARBITRARY field contents — unlike a NUL (or any fixed) separator,
// no field boundary can be forged by shifting bytes between adjacent fields even if a
// field itself contains the separator byte, so a canonicalization/collision attack
// across (repoKey, branch, oldRef, newRef) is impossible. prevHash is the prior
// entry's entryHash on the same (repoKey, branch); it is "" for a branch's first entry.
func FactAdvanceEntryHash(prevHash, repoKey, branch, oldRef, newRef string, version int64) string {
	h := sha256.New()
	writeLenPrefixed(h, prevHash)
	writeLenPrefixed(h, repoKey)
	writeLenPrefixed(h, branch)
	writeLenPrefixed(h, oldRef)
	writeLenPrefixed(h, newRef)
	writeLenPrefixed(h, strconv.FormatInt(version, 10))
	return hex.EncodeToString(h.Sum(nil))
}

// writeLenPrefixed writes an 8-byte big-endian length followed by s's raw bytes, so
// the field boundary is carried by the length, not by any in-band separator.
func writeLenPrefixed(h hash.Hash, s string) {
	var n [8]byte
	binary.BigEndian.PutUint64(n[:], uint64(len(s)))
	h.Write(n[:])
	h.Write([]byte(s))
}

