12	// PgFactAdvanceLog is the durable FactAdvanceLog backing the tamper-evident audit of
13	// fact-set head advances in production: one append-only row per advance in the
14	// brain_fact_advances table (migration 039). It mirrors the package's pgxpool
15	// patterns — unqualified names resolved via search_path, pgx.ErrNoRows mapped — and
16	// computes every chain hash in Go via FactAdvanceEntryHash so the Pg chain is
17	// byte-identical to the Mem chain and needs no Postgres digest extension.
18	type PgFactAdvanceLog struct {
19		pool *pgxpool.Pool
20	}
21	
22	// NewPgFactAdvanceLog builds the durable audit log over the given pool. The pool
23	// must resolve unqualified names in the `repo` schema and hold the repo_rw
24	// SELECT/INSERT grants on brain_fact_advances (039 grants no UPDATE, no DELETE —
25	// the log is append-only). The same serve pool the fact-ref index uses satisfies it.
26	func NewPgFactAdvanceLog(pool *pgxpool.Pool) *PgFactAdvanceLog {
27		return &PgFactAdvanceLog{pool: pool}
28	}
29	
30	// Append records one head advance in a single transaction: read the branch's prior
31	// entry_hash (ErrNoRows → first entry, prevHash=""), compute the new entry_hash in
32	// Go, INSERT the row, and COMMIT. The read is a plain ORDER BY id DESC LIMIT 1 — NOT
33	// a SELECT ... FOR UPDATE: this table is append-only (039 grants repo_rw no UPDATE),
34	// and a row-lock clause requires the UPDATE privilege the grant deliberately
35	// withholds. Serialization of same-branch appends is not needed here anyway — the
36	// upstream CAS on brain_fact_refs already lets exactly one advance win per branch
37	// version, so two appends never race for the same prev.
38	func (s *PgFactAdvanceLog) Append(ctx context.Context, repoKey, branch, oldRef, newRef string, version int64) (string, error) {
39		if err := ctx.Err(); err != nil {
40			return "", err
41		}
42		if repoKey == "" || branch == "" {
43			return "", errors.New("brainbuild: empty repoKey/branch in Append")
44		}
45	
46		tx, err := s.pool.Begin(ctx)
47		if err != nil {
48			return "", fmt.Errorf("brainbuild: begin audit append %s/%s: %w", repoKey, branch, err)
49		}
50		defer tx.Rollback(ctx) //nolint:errcheck // no-op after a successful Commit
51	
52		var prevHash string
53		err = tx.QueryRow(ctx,
54			`SELECT entry_hash FROM brain_fact_advances
55			 WHERE repo_key = $1 AND branch = $2
56			 ORDER BY id DESC LIMIT 1`,
57			repoKey, branch).Scan(&prevHash)
58		if errors.Is(err, pgx.ErrNoRows) {
59			prevHash = "" // first advance on this branch
60		} else if err != nil {
61			return "", fmt.Errorf("brainbuild: read audit chain head %s/%s: %w", repoKey, branch, err)
62		}
63	
64		entryHash := FactAdvanceEntryHash(prevHash, repoKey, branch, oldRef, newRef, version)
65	
66		if _, err := tx.Exec(ctx,
67			`INSERT INTO brain_fact_advances
68			   (repo_key, branch, old_ref, new_ref, version, prev_hash, entry_hash)
69			 VALUES ($1, $2, $3, $4, $5, $6, $7)`,
70			repoKey, branch, oldRef, newRef, version, prevHash, entryHash); err != nil {
71			return "", fmt.Errorf("brainbuild: append audit entry %s/%s: %w", repoKey, branch, err)
72		}
73	
74		if err := tx.Commit(ctx); err != nil {
75			return "", fmt.Errorf("brainbuild: commit audit append %s/%s: %w", repoKey, branch, err)
76		}
77		return entryHash, nil
78	}
79	
80	// Verify reads all advances for (repoKey, branch) in id order and recomputes the
81	// chain with FactAdvanceEntryHash, checking each row's prev_hash equals the running
82	// prior entry_hash and its entry_hash equals the recompute. It returns ok=false on
83	// the first mismatch (a tampered field or a broken link), plus the entry count.
84	func (s *PgFactAdvanceLog) Verify(ctx context.Context, repoKey, branch string) (bool, int, error) {
85		if err := ctx.Err(); err != nil {
86			return false, 0, err
87		}
88		if repoKey == "" || branch == "" {
89			return false, 0, errors.New("brainbuild: empty repoKey/branch in Verify")
90		}
91	
92		rows, err := s.pool.Query(ctx,
93			`SELECT old_ref, new_ref, version, prev_hash, entry_hash
94			 FROM brain_fact_advances
95			 WHERE repo_key = $1 AND branch = $2
96			 ORDER BY id`,
97			repoKey, branch)
98		if err != nil {
99			return false, 0, fmt.Errorf("brainbuild: read audit chain %s/%s: %w", repoKey, branch, err)
100		}
101		defer rows.Close()
102	
103		prev := ""
104		entries := 0
105		ok := true
106		for rows.Next() {
107			var oldRef, newRef, prevHash, entryHash string
108			var version int64
109			if err := rows.Scan(&oldRef, &newRef, &version, &prevHash, &entryHash); err != nil {
110				return false, entries, fmt.Errorf("brainbuild: scan audit entry %s/%s: %w", repoKey, branch, err)
111			}
112			entries++
113			if ok {
114				want := FactAdvanceEntryHash(prev, repoKey, branch, oldRef, newRef, version)
115				if prevHash != prev || entryHash != want {
116					ok = false
117				} else {
118					prev = entryHash
119				}
120			}
121		}
122		if err := rows.Err(); err != nil {
123			return false, entries, fmt.Errorf("brainbuild: iterate audit chain %s/%s: %w", repoKey, branch, err)
124		}
125		return ok, entries, nil
126	}
