// Append records one head advance in a single transaction: take a per-(repoKey,
// branch) advisory lock, read the branch's prior entry_hash (ErrNoRows → first entry,
// prevHash=""), compute the new entry_hash in Go, INSERT the row, and COMMIT.
//
// The advisory lock is load-bearing for chain integrity. The upstream CAS on
// brain_fact_refs serializes ADVANCES (one winner per branch version), but the audit
// append runs AFTER that CAS in a SEPARATE transaction — so without this lock two
// advances that have both passed their CAS can both read the same prior entry_hash
// and INSERT rows claiming the same prevHash, FORKING the chain. pg_advisory_xact_lock
// serializes the read+insert per branch, guaranteeing a linear chain; it needs no
// table privilege (unlike SELECT ... FOR UPDATE, which the append-only grant — 039
// withholds UPDATE — cannot use) and releases automatically on commit/rollback.
func (s *PgFactAdvanceLog) Append(ctx context.Context, repoKey, branch, oldRef, newRef string, version int64) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", err
	}
