// TestIntegrationPgFactAdvanceLogConcurrentNoFork proves the advisory lock keeps the
// chain LINEAR under the concurrency the CAS-then-audit ordering permits: many appends
// racing the SAME (repoKey, branch) — the exact window where two could read the same
// prior entry_hash and fork — resolve to a single linear chain (Verify ok, N entries,
// every prev_hash distinct so no two rows link the same parent).
func TestIntegrationPgFactAdvanceLogConcurrentNoFork(t *testing.T) {
	ctx := context.Background()
	pool := openTestPool(t)
	log := NewPgFactAdvanceLog(pool)

	admin, err := pgxpool.New(ctx, os.Getenv("ACTIVITY_TEST_DATABASE_URL"))
	if err != nil {
		t.Fatalf("open admin pool: %v", err)
	}
	defer admin.Close()

	const slug, branch = "gh/acme/racer", "main"
	if _, err := admin.Exec(ctx, "DELETE FROM repo.brain_fact_advances WHERE repo_key = $1", slug); err != nil {
		t.Fatalf("clean: %v", err)
	}

	const n = 12
	var wg sync.WaitGroup
	errs := make([]error, n)
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			_, errs[i] = log.Append(ctx, slug, branch, fmt.Sprintf("facts-%d", i), fmt.Sprintf("facts-%d", i+1), int64(i+1))
		}(i)
	}
	wg.Wait()
	for i, e := range errs {
		if e != nil {
			t.Fatalf("concurrent Append %d: %v", i, e)
		}
	}

	// The chain is linear and intact despite the race.
	if ok, got, err := log.Verify(ctx, slug, branch); err != nil || !ok || got != n {
		t.Fatalf("Verify(concurrent) = %v, %d, %v; want true, %d, nil", ok, got, err, n)
	}
	// No fork: every prev_hash is distinct (a fork would repeat a parent link).
	var distinct int
	if err := admin.QueryRow(ctx,
		`SELECT count(DISTINCT prev_hash) FROM repo.brain_fact_advances WHERE repo_key = $1 AND branch = $2`,
		slug, branch).Scan(&distinct); err != nil {
		t.Fatalf("count distinct prev_hash: %v", err)
	}
	if distinct != n {
		t.Fatalf("distinct prev_hash = %d; want %d (a repeat means the chain forked)", distinct, n)
	}
}

