// TestAuditedFactSetStoreConvergenceChainIntact is the whole-M2 capstone (Mem-backed):
// the FULLY composed path — EncryptingStore + CAS head + tamper-evident audit log —
// under two-member convergence. After both members sync distinct facts through the
// read-merge-CAS loop, the fact-set holds the union (shared fact deduped) AND the audit
// chain is a linear, intact record of every head advance that happened.
func TestAuditedFactSetStoreConvergenceChainIntact(t *testing.T) {
	ctx := context.Background()
	inner := brainstore.NewMemStore()
	deks := brainstore.NewMemDEKStore()
	enc := brainstore.NewEncryptingStore(inner, snapshotcrypttest.NewCipher(), deks)
	log := NewMemFactAdvanceLog()
	s := NewFactSetStore(enc, NewMemFactRefIndex(), fakeResolver{m: map[string]string{testRepoID: testSlug}}).WithAdvanceLog(log)
	const branch = "main"

	var wg sync.WaitGroup
	errs := make([]error, 2)
	wg.Add(2)
	go func() { defer wg.Done(); errs[0] = memberSync(ctx, s, testRepoID, branch, []string{"fact:s", "fact:a1"}) }()
	go func() { defer wg.Done(); errs[1] = memberSync(ctx, s, testRepoID, branch, []string{"fact:s", "fact:b1"}) }()
	wg.Wait()
	for i, err := range errs {
		if err != nil {
			t.Fatalf("member %d: %v", i, err)
		}
	}

	// Converged union.
	_, _, pt, found, err := s.Current(ctx, testRepoID, branch)
	if err != nil || !found {
		t.Fatalf("Current: found=%v err=%v", found, err)
	}
	got := map[string]bool{}
	for _, l := range splitLines(pt) {
		got[l] = true
	}
	for _, w := range []string{"fact:s", "fact:a1", "fact:b1"} {
		if !got[w] {
			t.Fatalf("converged set missing %q; got %v", w, splitLines(pt))
		}
	}

	// The audit chain over the slug/branch is intact and non-empty (>=2 advances: two
	// members, at least one retried after a losing CAS).
	ok, entries, err := log.Verify(ctx, testSlug, branch)
	if err != nil || !ok {
		t.Fatalf("audit Verify = ok %v, %v; want intact chain", ok, err)
	}
	if entries < 2 {
		t.Fatalf("audit chain has %d entries; want >= 2 (both members' advances)", entries)
	}
}

