	entries := m.chains[repoKey][branch]
	prev := ""
	seen := make(map[int64]bool, len(entries))
	var maxVersion int64
	for _, e := range entries {
		if e.prevHash != prev {
			return false, len(entries), nil
		}
		want := FactAdvanceEntryHash(prev, repoKey, branch, e.oldRef, e.newRef, e.version)
		if e.entryHash != want {
			return false, len(entries), nil
		}
		// Version-SET completeness: the CAS bumps the head version by exactly 1 per
		// advance (create=1, then +1), so a complete chain's versions are the set
		// {1..N}. Checked as a SET (distinct, ≥1, max==count), NOT in chain order —
		// the advisory-locked append serializes in lock-acquisition order, so two
		// concurrent advances may be logged out of version order yet still be complete.
		// A MISSING entry (an advance whose audit Append failed after its CAS committed)
		// leaves a hole in the set — the only way that partial failure is detectable,
		// since the surviving entries still hash-link cleanly.
		if e.version < 1 || seen[e.version] {
			return false, len(entries), nil
		}
		seen[e.version] = true
		if e.version > maxVersion {
			maxVersion = e.version
		}
		prev = e.entryHash
	}
	if len(entries) > 0 && maxVersion != int64(len(entries)) {
		return false, len(entries), nil // a gap: N distinct versions but max != N
	}
	return true, len(entries), nil
}

