package factsync

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
)

// HTTPServer is the real Server adapter: it drives entire-api's fact-set sync
// endpoints (internal/httpapi/brain_facts.go) over HTTP so the sync runner can talk to
// the hosted head. It is the production implementor of the Server seam that Sync/Resolve
// are written against (the tests use an in-memory fake with identical semantics).
//
// Wire contract (must stay in lockstep with brain_facts.go):
//
//	GET  {BaseURL}/api/v1/repos/{repoID}/brain/facts?branch=… → 200
//	     {found, ref, version, data(base64)}   (pull-gated)
//	POST {BaseURL}/api/v1/repos/{repoID}/brain/facts/advance  → 200
//	     {new_ref, version, unchanged}         (push-gated)
//	     body {branch, old_ref, data(base64)}
//	     409 → the head advanced concurrently (→ ErrConflict, re-read + re-merge)
//	     unchanged:true → the merge changed nothing (→ ErrNoChange, converged)
//
// Data crosses the wire base64-encoded: huma serializes a Go []byte as a base64 JSON
// string, and encoding/json here does the same on both sides, so the []byte fields match
// byte-for-byte. Authorization is a bearer token (the member's session/runner token).
type HTTPServer struct {
	BaseURL string       // entire-api origin, e.g. https://api.entire.io (no trailing slash needed)
	Token   string       // bearer token; sent as Authorization: Bearer <token> when non-empty
	Client  *http.Client // defaults to http.DefaultClient when nil
}

func (h *HTTPServer) client() *http.Client {
	if h.Client != nil {
		return h.Client
	}
	return http.DefaultClient
}

func (h *HTTPServer) newRequest(ctx context.Context, method, path string, body io.Reader) (*http.Request, error) {
	req, err := http.NewRequestWithContext(ctx, method, strings.TrimRight(h.BaseURL, "/")+path, body)
	if err != nil {
		return nil, err
	}
	if h.Token != "" {
		req.Header.Set("Authorization", "Bearer "+h.Token)
	}
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	return req, nil
}

// Current reads the branch's fact-set head. A 200 with found=false (no head yet) returns
// found=false and nil plaintext; the data field is base64-decoded by encoding/json into
// the []byte. Any non-200 is an error (the runner cannot merge against an unknown state).
func (h *HTTPServer) Current(ctx context.Context, repoID, branch string) (string, []byte, bool, error) {
	path := fmt.Sprintf("/api/v1/repos/%s/brain/facts?branch=%s", url.PathEscape(repoID), url.QueryEscape(branch))
	req, err := h.newRequest(ctx, http.MethodGet, path, nil)
	if err != nil {
		return "", nil, false, err
	}
	resp, err := h.client().Do(req)
	if err != nil {
		return "", nil, false, fmt.Errorf("factsync: GET fact-set head %s/%s: %w", repoID, branch, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return "", nil, false, fmt.Errorf("factsync: GET fact-set head %s/%s: unexpected status %s", repoID, branch, resp.Status)
	}
	var out struct {
		Found   bool   `json:"found"`
		Ref     string `json:"ref"`
		Version int64  `json:"version"`
		Data    []byte `json:"data"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return "", nil, false, fmt.Errorf("factsync: decode fact-set head %s/%s: %w", repoID, branch, err)
	}
	if !out.Found {
		return "", nil, false, nil
	}
	return out.Ref, out.Data, true, nil
}

// Advance compare-and-swaps the head onto plaintext, mapping the endpoint's outcomes to
// the Server contract: 200 → the new ref; 200 with unchanged:true → ErrNoChange; 409 →
// ErrConflict. Any other status is an error (a 400 empty-data, 404 unknown repo, 503
// unconfigured, or 5xx — none of which the runner should paper over).
func (h *HTTPServer) Advance(ctx context.Context, repoID, branch, oldRef string, plaintext []byte) (string, error) {
	reqBody := struct {
		Branch string `json:"branch"`
		OldRef string `json:"old_ref"`
		Data   []byte `json:"data"`
	}{Branch: branch, OldRef: oldRef, Data: plaintext}
	buf, err := json.Marshal(reqBody)
	if err != nil {
		return "", err
	}
	path := fmt.Sprintf("/api/v1/repos/%s/brain/facts/advance", url.PathEscape(repoID))
	req, err := h.newRequest(ctx, http.MethodPost, path, bytes.NewReader(buf))
	if err != nil {
		return "", err
	}
	resp, err := h.client().Do(req)
	if err != nil {
		return "", fmt.Errorf("factsync: POST advance %s/%s: %w", repoID, branch, err)
	}
	defer resp.Body.Close()

	switch resp.StatusCode {
	case http.StatusOK:
		var out struct {
			NewRef    string `json:"new_ref"`
			Version   int64  `json:"version"`
			Unchanged bool   `json:"unchanged"`
		}
		if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
			return "", fmt.Errorf("factsync: decode advance %s/%s: %w", repoID, branch, err)
		}
		if out.Unchanged {
			return "", ErrNoChange
		}
		return out.NewRef, nil
	case http.StatusConflict:
		return "", ErrConflict
	default:
		return "", fmt.Errorf("factsync: POST advance %s/%s: unexpected status %s", repoID, branch, resp.Status)
	}
}

package factsync

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/ashtom/entire-brain/internal/factmerge"
)

// compile-time: HTTPServer satisfies the Server seam Sync/Resolve are written against.
var _ Server = (*HTTPServer)(nil)

// contractServer stands up an httptest server that speaks entire-api's fact-set sync
// wire contract (brain_facts.go) backed by an in-memory fakeServer. It lets the REAL
// HTTPServer adapter be exercised over a real HTTP round-trip — JSON encoding, base64
// data, query/body branch, and the 200/200-unchanged/409/400 status mapping — validating
// the adapter against the documented contract. (End-to-end validation against the live
// entire-api handler is the deploy-time step; the two Go modules can't share types.)
func contractServer(t *testing.T, fake *fakeServer) *httptest.Server {
	t.Helper()
	ctx := context.Background()
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		switch {
		case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/brain/facts"):
			ref, blob, found, _ := fake.Current(ctx, "repo", r.URL.Query().Get("branch"))
			_ = json.NewEncoder(w).Encode(map[string]any{"found": found, "ref": ref, "version": 1, "data": blob})

		case r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/brain/facts/advance"):
			var body struct {
				Branch string `json:"branch"`
				OldRef string `json:"old_ref"`
				Data   []byte `json:"data"`
			}
			if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
				w.WriteHeader(http.StatusBadRequest)
				return
			}
			if len(body.Data) == 0 { // brain_facts.go: empty data → 400
				w.WriteHeader(http.StatusBadRequest)
				return
			}
			newRef, err := fake.Advance(ctx, "repo", body.Branch, body.OldRef, body.Data)
			switch {
			case err == ErrNoChange:
				cur, _, _, _ := fake.Current(ctx, "repo", body.Branch)
				_ = json.NewEncoder(w).Encode(map[string]any{"new_ref": cur, "version": 1, "unchanged": true})
			case err == ErrConflict:
				w.WriteHeader(http.StatusConflict)
			case err != nil:
				w.WriteHeader(http.StatusBadRequest)
			default:
				_ = json.NewEncoder(w).Encode(map[string]any{"new_ref": newRef, "version": 1})
			}

		default:
			w.WriteHeader(http.StatusNotFound)
		}
	}))
}

// TestHTTPServerContract exercises the adapter's every status→sentinel mapping over a real
// HTTP round-trip: empty-head read, create, read-back, no-op (unchanged→ErrNoChange), and
// stale-old-ref (409→ErrConflict).
func TestHTTPServerContract(t *testing.T) {
	ctx := context.Background()
	ts := contractServer(t, &fakeServer{})
	defer ts.Close()
	h := &HTTPServer{BaseURL: ts.URL, Token: "test-token"}

	// Empty head.
	if ref, blob, found, err := h.Current(ctx, "repo", "main"); err != nil || found || ref != "" || blob != nil {
		t.Fatalf("Current(empty) = %q,%v,%v,%v", ref, blob, found, err)
	}
	// Create.
	ref1, err := h.Advance(ctx, "repo", "main", "", []byte("fact:a\n"))
	if err != nil || ref1 != contentRef([]byte("fact:a\n")) {
		t.Fatalf("Advance(create) = %q, %v", ref1, err)
	}
	// Read back the decrypted blob + ref over the wire (base64 round-trip).
	ref, blob, found, err := h.Current(ctx, "repo", "main")
	if err != nil || !found || ref != ref1 || string(blob) != "fact:a\n" {
		t.Fatalf("Current(after create) = %q,%q,%v,%v", ref, blob, found, err)
	}
	// No-op (identical content, current ref) → ErrNoChange.
	if _, err := h.Advance(ctx, "repo", "main", ref1, []byte("fact:a\n")); err != ErrNoChange {
		t.Fatalf("Advance(no-op) = %v; want ErrNoChange", err)
	}
	// Stale old_ref → ErrConflict.
	if _, err := h.Advance(ctx, "repo", "main", "facts-stale", []byte("fact:a\nfact:b\n")); err != ErrConflict {
		t.Fatalf("Advance(stale) = %v; want ErrConflict", err)
	}
}

// TestHTTPServerConvergenceOverWire runs the whole read-merge-CAS loop for TWO members
// through the real HTTPServer adapter over HTTP — proving the runner (Sync + factmerge)
// converges against the actual wire contract, not just the in-process fake.
func TestHTTPServerConvergenceOverWire(t *testing.T) {
	ctx := context.Background()
	ts := contractServer(t, &fakeServer{})
	defer ts.Close()
	h := &HTTPServer{BaseURL: ts.URL, Token: "tok"}
	now := time.Date(2026, 7, 7, 0, 0, 0, 0, time.UTC)

	a := []factmerge.Record{fact("uses postgres", []string{"data.store.engine"}, "sess-A", now)}
	b := []factmerge.Record{fact("deploys via argo", []string{"ops.deploy.tool"}, "sess-B", now)}

	var wg sync.WaitGroup
	errs := make([]error, 2)
	wg.Add(2)
	go func() { defer wg.Done(); _, errs[0] = Sync(ctx, h, "repo", "main", "member-A", a, now) }()
	go func() { defer wg.Done(); _, errs[1] = Sync(ctx, h, "repo", "main", "member-B", b, now) }()
	wg.Wait()
	for i, err := range errs {
		if err != nil {
			t.Fatalf("member %d sync over HTTP: %v", i, err)
		}
	}

	_, blob, found, err := h.Current(ctx, "repo", "main")
	if err != nil || !found {
		t.Fatalf("Current after wire convergence: found=%v err=%v", found, err)
	}
	recs, err := factmerge.ParseNDJSON(strings.NewReader(string(blob)))
	if err != nil {
		t.Fatal(err)
	}
	texts := map[string]bool{}
	for _, r := range recs {
		texts[r.Text] = true
	}
	if !texts["uses postgres"] || !texts["deploys via argo"] || len(recs) != 2 {
		t.Fatalf("converged-over-HTTP set = %v; want both members' facts", recs)
	}
}

