// Package brainquery is the server-side read/query engine over a repo's hosted
// durable fact-set — the plaintext NDJSON a FactSetStore.Current returns (P1.M2).
// It backs the remote MCP tools (P1.M3): parse the fact-set once, then serve
// lexical search and id lookups against it.
//
// It reimplements a deliberately SMALL, self-contained view of a fact record and a
// faithful-enough lexical (token-overlap) search — entire-api cannot import the
// cgo/SQLite-heavy brain, and the semantic/vector tools (which need the regenerable
// index the hosted store does not keep) are out of scope here. Exact ranking parity
// with the local brain is a later refinement; the contract this guarantees is:
// active facts only, deterministic ordering, no panics on malformed input.
package brainquery

import (
	"bufio"
	"bytes"
	"encoding/json"
	"sort"
	"strings"
)

// StatusActive is the only fact status served: superseded/retracted facts are
// history, never returned by search or get. Mirrors the brain's status vocabulary.
const StatusActive = "active"

// Fact is the minimal projection of a durable fact the query engine needs. It is a
// tolerant subset of the brain's on-disk record (unknown fields are ignored), so the
// wire format stays owned by the brain and this never has to track every field.
type Fact struct {
	ID     string   `json:"id"`
	Paths  []string `json:"paths"`
	Kind   string   `json:"kind"`
	Text   string   `json:"text"`
	Status string   `json:"status"`
}

// Result is one ranked search hit: the fact plus its overlap score (higher = better).
type Result struct {
	Fact  Fact `json:"fact"`
	Score int  `json:"score"`
}

// Parse reads a fact-set NDJSON blob into facts. Blank lines are skipped; a malformed
// line is skipped (not fatal) so one corrupt record never denies the whole query —
// the store already guarantees integrity, and a reader that fails closed on a single
// bad line would make the brain unqueryable on any partial corruption.
func Parse(ndjson []byte) []Fact {
	if len(ndjson) == 0 {
		return nil
	}
	var out []Fact
	sc := bufio.NewScanner(bytes.NewReader(ndjson))
	sc.Buffer(make([]byte, 0, 64*1024), 16*1024*1024)
	for sc.Scan() {
		line := bytes.TrimSpace(sc.Bytes())
		if len(line) == 0 {
			continue
		}
		var f Fact
		if err := json.Unmarshal(line, &f); err != nil {
			continue // skip a malformed record rather than fail the whole read
		}
		if f.ID == "" {
			continue
		}
		out = append(out, f)
	}
	return out
}

// Get returns the ACTIVE fact with the given id. found is false for an unknown id or
// a non-active (superseded/retracted) fact — a lookup never resurrects history.
func Get(facts []Fact, id string) (Fact, bool) {
	id = strings.TrimSpace(id)
	if id == "" {
		return Fact{}, false
	}
	for _, f := range facts {
		if f.ID == id && f.Status == StatusActive {
			return f, true
		}
	}
	return Fact{}, false
}

// Search ranks ACTIVE facts by lexical token overlap with the query and returns the
// top `limit` (limit <= 0 → a default of 20). Scoring counts DISTINCT query tokens
// that appear in the fact's text or paths; ties break by fact id for a deterministic
// order. Facts with zero overlap are omitted. An empty query returns nil.
func Search(facts []Fact, query string, limit int) []Result {
	qtokens := tokenSet(query)
	if len(qtokens) == 0 {
		return nil
	}
	if limit <= 0 {
		limit = 20
	}
	var results []Result
	for _, f := range facts {
		if f.Status != StatusActive {
			continue
		}
		hay := tokenSet(f.Text + " " + strings.Join(f.Paths, " "))
		score := 0
		for tok := range qtokens {
			if _, ok := hay[tok]; ok {
				score++
			}
		}
		if score > 0 {
			results = append(results, Result{Fact: f, Score: score})
		}
	}
	sort.SliceStable(results, func(i, j int) bool {
		if results[i].Score != results[j].Score {
			return results[i].Score > results[j].Score // higher score first
		}
		return results[i].Fact.ID < results[j].Fact.ID // deterministic tie-break
	})
	if len(results) > limit {
		results = results[:limit]
	}
	return results
}

// Count reports active/superseded/retracted totals over the fact-set (for brain_status).
func Count(facts []Fact) (active, superseded, retracted, total int) {
	for _, f := range facts {
		total++
		switch f.Status {
		case StatusActive:
			active++
		case "superseded":
			superseded++
		case "retracted":
			retracted++
		}
	}
	return active, superseded, retracted, total
}

// tokenSet lowercases, splits on non-alphanumeric runs, and returns the DISTINCT
// tokens (length >= 2 to drop noise). A set, so a repeated query word counts once.
func tokenSet(s string) map[string]struct{} {
	out := map[string]struct{}{}
	for _, tok := range strings.FieldsFunc(strings.ToLower(s), func(r rune) bool {
		return !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9')
	}) {
		if len(tok) >= 2 {
			out[tok] = struct{}{}
		}
	}
	return out
}

package brainquery

import (
	"strings"
	"testing"
)

const sampleNDJSON = `{"id":"fact:a","paths":["build.tooling.bazel"],"kind":"convention","text":"the build uses bazel with remote cache","status":"active"}
{"id":"fact:b","paths":["api.config.timeout"],"kind":"invariant","text":"api requests time out after 30 seconds","status":"active"}
{"id":"fact:c","paths":["build.tooling.old"],"kind":"convention","text":"the build previously used make","status":"superseded"}

{"id":"fact:d","paths":["ops.deploy.strategy"],"kind":"decision","text":"deploys use blue green cutover","status":"active"}
`

func TestParseSkipsBlankAndMalformed(t *testing.T) {
	facts := Parse([]byte(sampleNDJSON + "not json at all\n{}\n"))
	// 4 well-formed records with ids; the blank line, the non-JSON line, and the id-less
	// {} are all skipped.
	if len(facts) != 4 {
		t.Fatalf("Parse = %d facts; want 4 (blank/malformed/id-less skipped)", len(facts))
	}
	if Parse(nil) != nil || Parse([]byte("")) != nil {
		t.Fatal("Parse(empty) should be nil")
	}
}

func TestGetActiveOnly(t *testing.T) {
	facts := Parse([]byte(sampleNDJSON))
	if f, ok := Get(facts, "fact:a"); !ok || f.Text == "" {
		t.Fatalf("Get(fact:a) = %+v, %v; want the active fact", f, ok)
	}
	// Superseded fact is history — never returned.
	if _, ok := Get(facts, "fact:c"); ok {
		t.Fatal("Get(fact:c) returned a superseded fact; want not found")
	}
	if _, ok := Get(facts, "fact:missing"); ok {
		t.Fatal("Get(missing) should be not found")
	}
	if _, ok := Get(facts, "  "); ok {
		t.Fatal("Get(blank) should be not found")
	}
}

func TestSearchRanksAndFiltersSuperseded(t *testing.T) {
	facts := Parse([]byte(sampleNDJSON))

	// "build bazel" overlaps fact:a strongly; fact:c ("build ... make") is superseded so
	// must NOT appear even though it shares "build".
	res := Search(facts, "build bazel tooling", 10)
	if len(res) == 0 || res[0].Fact.ID != "fact:a" {
		t.Fatalf("Search(build bazel) top = %+v; want fact:a first", res)
	}
	for _, r := range res {
		if r.Fact.ID == "fact:c" {
			t.Fatal("search returned a superseded fact")
		}
	}

	// Higher overlap ranks first: query hitting both text and path of fact:a.
	if res[0].Score < 1 {
		t.Fatalf("top score = %d; want >= 1", res[0].Score)
	}

	// No-overlap query → no results; empty query → nil.
	if got := Search(facts, "quantum zebra", 10); len(got) != 0 {
		t.Fatalf("Search(no overlap) = %v; want empty", got)
	}
	if got := Search(facts, "   ", 10); got != nil {
		t.Fatalf("Search(blank) = %v; want nil", got)
	}
}

func TestSearchLimitAndDeterministicOrder(t *testing.T) {
	// Two facts with identical score must order by id, stably, and honor the limit.
	nd := `{"id":"fact:z","paths":["x.y.z"],"text":"alpha beta","status":"active"}
{"id":"fact:a","paths":["x.y.z"],"text":"alpha beta","status":"active"}
{"id":"fact:m","paths":["x.y.z"],"text":"alpha beta","status":"active"}`
	facts := Parse([]byte(nd))
	res := Search(facts, "alpha beta", 2)
	if len(res) != 2 {
		t.Fatalf("limit not honored: got %d, want 2", len(res))
	}
	if res[0].Fact.ID != "fact:a" || res[1].Fact.ID != "fact:m" {
		t.Fatalf("tie-break order = %s,%s; want fact:a,fact:m (by id)", res[0].Fact.ID, res[1].Fact.ID)
	}
}

func TestCount(t *testing.T) {
	facts := Parse([]byte(sampleNDJSON))
	active, superseded, retracted, total := Count(facts)
	if active != 3 || superseded != 1 || retracted != 0 || total != 4 {
		t.Fatalf("Count = %d/%d/%d/%d; want 3/1/0/4", active, superseded, retracted, total)
	}
}

func TestSearchLongLineWithinBuffer(t *testing.T) {
	// A large fact text must parse (scanner buffer is raised to 16MiB).
	big := strings.Repeat("word ", 200000) // ~1MB line
	nd := `{"id":"fact:big","paths":["a.b.c"],"text":"` + big + `","status":"active"}`
	facts := Parse([]byte(nd))
	if len(facts) != 1 {
		t.Fatalf("big line not parsed: %d facts", len(facts))
	}
}

