package httpapi

import (
	"context"
	"encoding/json"
	"net/http"

	"github.com/danielgtaylor/huma/v2"

	"github.com/entirehq/entire-api/internal/brainquery"
)

// The remote MCP transport for the hosted brain (P1.M3). Where the local brain speaks
// MCP over stdio (entire-brain/internal/cli/mcp.go), this exposes the SAME JSON-RPC 2.0
// surface over an authed HTTP POST so a team member's agent can query the SHARED brain
// remotely:
//
//	POST …/repos/{repo_id}/brain/mcp  — one JSON-RPC message per request (pull-gated).
//
// ADR-P1-H: JSON-RPC-over-HTTP (not SSE/streamable) — minimal and fully testable; huma
// owns the HTTP frame, so the stdio framing layer is dropped and only the dispatch
// (initialize / tools/list / tools/call) is lifted. ADR-P1-I: the remote tool surface is
// a curated READ-ONLY facts subset served straight from the M2 fact-set head via the
// brainquery engine; semantic/graph tools (which need the regenerable index the hosted
// store does not keep) are out of scope. Repo scope + auth reuse M1/M2 wholesale
// (requireAuth + requireRepoAccess pull); the repo is the boundary, the caller identity
// the member boundary.
//
// The MCP protocol version this server advertises when the client does not pin one.
const mcpProtocolVersion = "2024-11-05"

// maxBrainMCPBytes caps a single JSON-RPC request body. MCP messages are small (a tool
// call is a name + a few args); the generous artifact cap does not apply.
const maxBrainMCPBytes = 1 << 20 // 1 MiB

// BrainMCPInput is POST /repos/{repo_id}/brain/mcp — one JSON-RPC 2.0 request. ID is
// kept raw (a JSON-RPC id may be a string, number, or null) and echoed verbatim.
type BrainMCPInput struct {
	RepoID string `path:"repo_id"`
	Body   struct {
		JSONRPC string          `json:"jsonrpc"`
		ID      json.RawMessage `json:"id,omitempty"`
		Method  string          `json:"method"`
		Params  json.RawMessage `json:"params,omitempty"`
	}
}

// BrainMCPOutput carries the JSON-RPC 2.0 response as the whole body.
type BrainMCPOutput struct {
	Body mcpResponse
}

type mcpResponse struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      json.RawMessage `json:"id,omitempty"`
	Result  any             `json:"result,omitempty"`
	Error   *mcpError       `json:"error,omitempty"`
}

type mcpError struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
}

// JSON-RPC / MCP error codes (mirroring the local brain's mcp.go).
const (
	mcpErrMethodNotFound = -32601 // unknown JSON-RPC method
	mcpErrToolFailure    = -32000 // a tools/call that failed to execute
)

// brainMCP dispatches one JSON-RPC message. A nil fact-set store (hosted brain not
// configured) is 503, like the other brain endpoints. Transport/dispatch errors are
// JSON-RPC errors in a 200 body (the JSON-RPC convention), NOT HTTP errors — only auth
// (middleware) and "not configured" surface as HTTP status.
func brainMCP(ctx context.Context, deps *RepoActivityDeps, in *BrainMCPInput) (*BrainMCPOutput, error) {
	if deps.Facts == nil {
		return nil, huma.Error503ServiceUnavailable("hosted brain not configured")
	}
	resp := mcpResponse{JSONRPC: "2.0", ID: in.Body.ID}
	switch in.Body.Method {
	case "initialize":
		resp.Result = map[string]any{
			"protocolVersion": mcpInitProtocolVersion(in.Body.Params),
			"capabilities":    map[string]any{"tools": map[string]any{}},
			"serverInfo":      map[string]any{"name": "entire-brain-hosted", "version": "0.1.0"},
		}
	case "tools/list":
		resp.Result = map[string]any{"tools": hostedToolDefinitions()}
	case "tools/call":
		result, callErr := callHostedTool(ctx, deps, in.RepoID, in.Body.Params)
		if callErr != nil {
			resp.Error = callErr
		} else {
			resp.Result = result
		}
	default:
		resp.Error = &mcpError{Code: mcpErrMethodNotFound, Message: "method not found: " + in.Body.Method}
	}
	out := &BrainMCPOutput{}
	out.Body = resp
	return out, nil
}

// mcpInitProtocolVersion echoes the client's requested protocol version, or advertises
// the server default when the client did not pin one — mirroring the local brain.
func mcpInitProtocolVersion(raw json.RawMessage) string {
	if len(raw) == 0 {
		return mcpProtocolVersion
	}
	var p struct {
		ProtocolVersion string `json:"protocolVersion"`
	}
	if json.Unmarshal(raw, &p) == nil && p.ProtocolVersion != "" {
		return p.ProtocolVersion
	}
	return mcpProtocolVersion
}

// hostedToolDefinitions is the curated remote tool surface (ADR-P1-I). M3.1 exposes
// brain_search; M3.2 adds get / multi_get / status.
func hostedToolDefinitions() []map[string]any {
	return []map[string]any{
		{
			"name":        "brain_search",
			"description": "Lexical search over the shared team fact-set: returns active durable facts ranked by token overlap with the query.",
			"inputSchema": map[string]any{
				"type": "object",
				"properties": map[string]any{
					"query":  map[string]any{"type": "string", "description": "Keyword query"},
					"limit":  map[string]any{"type": "integer", "description": "Max results (default 20)", "minimum": 1},
					"branch": map[string]any{"type": "string", "description": "Branch fact-set to search (default: main)"},
				},
				"required":             []string{"query"},
				"additionalProperties": false,
			},
		},
	}
}

// mcpToolCallParams is the tools/call params envelope.
type mcpToolCallParams struct {
	Name      string `json:"name"`
	Arguments struct {
		Query  string `json:"query"`
		ID     string `json:"id"`
		IDs    []string `json:"ids"`
		Limit  int    `json:"limit"`
		Branch string `json:"branch"`
	} `json:"arguments"`
}

// callHostedTool runs a curated read tool against the repo's hosted fact-set. It returns
// an MCP result (content blocks) or a JSON-RPC error. Auth/repo-scope were enforced by
// the middleware; here we only resolve the branch fact-set and run the query.
func callHostedTool(ctx context.Context, deps *RepoActivityDeps, repoID string, rawParams json.RawMessage) (any, *mcpError) {
	var params mcpToolCallParams
	if len(rawParams) > 0 {
		if err := json.Unmarshal(rawParams, &params); err != nil {
			return nil, &mcpError{Code: mcpErrToolFailure, Message: "invalid tool params: " + err.Error()}
		}
	}
	branch := params.Arguments.Branch
	if branch == "" {
		branch = "main"
	}

	switch params.Name {
	case "brain_search":
		if params.Arguments.Query == "" {
			return nil, &mcpError{Code: mcpErrToolFailure, Message: "query is required"}
		}
		facts, mcpErr := hostedFacts(ctx, deps, repoID, branch)
		if mcpErr != nil {
			return nil, mcpErr
		}
		results := brainquery.Search(facts, params.Arguments.Query, params.Arguments.Limit)
		return mcpTextResult(results), nil
	default:
		return nil, &mcpError{Code: mcpErrToolFailure, Message: "unknown tool: " + params.Name}
	}
}

// hostedFacts reads + parses the branch's fact-set head. A missing head (no facts yet)
// is an empty slice, not an error; a store error (e.g. unresolved repo) is a tool error.
func hostedFacts(ctx context.Context, deps *RepoActivityDeps, repoID, branch string) ([]brainquery.Fact, *mcpError) {
	_, _, plaintext, found, err := deps.Facts.Current(ctx, repoID, branch)
	if err != nil {
		return nil, &mcpError{Code: mcpErrToolFailure, Message: "read fact-set: " + err.Error()}
	}
	if !found {
		return nil, nil
	}
	return brainquery.Parse(plaintext), nil
}

// mcpTextResult wraps a value as an MCP tools/call result: a single text content block
// carrying the JSON-encoded payload (the shape the local brain's tools return).
func mcpTextResult(payload any) map[string]any {
	b, err := json.Marshal(payload)
	if err != nil {
		b = []byte(`{"error":"failed to encode result"}`)
	}
	return map[string]any{
		"content": []map[string]any{{"type": "text", "text": string(b)}},
	}
}

// registerBrainMCP mounts the remote MCP endpoint, pull-gated (querying shared memory is
// a read), mirroring registerBrainFacts' readGate.
func registerBrainMCP(api huma.API, deps *RepoActivityDeps) {
	gate := []opMiddleware{requireAuth(api, deps.Authenticator), requireRepoAccess(api, deps)}
	op := teamOp("repoBrainMCP", http.MethodPost, "/repos/{repo_id}/brain/mcp",
		"Query the shared brain over MCP (JSON-RPC 2.0; requires repo pull access)", gate)
	op.MaxBodyBytes = maxBrainMCPBytes
	huma.Register(api, op, func(ctx context.Context, in *BrainMCPInput) (*BrainMCPOutput, error) {
		return brainMCP(ctx, deps, in)
	})
}

