// MultiGet returns the ACTIVE facts for the given ids (in the input id order, dups
// collapsed) plus the ids that were not found (unknown or non-active). It is the
// batch form of Get — a lookup never resurrects superseded/retracted history.
func MultiGet(facts []Fact, ids []string) (found []Fact, missing []string) {
	seen := map[string]bool{}
	for _, id := range ids {
		id = strings.TrimSpace(id)
		if id == "" || seen[id] {
			continue
		}
		seen[id] = true
		if f, ok := Get(facts, id); ok {
			found = append(found, f)
		} else {
			missing = append(missing, id)
		}
	}
	return found, missing
}

