package httpapi

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// P1.M4 — the multi-tenant isolation matrix. The hosted brain's tenant boundary is the
// repo: every brain surface (publish / facts read + advance / mcp) gates on the {repo_id}
// path param via requireAuth + requireRepoAccess|requireRepoPush → SpiceDB
// HasPermission("repo", id, pull|push), with the subject always the verified JWT Identity
// (never request input). This test proves the boundary systematically across ALL surfaces:
// a member of one repo cannot reach another's brain, an unauthenticated caller cannot
// reach any, and read access never confers write. These are DENY paths that short-circuit
// at the permission check BEFORE the repo-existence lookup, so no Postgres is needed.

// brainSurface is one gated brain entrypoint.
type brainSurface struct {
	name      string
	method    string
	path      string // under /api/v1/repos/{repo_id}
	body      string // minimal valid-ish body (unused by GET)
	write     bool   // true = push-gated (publish, advance); false = pull-gated (read, mcp)
}

func brainSurfaces(repoID string) []brainSurface {
	base := "/api/v1/repos/" + repoID + "/brain"
	return []brainSurface{
		{"publish", http.MethodPost, base + "/artifacts", `{"artifacts":[]}`, true},
		{"facts-current", http.MethodGet, base + "/facts?branch=main", "", false},
		{"facts-advance", http.MethodPost, base + "/facts/advance", `{"branch":"main","old_ref":"","data":"eA=="}`, true},
		{"mcp", http.MethodPost, base + "/mcp", `{"jsonrpc":"2.0","id":1,"method":"initialize"}`, false},
	}
}

// isolationRouter builds a real activity router whose SpiceDB double grants exactly the
// given pull/push repo sets. Brain deps are wired to a Mem fact-set store so a request
// that DID reach a handler would 200/404 rather than spuriously 503 — but every case
// here denies at the authz gate first.
func isolationRouter(t *testing.T, authnMint func() (auth Authenticatorish, mint func(string) string), pull, push []string) (*Router, func(string) string) {
	t.Helper()
	authn, mint := jwksAuth(t)
	base := baseDeps{Authenticator: authn, Reader: fakeReaderRW(pull, push, nil, false)}
	repoDeps := &RepoActivityDeps{baseDeps: base, Facts: newFactsTest().Facts}
	userDeps := &UserActivityDeps{baseDeps: base, Store: fakeUserReader{}}
	return NewActivityAPIRouter(repoDeps, userDeps), mint
}

// Authenticatorish is a tiny alias so the helper signature reads clearly; jwksAuth returns
// the concrete Authenticator which satisfies whatever the router needs.
type Authenticatorish = any

func do(t *testing.T, r *Router, s brainSurface, token string) int {
	t.Helper()
	var bodyR *strings.Reader
	if s.body != "" {
		bodyR = strings.NewReader(s.body)
	} else {
		bodyR = strings.NewReader("")
	}
	req := httptest.NewRequest(s.method, s.path, bodyR)
	req.Header.Set("Content-Type", "application/json")
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	w := httptest.NewRecorder()
	r.HTTPHandler().ServeHTTP(w, req)
	return w.Code
}

func TestBrainTenantIsolationMatrix(t *testing.T) {
	repoX := routeULID("tenant-X")
	repoY := routeULID("tenant-Y")

	// A member of repo X (full pull+push on X, nothing on Y).
	rX, mintX := isolationRouter(t, nil, []string{repoX}, []string{repoX})
	tokenX := mintX("member-of-X")

	// 1. CROSS-TENANT: X's member hitting Y's brain is 403 on EVERY surface (denied at the
	//    repo permission check — Y is in neither set).
	for _, s := range brainSurfaces(repoY) {
		if got := do(t, rX, s, tokenX); got != http.StatusForbidden {
			t.Fatalf("cross-tenant %s on Y as X-member = %d; want 403", s.name, got)
		}
	}

	// 2. UNAUTHENTICATED: no token is 401 on every surface.
	for _, s := range brainSurfaces(repoY) {
		if got := do(t, rX, s, ""); got != http.StatusUnauthorized {
			t.Fatalf("no-token %s = %d; want 401", s.name, got)
		}
	}

	// 3. READ ≠ WRITE: a caller with PULL on Y but no PUSH is 403 on every WRITE surface
	//    (publish, advance) — read access never confers write.
	rPull, mintPull := isolationRouter(t, nil, []string{repoY}, nil)
	tokenPull := mintPull("reader-of-Y")
	for _, s := range brainSurfaces(repoY) {
		if !s.write {
			continue
		}
		if got := do(t, rPull, s, tokenPull); got != http.StatusForbidden {
			t.Fatalf("pull-only %s on Y = %d; want 403 (write needs push)", s.name, got)
		}
	}
}

