package brainbuild

import (
	"context"
	"errors"
	"testing"

	"github.com/entirehq/entire-api/internal/brainstore"
	"github.com/entirehq/entire-api/internal/snapshotcrypt/snapshotcrypttest"
)

// P1.M4 — the SECOND, independent tenant-isolation layer: slug-keyed storage. Above the
// store, the authz gate walls tenants at the {repo_id} boundary (see
// httpapi TestBrainTenantIsolationMatrix). Below it, EVEN IF the gate were bypassed, the
// FactSetStore resolves each repo ULID to its own wire-slug and keys every blob + CAS head
// under that slug — so one tenant's facts can never surface for another. This proves that
// defense-in-depth directly at the store: two repos, distinct slugs, no cross-leak, and
// fail-closed on an unresolvable repo.
func TestFactSetStoreTenantIsolation(t *testing.T) {
	ctx := context.Background()

	const (
		repoX, slugX = "01ARZ3NDEKTSV4RRFFQ69G5FAV", "gh/acme/alpha"
		repoY, slugY = "01BX5ZZKBKACTAV9WEVGEMMVRZ", "gh/beta/omega"
	)
	inner := brainstore.NewMemStore()
	enc := brainstore.NewEncryptingStore(inner, snapshotcrypttest.NewCipher(), brainstore.NewMemDEKStore())
	resolver := fakeResolver{m: map[string]string{repoX: slugX, repoY: slugY}}
	store := NewFactSetStore(enc, NewMemFactRefIndex(), resolver)

	// Tenant X publishes a fact-set on main.
	xBlob := []byte("fact:x-secret\n")
	if _, _, err := store.Advance(ctx, repoX, "main", "", xBlob); err != nil {
		t.Fatalf("X advance: %v", err)
	}

	// Tenant Y reads main → NOT FOUND. X's facts are keyed under slugX; Y resolves to slugY
	// and sees nothing. No cross-tenant leak.
	if ref, _, pt, found, err := store.Current(ctx, repoY, "main"); err != nil || found || pt != nil || ref != "" {
		t.Fatalf("Y Current after X advance = %q,%q,%v,%v; want empty (isolated)", ref, pt, found, err)
	}

	// X reads its own main → present (sanity: isolation didn't break X's own access).
	if _, _, pt, found, err := store.Current(ctx, repoX, "main"); err != nil || !found || string(pt) != string(xBlob) {
		t.Fatalf("X Current = %q,%v,%v; want its own facts", pt, found, err)
	}

	// Y publishes ITS OWN facts on main; X must not see Y's, Y must not see X's.
	yBlob := []byte("fact:y-secret\n")
	if _, _, err := store.Advance(ctx, repoY, "main", "", yBlob); err != nil {
		t.Fatalf("Y advance: %v", err)
	}
	if _, _, pt, _, _ := store.Current(ctx, repoX, "main"); string(pt) != string(xBlob) {
		t.Fatalf("X's fact-set changed after Y advance: %q", pt)
	}
	if _, _, pt, _, _ := store.Current(ctx, repoY, "main"); string(pt) != string(yBlob) {
		t.Fatalf("Y's fact-set = %q; want its own", pt)
	}

	// FAIL-CLOSED: an unknown repo id resolves to no slug → ErrUnresolvedRepo, never a read
	// or write under a raw ULID or a wrong tenant.
	if _, _, _, _, err := store.Current(ctx, "01CUNKNOWNULID00000000000", "main"); !errors.Is(err, ErrUnresolvedRepo) {
		t.Fatalf("unresolved repo Current = %v; want ErrUnresolvedRepo", err)
	}
	if _, _, err := store.Advance(ctx, "01CUNKNOWNULID00000000000", "main", "", []byte("x")); !errors.Is(err, ErrUnresolvedRepo) {
		t.Fatalf("unresolved repo Advance = %v; want ErrUnresolvedRepo", err)
	}
}

