// manifest — is stored at BrainKey{RepoKey: slug, Kind, Ref}, so an artifact one tenant
// publishes under its slug is unreachable under another tenant's slug even at the same
// Kind+Ref. This is the store layer beneath the publish endpoint (which the end-to-end
// MCP test does not exercise); the keying mechanism is identical across all surfaces.
func TestBrainStoreCrossSlugArtifactIsolation(t *testing.T) {
	ctx := context.Background()
	const (
		slugX = "gh/acme/alpha"
		slugY = "gh/beta/omega"
		ref   = "abc123" // same logical ref under both tenants — only the slug differs
	)
	inner := brainstore.NewMemStore()
	enc := brainstore.NewEncryptingStore(inner, snapshotcrypttest.NewCipher(), brainstore.NewMemDEKStore())

	// Every publishable kind, stored under tenant X's slug.
	for _, kind := range []string{brainstore.KindSnapshot, brainstore.KindOverlay, brainstore.KindFacts, brainstore.KindManifest} {
		payload := []byte("X-" + kind + "-secret")
		if err := enc.Put(ctx, brainstore.BrainKey{RepoKey: slugX, Kind: kind, Ref: ref}, payload); err != nil {
			t.Fatalf("Put X %s: %v", kind, err)
		}
		// Same Kind+Ref under tenant Y's slug → NOT FOUND (distinct key namespace).
		if _, err := enc.Get(ctx, brainstore.BrainKey{RepoKey: slugY, Kind: kind, Ref: ref}); !errors.Is(err, brainstore.ErrNotFound) {
			t.Fatalf("Y Get %s under X's ref = %v; want ErrNotFound (cross-tenant isolation)", kind, err)
		}
		// X reads its own artifact back (isolation didn't break same-tenant access).
		if got, err := enc.Get(ctx, brainstore.BrainKey{RepoKey: slugX, Kind: kind, Ref: ref}); err != nil || string(got) != string(payload) {
			t.Fatalf("X Get %s = %q,%v; want its own payload", kind, got, err)
		}
	}
}

