// mapping, then renders the slug byte-identically to the client's manifest repo_key
// (see wireRepoPath). It satisfies httpapi.RepoSlugResolver.
type brainSlugResolver struct {
	store *store.RepoStore
}

// Resolve returns the wire slug for repoID, or "" when the repo is unknown here or
// has no observed full name (the publish handler turns "" into a 404 and stores
// nothing).
func (r *brainSlugResolver) Resolve(ctx context.Context, repoID string) (string, error) {
	meta, ok, err := r.store.GetRepoMeta(ctx, repoID)
	if err != nil {
		return "", err
	}
	if !ok || meta.FullName == "" {
		return "", nil
	}
	path := wireRepoPath(meta.FullName)
	if path == "" {
		return "", nil
	}
	return "gh/" + path, nil
}

// nonSlugChars matches any run of characters outside the safe repo-path alphabet.
// It mirrors entire-brain's safeRepoPathComponent so the slug this server derives
// is byte-identical to the client's manifest repo_key.
var nonSlugChars = regexp.MustCompile(`[^a-zA-Z0-9._-]+`)

// safeRepoPathComponent normalizes ONE "/"-component of a repo path exactly as the
// client does: lowercase → collapse any unsafe run to a single '-' → trim leading/
// trailing '-', '.', '_'. So ".github" → "github" and "My Repo!" → "my-repo".
func safeRepoPathComponent(s string) string {
	s = strings.ToLower(s)
	s = nonSlugChars.ReplaceAllString(s, "-")
	return strings.Trim(s, "-._")
}

// wireRepoPath renders "owner/repo" (the stored full_name) into the wire path by
// normalizing EACH slash-separated component with safeRepoPathComponent and
// rejoining. The caller prepends the "gh/" host prefix; e.g. "acme/.github" →
// "acme/github" → (with prefix) "gh/acme/github".
func wireRepoPath(fullName string) string {
	parts := strings.Split(fullName, "/")
	for i, p := range parts {
		parts[i] = safeRepoPathComponent(p)
	}
	return strings.Join(parts, "/")
}

// buildBrainPublisher wires the brain publish dependency, mirroring snapshot.New:
...
// fact-ref index + the same ULID→slug resolver) on top.
//
// Fail-closed identically to buildBrainPublisher:
//   - cipher != aws → log + (nil, nil). Both fact endpoints 503; startup continues.
//     Shared team memory must NEVER be sealed under the local (reproducible-key) dev
//     cipher or persisted with a volatile DEK store.
//   - cipher == aws but bucket or KMS key unset → an error that ABORTS startup.
//
// It mirrors buildBrainPublisher's aws-resource composition minimally rather than
// sharing a single EncryptingStore instance: EncryptingStore is stateless over its
// (S3, cipher, DEK-store) deps, so a second instance over the SAME bucket/cipher/DEK
// store is behaviorally identical, and this keeps the M1 publish wiring untouched.
func buildFactSetStore(ctx context.Context, cfg config.Snapshot, repoStore *store.RepoStore, log *slog.Logger) (*brainbuild.FactSetStore, error) {
	if cfg.Cipher != snapshot.CipherAWS {
		log.Warn("brain: fact sync disabled (ENTIRE_SNAPSHOT_CIPHER != aws); GET/POST /repos/{repo_id}/brain/facts return 503",
			slog.String("cipher", cfg.Cipher))
		return nil, nil
	}
	if cfg.Bucket == "" || cfg.KMSKeyARN == "" {
		return nil, fmt.Errorf("brain: cipher=aws requires ENTIRE_SNAPSHOT_BUCKET and ENTIRE_SNAPSHOT_KMS_KEY_ARN")
	}
	awsCfg, err := awsconfig.LoadDefaultConfig(ctx)
	if err != nil {
		return nil, fmt.Errorf("brain: load aws config: %w", err)
	}
	cipher := snapshotcrypt.NewAWSKMSCipher(kms.NewFromConfig(awsCfg), cfg.KMSKeyARN)
	objects := brainstore.NewS3(s3.NewFromConfig(awsCfg), cfg.Bucket)
	enc := brainstore.NewEncryptingStore(objects, cipher, durableBrainDEKStore(repoStore))
	refs := brainbuild.NewPgFactRefIndex(repoStore.Pool())
	log.Info("brain: aws fact sync configured", slog.String("bucket", cfg.Bucket))
	return brainbuild.NewFactSetStore(enc, refs, &brainSlugResolver{store: repoStore}), nil
}

