// TestFactSetStoreSameSlugDistinctReposIsolated is the regression for the slug-collision
// tenancy break: two DISTINCT repos (different ULIDs, different ACLs) whose lossy wire
// slugs COLLIDE — e.g. acme/.github and acme/github both render "gh/acme/github". Because
// the storage key binds the repo ULID (RepoKeyFor), they get disjoint keyspaces: one's
// facts never surface for the other, and neither can CAS-advance the other's head.
func TestFactSetStoreSameSlugDistinctReposIsolated(t *testing.T) {
	ctx := context.Background()
	const (
		repoA = "01ARZ3NDEKTSV4RRFFQ69G5FAV" // acme/.github
		repoB = "01BX5ZZKBKACTAV9WEVGEMMVRZ" // acme/github
		slug  = "gh/acme/github"             // COLLIDING slug for both
	)
	inner := brainstore.NewMemStore()
	enc := brainstore.NewEncryptingStore(inner, snapshotcrypttest.NewCipher(), brainstore.NewMemDEKStore())
	// Both distinct repos resolve to the SAME lossy slug.
	store := NewFactSetStore(enc, NewMemFactRefIndex(), fakeResolver{m: map[string]string{repoA: slug, repoB: slug}})

	if _, _, err := store.Advance(ctx, repoA, "main", "", []byte("fact:a-secret\n")); err != nil {
		t.Fatalf("A advance: %v", err)
	}
	// B (same slug, different ULID) sees NOTHING of A's — disjoint keyspace.
	if _, _, pt, found, err := store.Current(ctx, repoB, "main"); err != nil || found || pt != nil {
		t.Fatalf("B Current = %q, found=%v, err=%v; want empty (same slug must NOT share A's keyspace)", pt, found, err)
	}
	// B's create SUCCEEDS (it's not colliding with A's head) and stays its own.
	if _, _, err := store.Advance(ctx, repoB, "main", "", []byte("fact:b-secret\n")); err != nil {
		t.Fatalf("B advance (would ErrFactRefConflict if it shared A's head): %v", err)
	}
	if _, _, pt, _, _ := store.Current(ctx, repoA, "main"); string(pt) != "fact:a-secret\n" {
		t.Fatalf("A's fact-set changed by B: %q", pt)
	}
	if _, _, pt, _, _ := store.Current(ctx, repoB, "main"); string(pt) != "fact:b-secret\n" {
		t.Fatalf("B's fact-set = %q; want its own", pt)
	}
}
