// buildBrainPublisher wires the brain publish dependency, mirroring snapshot.New:
// the SAME ENTIRE_SNAPSHOT_* cipher/bucket config, the SAME snapshotcrypt KMS
// cipher (which satisfies brainstore.Cipher), and the SAME S3 client, composed as
// EncryptingStore(S3, cipher, durable-Pg-DEK-store).
//
// Fail-closed:
//   - cipher != aws → log + return (nil, nil). The endpoint 503s; startup
//     continues. A brain must NEVER be sealed under the local (reproducible-key)
//     dev cipher or persisted with a volatile DEK store, so hosted publish is
//     simply off outside a real KMS deployment.
//   - cipher == aws but bucket or KMS key unset → return an error that ABORTS
//     startup (a misconfigured production process must not come up half-wired).
func buildBrainPublisher(ctx context.Context, cfg config.Snapshot, repoStore *store.RepoStore, log *slog.Logger) (*httpapi.BrainPublisher, error) {
	if cfg.Cipher != snapshot.CipherAWS {
		log.Warn("brain: publisher disabled (ENTIRE_SNAPSHOT_CIPHER != aws); POST /repos/{repo_id}/brain/artifacts returns 503",
			slog.String("cipher", cfg.Cipher))
		return nil, nil
	}
	if cfg.Bucket == "" || cfg.KMSKeyARN == "" {
		return nil, fmt.Errorf("brain: cipher=aws requires ENTIRE_SNAPSHOT_BUCKET and ENTIRE_SNAPSHOT_KMS_KEY_ARN")
	}
	awsCfg, err := awsconfig.LoadDefaultConfig(ctx)
	if err != nil {
		return nil, fmt.Errorf("brain: load aws config: %w", err)
	}
	cipher := snapshotcrypt.NewAWSKMSCipher(kms.NewFromConfig(awsCfg), cfg.KMSKeyARN)
	objects := brainstore.NewS3(s3.NewFromConfig(awsCfg), cfg.Bucket)
	enc := brainstore.NewEncryptingStore(objects, cipher, durableBrainDEKStore(repoStore))
	log.Info("brain: aws publisher configured", slog.String("bucket", cfg.Bucket))
	return httpapi.NewBrainPublisher(enc, &brainSlugResolver{store: repoStore}), nil
}

// durableBrainDEKStore is the production DEK store: the durable Postgres store over
// the repo store's pool. It is NEVER an in-memory store in serve — a volatile DEK
// store would crypto-shred every brain on restart (the wrapped DEK is the sole
// pointer to a ciphertext object).
func durableBrainDEKStore(repoStore *store.RepoStore) brainstore.DEKStore {
	return brainstore.NewPgDEKStore(repoStore.Pool())
}

