package brainstore

import (
	"context"
	"sync"
)

// ValidatingStore wraps a Store with an integrity + schema-validation gate. It
// carries no cipher: validation is over whatever bytes flow through (in a
// deployment this sits ABOVE the encryption layer for manifests, which are not
// secret, or is used on its own for content-addressed integrity). Two guards:
//
//   - Expect(key, digest) registers a per-key expected content digest; a
//     subsequent Put under that key must match it (fail-closed — a mismatch
//     stores nothing and returns ErrIntegrity).
//   - Every KindManifest Put runs ValidateManifest and refuses to store a
//     malformed / unsupported-major manifest; a tolerated greater-minor manifest
//     is stored (the warning is dropped on the write path — callers that want it
//     call ValidateManifest directly). Get re-validates manifests so a manifest
//     that became unreadable at rest surfaces as an error rather than bad bytes.
type ValidatingStore struct {
	inner Store

	mu       sync.Mutex
	expected map[string]string // physical key -> claimed digest
}

// NewValidatingStore wraps inner with the validation gate.
func NewValidatingStore(inner Store) *ValidatingStore {
	return &ValidatingStore{inner: inner, expected: map[string]string{}}
}

// Expect registers the digest a future Put under key must satisfy. Re-registering
// overwrites the prior expectation.
func (v *ValidatingStore) Expect(key BrainKey, digest string) {
	v.mu.Lock()
	defer v.mu.Unlock()
	v.expected[key.String()] = digest
}

// expectedDigest returns the registered digest for key, if any.
func (v *ValidatingStore) expectedDigest(key BrainKey) (string, bool) {
	v.mu.Lock()
	defer v.mu.Unlock()
	d, ok := v.expected[key.String()]
	return d, ok
}

func (v *ValidatingStore) Put(ctx context.Context, key BrainKey, data []byte) error {
	if err := key.validate(); err != nil {
		return err
	}
	// Digest gate: fail-closed before anything is stored.
	if digest, ok := v.expectedDigest(key); ok {
		if err := VerifyDigest(data, digest); err != nil {
			return err
		}
	}
	// Manifest schema gate: refuse to store a malformed / unsupported manifest.
	if key.Kind == KindManifest {
		if _, err := ValidateManifest(data); err != nil {
			return err
		}
	}
	return v.inner.Put(ctx, key, data)
}

func (v *ValidatingStore) Get(ctx context.Context, key BrainKey) ([]byte, error) {
	data, err := v.inner.Get(ctx, key)
	if err != nil {
		return nil, err
	}
	// Re-validate a manifest at read time so at-rest corruption or a version we
	// can no longer read surfaces as an error, never as trusted bytes.
	if key.Kind == KindManifest {
		if _, err := ValidateManifest(data); err != nil {
			return nil, err
		}
	}
	return data, nil
}

func (v *ValidatingStore) List(ctx context.Context, repoKey, kind string) ([]BrainKey, error) {
	return v.inner.List(ctx, repoKey, kind)
}

func (v *ValidatingStore) ListWithMeta(ctx context.Context, repoKey, kind string) ([]ObjectMeta, error) {
	return v.inner.ListWithMeta(ctx, repoKey, kind)
}

func (v *ValidatingStore) Tag(ctx context.Context, key BrainKey, tags map[string]string) error {
	return v.inner.Tag(ctx, key, tags)
}
