// GC retires the deleted branch's overlays. For each recorded ref it holds the
// coordinate lock (the SAME key a publish holds), retires the ref, and — on a
// shred — tags the versioned object. The tag is best-effort and OUTSIDE the
// RetireRef tx: the DEK is already gone (the real shred), so a tag failure only
// leaves storage cleanup to the lifecycle sweep, never leaks plaintext.
func (g *StoreOverlayGC) GC(ctx context.Context, repoID, branch string) (int, error) {
	slug, err := resolveSlug(ctx, g.resolver, repoID)
	if err != nil {
		return 0, err
	}
	refs, err := g.index.Overlays(ctx, RepoKeyFor(slug, repoID), branch)
	if err != nil {
		return 0, fmt.Errorf("brainbuild: gc list overlays %s/%s: %w", slug, branch, err)
	}
	retired := 0
	for _, ref := range refs {
		coord := brainstore.BrainKey{RepoKey: RepoKeyFor(slug, repoID), Kind: brainstore.KindOverlay, Ref: ref}
		if err := g.locker.WithLock(ctx, coord.String(), func(ctx context.Context) error {
			version, shredded, err := g.index.RetireRef(ctx, RepoKeyFor(slug, repoID), branch, ref)
			if err != nil {
				return fmt.Errorf("brainbuild: gc retire %s/%s/%s: %w", slug, branch, ref, err)
			}
			if shredded {
				// Best-effort object retirement; swallowed on error (DEK already gone).
				_ = g.objects.Tag(ctx, brainstore.RetiredObjectKey(coord, version), brainstore.UnsharedTags())
			}
			return nil
		}); err != nil {
			return retired, err
		}
		retired++
	}
	return retired, nil
}

