// brain-atlas: static view router in the spirit of atlas.partial.to
let VIEWS = [];
let GLOSSARY = {};

async function boot() {
  try {
    const data = await fetch('views.json').then(r => r.json());
    VIEWS = data.views;
    document.getElementById('source').textContent = data.meta?.source || '';
    try { GLOSSARY = await fetch('glossary.json').then(r => r.json()); } catch (_) {}
    renderNav();
    window.addEventListener('hashchange', route);
    route();
  } catch (e) {
    document.getElementById('view-intro').textContent = 'Failed to load views.json: ' + e;
  }
}

function currentId() {
  const h = location.hash.replace('#', '');
  return VIEWS.some(v => v.id === h) ? h : VIEWS[0].id;
}

function renderNav() {
  const nav = document.getElementById('nav');
  nav.innerHTML = '';
  for (const v of VIEWS) {
    const b = document.createElement('a');
    b.href = '#' + v.id;
    b.textContent = v.title;
    b.dataset.id = v.id;
    b.className = 'pill px-3.5 py-1.5 rounded-full border text-sm';
    nav.appendChild(b);
  }
}

function markNav(id) {
  document.querySelectorAll('#nav a').forEach(a => {
    const active = a.dataset.id === id;
    a.className = 'pill px-3.5 py-1.5 rounded-full border text-sm ' + (active
      ? 'bg-slate-900 text-white border-slate-900'
      : 'bg-white text-slate-700 border-slate-200 hover:border-slate-400');
  });
}

async function route() {
  const id = currentId();
  markNav(id);
  const v = VIEWS.find(x => x.id === id);
  document.getElementById('view-title').textContent = v.title;
  document.getElementById('view-intro').textContent = v.intro || '';
  const repo = document.getElementById('view-repo');
  repo.innerHTML = v.repo ? `<a class="text-blue-700 underline underline-offset-2" href="${v.repo}" target="_blank" rel="noopener">${v.repo.replace('https://', '')}</a>` : '';

  const dia = document.getElementById('diagram');
  dia.innerHTML = '<div class="text-slate-400 text-sm p-8">loading diagram…</div>';
  try {
    const svg = await fetch(`diagrams/${id}.svg`).then(r => { if (!r.ok) throw 0; return r.text(); });
    dia.innerHTML = svg; // inline so text stays selectable + crisp
  } catch (_) {
    dia.innerHTML = '<div class="text-slate-400 text-sm p-8">diagram pending</div>';
  }

  renderLegend(v);

  const content = document.getElementById('content');
  content.innerHTML = '';
  try {
    const html = await fetch(`content/${id}.html`).then(r => { if (!r.ok) throw 0; return r.text(); });
    content.innerHTML = html;
    wireGlossary(content);
  } catch (_) {}
  window.scrollTo({ top: 0 });
}

function renderLegend(v) {
  const el = document.getElementById('legend');
  const items = v.legend || [
    ['#334155', 'solid', 'live today'],
    ['#94a3b8', 'dashed', 'planned / in review'],
  ];
  el.innerHTML = items.map(([color, style, label]) =>
    `<span class="inline-flex items-center gap-2">
       <svg width="34" height="8"><line x1="1" y1="4" x2="33" y2="4" stroke="${color}" stroke-width="2" ${style === 'dashed' ? 'stroke-dasharray="5 4"' : ''}/></svg>
       <span>${label}</span></span>`).join('');
}

function wireGlossary(rootEl) {
  const terms = Object.keys(GLOSSARY);
  if (!terms.length) return;
  rootEl.querySelectorAll('code').forEach(c => {
    const t = c.textContent.trim().toLowerCase();
    if (GLOSSARY[t]) { c.title = GLOSSARY[t]; c.style.cursor = 'help'; c.style.borderBottom = '1px dotted #64748b'; }
  });
}

boot();

