const ids = ['overview','entire-sem','entire-brain','hosted','overlaps','p0','p1','p2','p3','p4','p5'];
const report = {};
const host = document.createElement('div');
host.style.cssText = 'position:absolute;left:0;top:0;width:1160px;opacity:0;pointer-events:none;';
document.body.appendChild(host);

function bb(el){ try { return el.getBBox(); } catch(e){ return null; } }
function inter(a,b,eps=1){ return !(a.x+a.width<b.x+eps||b.x+b.width<a.x+eps||a.y+a.height<b.y+eps||b.y+b.height<a.y+eps); }
function contains(a,b,pad=1){ return b.x>=a.x-pad&&b.y>=a.y-pad&&b.x+b.width<=a.x+a.width+pad&&b.y+b.height<=a.y+a.height+pad; }

for (const id of ids) {
  const txt = await fetch(`diagrams/${id}.svg?v=${Date.now()}`).then(r=>r.text());
  host.innerHTML = txt;
  const svg = host.querySelector('svg');
  const vb = svg.viewBox.baseVal;
  const probs = [];
  const texts = [...svg.querySelectorAll('text')].map(t=>({el:t,b:bb(t),s:t.textContent.slice(0,40)})).filter(t=>t.b&&t.b.width>0);
  const rects = [...svg.querySelectorAll('rect')].map(r=>({b:bb(r), pill:(+r.getAttribute('height')<=22)})).filter(r=>r.b);
  const inView = b => b.y+b.height > vb.y && b.y < vb.y+vb.height;
  // text vs text
  for (let i=0;i<texts.length;i++) for (let j=i+1;j<texts.length;j++){
    const a=texts[i], c=texts[j];
    if (!inView(a.b)||!inView(c.b)) continue;
    if (inter(a.b,c.b,2)) probs.push(`TXT/TXT "${a.s}" ~ "${c.s}" @y${Math.round(a.b.y)}`);
  }
  // text crossing a rect border (partially in, partially out)
  for (const t of texts){
    if (!inView(t.b)) continue;
    for (const r of rects){
      if (!inView(r.b)) continue;
      if (inter(t.b,r.b,2) && !contains(r.b,t.b,3) && !contains(t.b,r.b,3)) {
        probs.push(`TXT/BORDER "${t.s}" crosses rect(${Math.round(r.b.x)},${Math.round(r.b.y)},${Math.round(r.b.width)}x${Math.round(r.b.height)})`);
      }
    }
    // text clipped by viewBox right/left edge
    if (t.b.x < vb.x+2 || t.b.x+t.b.width > vb.x+vb.width-2) probs.push(`TXT/CLIP "${t.s}" x=${Math.round(t.b.x)} w=${Math.round(t.b.width)}`);
    if (t.b.y < vb.y+2 && t.b.y+t.b.height > vb.y) probs.push(`TXT/TOPCLIP "${t.s}"`);
  }
  // box-on-box overlap (non nested, ignore pills inside)
  for (let i=0;i<rects.length;i++) for (let j=i+1;j<rects.length;j++){
    const a=rects[i].b, c=rects[j].b;
    if (!inView(a)||!inView(c)) continue;
    if (inter(a,c,3) && !contains(a,c,4) && !contains(c,a,4))
      probs.push(`RECT/RECT (${Math.round(a.x)},${Math.round(a.y)} ${Math.round(a.width)}x${Math.round(a.height)}) ~ (${Math.round(c.x)},${Math.round(c.y)} ${Math.round(c.width)}x${Math.round(c.height)})`);
  }
  report[id] = probs;
}
host.remove();
JSON.stringify(report, null, 1);

