#!/usr/bin/env python3
"""Bundle brain-atlas into one self-contained HTML (no CDN, no fonts, no fetch) for Claude Artifact hosting."""
import json, pathlib, html

root = pathlib.Path(__file__).parent
views = json.loads((root / "views.json").read_text())
glossary = json.loads((root / "glossary.json").read_text())

CSS = """
:root{
  --bg:#fbfaf8; --card:#ffffff; --ink:#0f172a; --body:#334155; --sub:#475569;
  --mut:#64748b; --faint:#94a3b8; --line:#e2e8f0; --link:#1d4ed8; --accent:#2563eb;
  --pill-bg:#ffffff; --pill-ink:#334155; --pill-line:#e2e8f0; --pill-hover:#94a3b8;
  --code-bg:#f1f5f9; --callout-bg:#f8fafc;
}
@media (prefers-color-scheme: dark){:root{
  --bg:#0f141c; --card:#161d28; --ink:#e6edf6; --body:#b6c2d2; --sub:#a3b0c2;
  --mut:#8494a8; --faint:#64748b; --line:#2a3547; --link:#7ab3ff; --accent:#5b93e8;
  --pill-bg:#161d28; --pill-ink:#c4cfdd; --pill-line:#2a3547; --pill-hover:#64748b;
  --code-bg:#1d2734; --callout-bg:#141b26;
}}
:root[data-theme="light"]{
  --bg:#fbfaf8; --card:#ffffff; --ink:#0f172a; --body:#334155; --sub:#475569;
  --mut:#64748b; --faint:#94a3b8; --line:#e2e8f0; --link:#1d4ed8; --accent:#2563eb;
  --pill-bg:#ffffff; --pill-ink:#334155; --pill-line:#e2e8f0; --pill-hover:#94a3b8;
  --code-bg:#f1f5f9; --callout-bg:#f8fafc;
}
:root[data-theme="dark"]{
  --bg:#0f141c; --card:#161d28; --ink:#e6edf6; --body:#b6c2d2; --sub:#a3b0c2;
  --mut:#8494a8; --faint:#64748b; --line:#2a3547; --link:#7ab3ff; --accent:#5b93e8;
  --pill-bg:#161d28; --pill-ink:#c4cfdd; --pill-line:#2a3547; --pill-hover:#64748b;
  --code-bg:#1d2734; --callout-bg:#141b26;
}
*{box-sizing:border-box}
body{background:var(--bg); color:var(--ink); margin:0;
  font-family:'Inter',ui-sans-serif,system-ui,-apple-system,sans-serif; line-height:1.5;}
.wrap{max-width:72rem; margin:0 auto; padding:2.5rem 1.5rem;}
.font-display{font-family:'Iowan Old Style','Palatino Linotype',Palatino,Georgia,ui-serif,serif;}
.mono{font-family:ui-monospace,'SF Mono',Menlo,monospace;}
header h1{font-size:1.9rem; font-weight:600; letter-spacing:-.01em; margin:0;}
.head-row{display:flex; align-items:baseline; justify-content:space-between; flex-wrap:wrap; gap:.5rem;}
#source{font-size:.72rem; color:var(--faint);}
nav{display:flex; flex-wrap:wrap; gap:.5rem; margin-top:1rem;}
nav a{padding:.35rem .9rem; border-radius:9999px; border:1px solid var(--pill-line);
  background:var(--pill-bg); color:var(--pill-ink); font-size:.875rem; text-decoration:none;
  transition:background .12s,color .12s,border-color .12s; cursor:pointer;}
nav a:hover{border-color:var(--pill-hover);}
nav a.on{background:var(--ink); color:var(--bg); border-color:var(--ink);}
.view{display:none; margin-top:1.6rem;}
.view.on{display:block;}
.view h2{font-size:1.25rem; font-weight:600; margin:0 0 .35rem;}
.intro{font-size:.95rem; line-height:1.75; color:var(--sub); max-width:56rem; margin:.25rem 0;}
.repo{font-size:.72rem; margin:.25rem 0 0;}
.repo a{color:var(--link); text-decoration:underline; text-underline-offset:2px;}
.dia{background:#ffffff; border:1px solid var(--line); border-radius:1rem; padding:1rem;
  box-shadow:0 1px 2px rgba(15,23,42,.05); overflow-x:auto; margin-top:1.1rem;}
.dia svg{width:100%; height:auto; display:block; min-width:640px;}
.legend{display:flex; flex-wrap:wrap; gap:1.25rem; font-size:.75rem; color:var(--mut); margin-top:.6rem; align-items:center;}
.legend span{display:inline-flex; align-items:center; gap:.5rem;}
.prose{margin-top:.6rem;}
.prose h2{font-family:'Iowan Old Style','Palatino Linotype',Palatino,Georgia,ui-serif,serif;
  font-size:1.35rem; font-weight:600; color:var(--ink); margin:2rem 0 .6rem;}
.prose h3{font-size:1.02rem; font-weight:600; color:var(--ink); margin:1.4rem 0 .4rem;}
.prose p{color:var(--body); line-height:1.7; margin:.55rem 0; max-width:72ch;}
.prose ul{list-style:disc; margin:.55rem 0 .55rem 1.4rem; color:var(--body); line-height:1.65; max-width:70ch; padding:0;}
.prose li{margin:.25rem 0;}
.prose code{font-family:ui-monospace,'SF Mono',Menlo,monospace; font-size:.85em; background:var(--code-bg);
  border:1px solid var(--line); border-radius:4px; padding:.08em .35em; color:var(--ink);}
.prose table{border-collapse:collapse; margin:.8rem 0; font-size:.9rem;}
.prose th,.prose td{border:1px solid var(--line); padding:.4rem .7rem; text-align:left; color:var(--body);}
.prose th{background:var(--callout-bg); font-weight:600; color:var(--ink);}
.prose a{color:var(--link); text-decoration:underline; text-underline-offset:2px;}
.prose .callout{background:var(--callout-bg); border:1px solid var(--line); border-left:3px solid var(--accent);
  border-radius:8px; padding:.7rem 1rem; margin:.9rem 0; max-width:72ch;}
.status-done{color:#15803d}.status-built{color:#b45309}.status-pending{color:var(--mut)}
@media (prefers-color-scheme: dark){ .status-done{color:#4ade80} .status-built{color:#fbbf24} }
:root[data-theme="dark"] .status-done{color:#4ade80} :root[data-theme="dark"] .status-built{color:#fbbf24}
:root[data-theme="light"] .status-done{color:#15803d} :root[data-theme="light"] .status-built{color:#b45309}
"""

JS = """
const GLOSSARY = %GLOSSARY%;
function show(id){
  document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('on', a.dataset.id===id));
  document.querySelectorAll('.view').forEach(v=>v.classList.toggle('on', v.id==='v-'+id));
  if (location.hash !== '#'+id) history.replaceState(null,'','#'+id);
  window.scrollTo({top:0});
}
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();show(a.dataset.id);}));
document.querySelectorAll('.prose code').forEach(c=>{
  const t=c.textContent.trim().toLowerCase();
  if(GLOSSARY[t]){c.title=GLOSSARY[t];c.style.cursor='help';c.style.borderBottom='1px dotted #64748b';}
});
const first=%FIRST%;
const h=location.hash.replace('#','');
show(document.getElementById('v-'+h)?h:first);
"""

parts = []
parts.append(f"<title>entire-brain — Architecture</title>\n<style>{CSS}</style>\n")
parts.append('<div class="wrap">\n<header>\n<div class="head-row">')
parts.append('<h1 class="font-display">entire-brain — Architecture</h1>')
parts.append(f'<span id="source" class="mono">{html.escape(views["meta"]["source"])}</span></div>\n<nav>')
for v in views["views"]:
    parts.append(f'<a href="#{v["id"]}" data-id="{v["id"]}">{html.escape(v["title"])}</a>')
parts.append("</nav>\n</header>\n")

legend = ('<div class="legend">'
          '<span><svg width="34" height="8"><line x1="1" y1="4" x2="33" y2="4" stroke="#94a3b8" stroke-width="2"/></svg>live today</span>'
          '<span><svg width="34" height="8"><line x1="1" y1="4" x2="33" y2="4" stroke="#94a3b8" stroke-width="2" stroke-dasharray="5 4"/></svg>planned / in review</span>'
          '</div>')

for v in views["views"]:
    vid = v["id"]
    svg = (root / "diagrams" / f"{vid}.svg").read_text()
    content_path = root / "content" / f"{vid}.html"
    content = content_path.read_text() if content_path.exists() else ""
    repo = (f'<p class="repo mono"><a href="{v["repo"]}" target="_blank" rel="noopener">'
            f'{html.escape(v["repo"].replace("https://",""))}</a></p>') if v.get("repo") else ""
    parts.append(f'<section class="view" id="v-{vid}">\n'
                 f'<h2 class="font-display">{html.escape(v["title"])}</h2>\n'
                 f'<p class="intro">{html.escape(v.get("intro",""))}</p>\n{repo}\n'
                 f'<div class="dia">{svg}</div>\n{legend}\n'
                 f'<article class="prose">{content}</article>\n</section>\n')

parts.append("</div>\n")
js = JS.replace("%GLOSSARY%", json.dumps(glossary)).replace("%FIRST%", json.dumps(views["views"][0]["id"]))
parts.append(f"<script>{js}</script>\n")

out = root / "brain-atlas-artifact.html"
out.write_text("".join(parts))
print(f"wrote {out} ({out.stat().st_size/1024:.0f} KB)")

