export const meta = {
  name: 'audit-sem-pr22',
  description: 'Audit entire-sem PR #22 (live graph extraction gaps) across dimensions, adversarially verify findings',
  phases: [
    { title: 'Review', detail: '4 dimension reviewers over the PR diff + repo' },
    { title: 'Verify', detail: 'adversarial refutation per finding' },
  ],
}
const REPO = '/private/tmp/claude-501/-Users-suhaan-devenv/de272aad-c620-4d71-bbdd-27dd2d3dc8af/scratchpad/sem-pr22'
const DIFF = '/private/tmp/claude-501/-Users-suhaan-devenv/de272aad-c620-4d71-bbdd-27dd2d3dc8af/scratchpad/pr22.diff'

const CTX = `You are auditing PR #22 of entire-sem (Go, tree-sitter structural extractor; schema 1.x FROZEN per ADR 0001 — output record shapes must not change; zero embeddings, zero egress; brain-bench CI gate 28/30 languages).
PR: "Fix remaining live graph extraction gaps" by ashtom. Adds: (1) Python dotted imported-module call discovery (python_calls.go pythonDottedCallImportedNames + provider.go merge into import hints, suppress external fallback when local target exists), (2) Dart property assignments as setter invocations (dart.go), (3) Haskell higher-order first-arg function registration with binder/shadowing guards (haskell.go), (4) R chained-assignment function values (parser.go walks assignment ops), (5) Perl fluent receiver calls by package type (perl.go).
The full diff is at ${DIFF} (730 lines). The PR-branch checkout is at ${REPO}. Read the diff FIRST, then read the touched files in full in the checkout, plus any callers of changed functions (grep for them). Base-branch comparison: use "git -C ${REPO} show origin/main:<path>" for the pre-PR version of any file.`

const FINDINGS = {
  type: 'object', required: ['findings'],
  properties: { findings: { type: 'array', items: {
    type: 'object', required: ['file', 'line', 'summary', 'failure_scenario', 'severity'],
    properties: {
      file: { type: 'string' }, line: { type: 'integer' },
      summary: { type: 'string', description: 'one-sentence defect statement' },
      failure_scenario: { type: 'string', description: 'concrete input source code -> wrong extraction output' },
      severity: { type: 'string', enum: ['blocker', 'major', 'minor'] },
    } } } },
}
const VERDICT = {
  type: 'object', required: ['isReal', 'reasoning'],
  properties: { isReal: { type: 'boolean' }, reasoning: { type: 'string' },
    revisedSeverity: { type: 'string', enum: ['blocker', 'major', 'minor', 'not-a-bug'] } },
}

const DIMENSIONS = [
  { key: 'correctness', model: 'opus', effort: 'xhigh', prompt: `${CTX}
Dimension: CORRECTNESS of the new extraction logic. For each of the 5 language changes, trace the code against real-world source snippets you construct: does the scanner tokenize/walk correctly (byte offsets, unicode, nested expressions, comments, strings containing lookalike code)? Are the shadowing/binder guards right (Haskell)? Is the R assignment-op walk correct for right-assign (->, ->>) where target/value sides swap? Does Python dotted-call discovery handle aliased imports (import a.b as c), relative imports, multi-dot chains (a.b.c.d()), calls inside f-strings/comments? Off-by-one in line/col? Report only defects with a concrete failing input.` },
  { key: 'regressions', model: 'opus', effort: 'xhigh', prompt: `${CTX}
Dimension: REGRESSIONS to existing behavior. The extractor previously emitted certain CALLS edges and external fallbacks; this PR changes merge/suppression logic in provider.go and parser.go shared paths. Compare against origin/main versions of provider.go, parser.go, python_calls.go: what previously-correct edges could now disappear or change resolution confidence (exact/type_inferred/name_only)? Could the new import-hint merge poison resolution for NON-dotted calls? Could the R assignment walk change extraction for non-function chained assignments (x <- y <- 5)? Could Dart setter logic double-emit for compound assignments (+=)? Schema discipline: any new relation type or field that violates frozen schema 1.x? Report only defects with a concrete failing input.` },
  { key: 'edge-cases', model: 'opus', effort: 'high', prompt: `${CTX}
Dimension: EDGE CASES + robustness. Hunt: nil/empty nodes, zero-length names, guard-clause gaps causing panics (index out of range on Children, nil FirstChild), pathological nesting depth, files with parse errors (tree-sitter ERROR nodes), duplicate emission (same call site registered twice -> duplicate CALLS edges), case sensitivity, very long identifiers. Construct the concrete source input for each suspected crash/dup. Report only defects with a concrete failing input.` },
  { key: 'tests', model: 'sonnet', effort: 'medium', prompt: `${CTX}
Dimension: TEST ADEQUACY. Read provider_test.go + haskell_test.go changes in the diff. For each of the 5 language changes: is there a regression test locking the new behavior? Is Perl fluent-receiver tested? Is the R right-assign direction tested? Is the Python alias-import case tested? Name each specific untested behavior as a finding (severity minor unless the untested path is the risky one). Do NOT report style nits.` },
]

phase('Review')
const results = await pipeline(
  DIMENSIONS,
  d => agent(d.prompt, { label: `review:${d.key}`, phase: 'Review', schema: FINDINGS, model: d.model, effort: d.effort }),
  (review, d) => parallel((review?.findings ?? []).map(f => () =>
    agent(`${CTX}
An auditor claims this defect in the PR. Adversarially VERIFY it — your default is refuted unless you can reproduce the logic trace yourself from the actual code at ${REPO}. Read the exact file+line, trace the claimed failure input through the code path step by step. If Go lets you, you may write and run a quick test in the checkout (go test ./internal/sem -run <TestName> after adding a _pr22audit_test.go; delete it after).
CLAIM (dimension ${d.key}): ${JSON.stringify(f)}
Return isReal=true ONLY if the failure scenario genuinely produces wrong output/crash on this branch.`,
      { label: `verify:${f.file}:${f.line}`, phase: 'Verify', schema: VERDICT, model: 'opus', effort: 'xhigh' })
      .then(v => ({ ...f, dimension: d.key, verdict: v }))
  ))
)
const all = results.filter(Boolean).flat().filter(Boolean)
const confirmed = all.filter(f => f.verdict?.isReal)
log(`${all.length} raw findings, ${confirmed.length} confirmed`)
return { confirmed, refuted: all.filter(f => !f.verdict?.isReal).map(f => ({ file: f.file, summary: f.summary, why: f.verdict?.reasoning?.slice(0, 200) })) }

