639	+func pythonDottedCallImportedNames(block string, importsByName map[string][]string) map[string][]string {
640	+	stripped := stripCodeLiteralsAndComments(block)
641	+	out := map[string][]string{}
642	+	for _, m := range pythonDottedCallRe.FindAllStringSubmatchIndex(stripped, -1) {
643	+		if len(m) < 4 {
644	+			continue
645	+		}
646	+		parts := pythonDottedPathParts(stripped[m[2]:m[3]])
647	+		if len(parts) < 2 {
648	+			continue
649	+		}
650	+		alias := parts[0]
651	+		imported := importsByName[alias]
652	+		if len(imported) == 0 {
653	+			continue
654	+		}
655	+		name := parts[len(parts)-1]
656	+		tail := parts[1 : len(parts)-1]
657	+		if len(tail) == 0 {
658	+			continue
659	+		}
660	+		for _, module := range pythonDottedCallModules(alias, tail, imported) {
661	+			out[name] = append(out[name], module)
662	+		}
663	+		out[name] = uniqueStrings(out[name])
664	+	}
665	+	return out
666	+}
