668	+func cloneStringSliceMap(in map[string][]string) map[string][]string {
669	+	out := make(map[string][]string, len(in))
670	+	for key, values := range in {
671	+		out[key] = append([]string(nil), values...)
672	+	}
673	+	return out
674	+}
