676	+func pythonDottedPathParts(path string) []string {
677	+	raw := strings.Split(path, ".")
678	+	parts := make([]string, 0, len(raw))
679	+	for _, part := range raw {
680	+		part = strings.TrimSpace(part)
681	+		if part == "" {
682	+			return nil
683	+		}
684	+		parts = append(parts, part)
685	+	}
686	+	return parts
687	+}
