689	+func pythonDottedCallModules(alias string, tail []string, imported []string) []string {
690	+	var modules []string
691	+	add := func(module string) {
692	+		module = strings.TrimSpace(module)
693	+		if module != "" {
694	+			modules = append(modules, module)
695	+		}
696	+	}
