698	+		module = strings.TrimSpace(module)
699	+		if module == "" {
700	+			continue
701	+		}
702	+		add(module)
703	+		if len(tail) > 0 && !strings.Contains(module, "/") {
704	+			tailSpec := strings.Join(tail, ".")
705	+			if module == alias || !strings.HasSuffix(module, "."+tailSpec) {
706	+				add(module + "." + tailSpec)
