1	// Entire — Architecture. Nav between views; each view = an architecture diagram plus
2	// (optionally) a long-form explainer (content/<id>.html) with embedded flow diagrams,
3	// a section TOC, and hoverable glossary terms. Diagrams are hand-authored D2 / SVG
4	// (architecture/diagrams), rendered by build.sh; verify.sh keeps scan-tagged nodes honest.
5	
6	let VIEWS, META, GLOSSARY = {};
7	let renderSeq = 0; // bumped per renderView; async writes from a superseded view are dropped
8	
9	async function boot() {
10	  try {
11	    const v = await fetch("views.json", { cache: "no-store" }).then(r => { if (!r.ok) throw new Error("views.json " + r.status); return r.json(); });
12	    META = v.meta || {}; VIEWS = v.views || [];
13	  } catch (e) { return bootError(e); }
14	  GLOSSARY = await fetch("glossary.json", { cache: "no-store" }).then(r => r.ok ? r.json() : {}).catch(() => ({}));
15	  document.getElementById("regions-note").textContent = META.regionsNote || "";
16	  renderNav();
17	  window.addEventListener("hashchange", route);
18	  window.addEventListener("scroll", () => document.getElementById("term-pop").classList.remove("on"), { passive: true });
19	  route();
20	}
21	
22	function bootError(e) {
23	  const el = document.getElementById("boot-error");
24	  el.hidden = false;
25	  el.innerHTML = `<strong>Could not load.</strong> ${esc(e.message)}. Serve over HTTP (<code class="mono">./serve.sh</code>); if diagrams are missing, run <code class="mono">./build.sh</code>.`;
26	  document.getElementById("view").style.display = "none";
27	}
28	
29	function renderNav() {
30	  const box = document.getElementById("nav");
31	  box.innerHTML = "";
32	  for (const v of VIEWS) {
33	    const b = document.createElement("button");
34	    b.textContent = v.title;
35	    b.dataset.view = v.id;
36	    b.onclick = () => { location.hash = "#/" + v.id; };
37	    box.appendChild(b);
38	  }
39	}
40	
41	function route() {
42	  const id = decodeURIComponent(location.hash.replace(/^#\/?/, "").split("/")[0]) || (VIEWS[0] && VIEWS[0].id);
43	  const v = VIEWS.find(x => x.id === id) || VIEWS[0];
44	  if (v) renderView(v);
45	}
46	
47	async function renderView(v) {
48	  const seq = ++renderSeq; // latest call wins; stale async writes below are dropped
49	  for (const b of document.querySelectorAll("#nav button"))
50	    b.className = "px-3.5 py-2 rounded-lg text-sm font-medium border transition " +
51	      (b.dataset.view === v.id ? "bg-slate-900 text-white border-slate-900 shadow-sm" : "bg-white text-slate-700 border-slate-200 hover:bg-slate-100 hover:border-slate-300");
52	  document.getElementById("view-title").textContent = v.title;
53	  document.getElementById("view-intro").textContent = v.intro || "";
54	  const src = document.getElementById("source");
