// Top-level nav: one button per ungrouped view, plus one button per group
// (e.g. "entire-brain"), which routes to the group's first view. A grouped
// view's siblings render as a second pill row (renderSubNav).
function renderNav() {
  const box = document.getElementById("nav");
  box.innerHTML = "";
  const seenGroups = new Set();
  for (const v of VIEWS) {
    if (v.group) {
      if (seenGroups.has(v.group)) continue;
      seenGroups.add(v.group);
      const first = VIEWS.find(x => x.group === v.group);
      const b = document.createElement("button");
      b.textContent = v.group;
      b.dataset.group = v.group;
      b.onclick = () => { location.hash = "#/" + first.id; };
      box.appendChild(b);
      continue;
    }
    const b = document.createElement("button");
    b.textContent = v.title;
    b.dataset.view = v.id;
    b.onclick = () => { location.hash = "#/" + v.id; };
    box.appendChild(b);
  }
}

function renderSubNav(v) {
  const box = document.getElementById("subnav");
  if (!box) return;
  if (!v.group) { box.innerHTML = ""; box.hidden = true; return; }
  box.hidden = false;
  box.innerHTML = "";
  for (const s of VIEWS.filter(x => x.group === v.group)) {
    const b = document.createElement("button");
    b.textContent = s.title;
    b.className = "px-3 py-1.5 rounded-full text-xs font-medium border transition " +
      (s.id === v.id ? "bg-slate-700 text-white border-slate-700" : "bg-white text-slate-600 border-slate-200 hover:bg-slate-100 hover:border-slate-300");
    b.onclick = () => { location.hash = "#/" + s.id; };
    box.appendChild(b);
  }
}

