  const d = await fetch(`diagrams/${v.id}.svg`, {method:'HEAD'});
  if (!d.ok) probs.push(`diagram 404: ${v.id}`);
  const c = await fetch(`content/${v.id}.html`, {method:'HEAD'});
  if (!c.ok && v.id !== 'overview') probs.push(`content missing: ${v.id}`);
}
