#!/usr/bin/env python3
"""graph-query: structural code lookups over an entire-graph dump (symbols + edges NDJSON).

Runs inside the task container (treated arm only). Answers "where is X / who calls X /
what does X call / outline this file" in one cheap call, instead of grep+read sweeps.

Data (env overridable):
  GRAPH_SYMBOLS=/tmp/graph.symbols.ndjson
  GRAPH_EDGES=/tmp/graph.edges.ndjson

Usage:
  graph-query def <name>            symbol definition(s): file:line kind signature
  graph-query symbols <substr>      symbols whose name contains <substr>
  graph-query file <path-substr>    outline: symbols defined in matching file(s)
  graph-query callers <name>        symbols that call/reference <name>
  graph-query callees <name>        symbols that <name> calls/references
  graph-query neighbors <name>      callers + callees
  graph-query stats                 graph size + languages
"""
import sys, os, json

SYM = os.environ.get("GRAPH_SYMBOLS", "/tmp/graph.symbols.ndjson")
EDG = os.environ.get("GRAPH_EDGES", "/tmp/graph.edges.ndjson")
CAP = int(os.environ.get("GRAPH_CAP", "40"))


def _load(path, rt):
    out, hdr = [], None
    try:
        with open(path) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    o = json.loads(line)
                except Exception:
                    continue
                if o.get("record_type") == rt:
                    out.append(o)
                elif "schema_version" in o and hdr is None:
                    hdr = o
    except FileNotFoundError:
        print(f"graph data not found: {path}", file=sys.stderr)
        sys.exit(2)
    return out, hdr


def _sym_short(s):
    return f'{s.get("file_path","?")}:{s.get("start_line","?")}  {s.get("kind","")} {s.get("name","")}'


def _print_syms(syms):
    if not syms:
        print("(none)")
        return
    for s in syms[:CAP]:
        print(_sym_short(s))
    if len(syms) > CAP:
        print(f"... (+{len(syms)-CAP} more; narrow the query)")


def main():
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(1)
    cmd = sys.argv[1]
    arg = sys.argv[2] if len(sys.argv) > 2 else ""

    if cmd == "stats":
        syms, hdr = _load(SYM, "symbol")
        edgs, _ = _load(EDG, "relation")
        langs = (hdr or {}).get("languages", [])
        print(f"symbols={len(syms)} edges={len(edgs)} languages={langs}")
        return

    syms, _ = _load(SYM, "symbol")

    if cmd == "def":
        _print_syms([s for s in syms if s.get("name") == arg or s.get("qualified_name") == arg])
    elif cmd == "symbols":
        al = arg.lower()
        _print_syms([s for s in syms if al in (s.get("name","") + " " + s.get("qualified_name","")).lower()])
    elif cmd == "file":
        _print_syms([s for s in syms if arg in s.get("file_path", "")])
    elif cmd in ("callers", "callees", "neighbors"):
        edgs, _ = _load(EDG, "relation")
        target_ids = {s["id"] for s in syms if s.get("name") == arg or s.get("qualified_name") == arg}
        if not target_ids:
            print(f"no symbol named '{arg}' (try: graph-query symbols {arg})")
            return
        by_id = {s["id"]: s for s in syms}
        res = []
        if cmd in ("callers", "neighbors"):
            for e in edgs:
                if e.get("to_id") in target_ids and e.get("from_id") in by_id:
                    res.append(("<-" + e.get("type","REF"), by_id[e["from_id"]]))
        if cmd in ("callees", "neighbors"):
            for e in edgs:
                if e.get("from_id") in target_ids and e.get("to_id") in by_id:
                    res.append(("->" + e.get("type","REF"), by_id[e["to_id"]]))
        if not res:
            print("(no edges)")
            return
        seen = set()
        for tag, s in res[:CAP]:
            key = (tag, s["id"])
            if key in seen:
                continue
            seen.add(key)
            print(f'{tag:<14} {_sym_short(s)}')
        if len(res) > CAP:
            print(f"... (+{len(res)-CAP} more)")
    else:
        print(__doc__)
        sys.exit(1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Compare baseline vs treated: resolution rate + token usage + steps, overall and per language.

Reads:
  results/<arm>/preds.json                    (which instances were attempted)
  results/<arm>/<iid>/<iid>.traj.json         (tokens, steps, cost per instance)
  *.pilot_<arm>.json  (swebench eval summary; resolved_ids)  OR logs/run_evaluation/pilot_<arm>/**/report.json
Writes results/compare.md and prints the table.
"""
import json, glob, os, statistics as st
from collections import defaultdict

ROOT = "/Users/suhaan/Documents/Coding/brain-swebench"
os.chdir(ROOT)

REPO_LANG = json.load(open("repo_lang.json")) if os.path.exists("repo_lang.json") else {}
if not REPO_LANG:
    # fallback inline (kept in sync with stratify.py)
    REPO_LANG = {
        "jqlang/jq":"C","redis/redis":"C","valkey-io/valkey":"C","micropython/micropython":"C",
        "fmtlib/fmt":"C++","nlohmann/json":"C++","caddyserver/caddy":"Go","gin-gonic/gin":"Go",
        "gohugoio/hugo":"Go","hashicorp/terraform":"Go","prometheus/prometheus":"Go",
        "apache/druid":"Java","apache/lucene":"Java","google/gson":"Java","javaparser/javaparser":"Java",
        "projectlombok/lombok":"Java","reactivex/rxjava":"Java","babel/babel":"JavaScript",
        "mrdoob/three.js":"JavaScript","axios/axios":"JavaScript","facebook/docusaurus":"TypeScript",
        "vuejs/core":"TypeScript","immutable-js/immutable-js":"TypeScript","preactjs/preact":"TypeScript",
        "briannesbitt/carbon":"PHP","laravel/framework":"PHP","php-cs-fixer/php-cs-fixer":"PHP",
        "phpoffice/phpspreadsheet":"PHP","faker-ruby/faker":"Ruby","fastlane/fastlane":"Ruby",
        "fluent/fluentd":"Ruby","jekyll/jekyll":"Ruby","jordansissel/fpm":"Ruby","rubocop/rubocop":"Ruby",
        "astral-sh/ruff":"Rust","burntsushi/ripgrep":"Rust","nushell/nushell":"Rust","sharkdp/bat":"Rust",
        "tokio-rs/axum":"Rust","tokio-rs/tokio":"Rust","uutils/coreutils":"Rust",
    }

pilot = {r["instance_id"]: r for r in json.load(open("pilot_tasks.json"))["instances"]}
lang_of = {iid: REPO_LANG.get(r["repo"], "?") for iid, r in pilot.items()}


def resolved_ids(arm):
    ids = set()
    for f in glob.glob(f"*pilot_{arm}.json"):
        try:
            ids |= set(json.load(open(f)).get("resolved_ids", []))
        except Exception:
            pass
    if not ids:  # fallback: per-instance reports
        for f in glob.glob(f"logs/run_evaluation/pilot_{arm}/**/report.json", recursive=True):
            try:
                d = json.load(open(f))
                for iid, rep in d.items():
                    if rep.get("resolved"):
                        ids.add(iid)
            except Exception:
                pass
    return ids


def traj_stats(arm, iid):
    p = f"results/{arm}/{iid}/{iid}.traj.json"
    if not os.path.exists(p):
        return None
    d = json.load(open(p))
    tin = tout = 0
    for m in d.get("messages", []):
        u = (m.get("extra") or {}).get("response", {}).get("usage") or {}
        tin += u.get("prompt_tokens", 0) or 0
        tout += u.get("completion_tokens", 0) or 0
    ms = d.get("info", {}).get("model_stats", {})
    return {"in": tin, "out": tout, "steps": ms.get("api_calls", 0), "cost": ms.get("instance_cost", 0.0)}


def collect(arm):
    res = resolved_ids(arm)
    rows = {}
    for iid in pilot:
        s = traj_stats(arm, iid)
        rows[iid] = {"resolved": iid in res, "stats": s}
    return rows


base = collect("baseline")
treat = collect("treated")


def agg(rows, iids):
    n = len(iids)
    solved = sum(rows[i]["resolved"] for i in iids)
    ins = [rows[i]["stats"]["in"] for i in iids if rows[i]["stats"]]
    outs = [rows[i]["stats"]["out"] for i in iids if rows[i]["stats"]]
    steps = [rows[i]["stats"]["steps"] for i in iids if rows[i]["stats"]]
    cost = [rows[i]["stats"]["cost"] for i in iids if rows[i]["stats"]]
    m = lambda xs: round(st.mean(xs)) if xs else 0
    return solved, n, m(ins), m(outs), m(steps), (round(sum(cost), 2))


langs = sorted(set(lang_of.values()))
lines = []
hdr = f"| {'lang':<11} | n | base✓ | treat✓ | base in-tok | treat in-tok | base out | treat out | base steps | treat steps | base $ | treat $ |"
sep = "|" + "|".join(["-" * len(c) for c in hdr.split("|")[1:-1]]) + "|"
lines += [hdr, sep]
for lg in langs + ["ALL"]:
    iids = list(pilot) if lg == "ALL" else [i for i in pilot if lang_of[i] == lg]
    if not iids:
        continue
    bs, n, bi, bo, bstp, bc = agg(base, iids)
    ts, _, ti, to, tstp, tc = agg(treat, iids)
    lines.append(f"| {lg:<11} | {n} | {bs} | {ts} | {bi} | {ti} | {bo} | {to} | {bstp} | {tstp} | {bc} | {tc} |")

out = "\n".join(lines)
print(out)
with open("results/compare.md", "w") as f:
    f.write("# Pilot: baseline vs +graph (entire-graph)\n\n" + out + "\n")
print("\nsaved results/compare.md")

