// compiles the insecure authenticator in at all.
func selectAuthenticator(ctx context.Context, cfg config.Config) api.Authenticator {
	if cfg.DevAuth {
		slog.WarnContext(ctx, "ENTIRE_GIT_META_DEV_AUTH enabled: using insecure DevAuthenticator (gitmeta_dev build only, never in production)")
