def header_stats(path):
    """Return the provider's POPULATED stats dict (symbols/relations/completeness_level/…), or {}.

    `entire graph` emits a first-line header with ZEROED stats and a separate
    `record_type=="summary"` record carrying the real counts + completeness_level (line 2 of the
    edges file; the last line of the symbols file). The older `entire sem` populated the first-line
    header directly. Prefer the summary record's stats; fall back to the first record's stats. A
    corrupt/unparseable file yields {} (itself a signal the file is unusable). Bounded: returns as
    soon as the summary is found (line 2 for edges), so it is cheap on the edges file.
    """
    header = {}
    try:
        with open(path) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    o = json.loads(line)
                except Exception:
                    # Corrupt line before a summary was found: return whatever header we have.
                    return header
                st = o.get("stats")
                if o.get("record_type") == "summary" and isinstance(st, dict):
                    return st                       # real, populated stats — always prefer this
                if not header and isinstance(st, dict):
                    header = st                     # first record's stats (zeroed for entire graph)
    except OSError:
        return {}
    return header

