def _stream_typed(target_ids, by_id, types, direction):
    """Single streaming pass returning ONLY edges whose type is in `types`, touching a target.

    The generic callers/callees query lumps all 22 edge types together under one CAP, so the
    high-value completeness relations (TESTS, IMPLEMENTS, OVERRIDES) get drowned out by the
    thousands of CALLS/USES_TYPE edges and truncated away. This surfaces one relation family
    on its own budget. Constant memory, stops at CAP.

      direction 'in'   edges pointing AT the target (to_id in targets)  -> return the source
      direction 'out'  edges FROM the target        (from_id in targets)-> return the dest
      direction 'both' both, each tagged with <- (incoming) or -> (outgoing)
    """
    res, seen = [], set()
    try:
        f = open(EDG)
    except FileNotFoundError:
        print(f"graph data not found: {EDG}", file=sys.stderr)
        sys.exit(2)
    with f:
        for line in f:
            if not line.strip():
                continue
            try:
                o = json.loads(line)
            except Exception:
                STATS["parse_errors"] += 1
                continue
            if o.get("record_type") != "relation":
                continue
            typ = o.get("type")
            if types and typ not in types:
                continue
            fid = o.get("from_id")
            tid = o.get("to_id")
            if direction in ("in", "both") and tid in target_ids and fid in by_id:
                key = ("<-" + typ, fid)
                if key not in seen:
                    seen.add(key)
                    res.append(("<-" + typ, by_id[fid]))
            if direction in ("out", "both") and fid in target_ids and tid in by_id:
                key = ("->" + typ, tid)
                if key not in seen:
                    seen.add(key)
                    res.append(("->" + typ, by_id[tid]))
            if len(res) >= CAP:
                break
    return res


