}

// TestFactsSyncPullsHostedSettlementIntoLocalFacts is the regression for the
// "accepted settlements don't stick" defect: a teammate settling a conflict on
// the hosted queue used to leave the losing member's local facts untouched, so
// the next keep-both Promote re-added the retired fact and re-raised the same
// conflict under a fresh id — an unresolvable loop.
func TestFactsSyncPullsHostedSettlementIntoLocalFacts(t *testing.T) {
	f, fake, _ := newHostedProposalsFixture(t)
	fake.mu.Lock()
	fake.proposals = nil
